INSERT INTO public.concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES 
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando o disposto na Constituição Federal e o entendimento consolidado do Supremo Tribunal Federal (STF) acerca dos direitos e garantias fundamentais, julgue o item a seguir: O direito à vida, garantido constitucionalmente, é absoluto, não admitindo qualquer tipo de relativização ou mitigação, seja em tempo de paz ou em estado de guerra, o que fundamenta a proibição absoluta de pena de morte no ordenamento jurídico brasileiro.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Nenhum direito fundamental é absoluto, nem mesmo o direito à vida. A própria Constituição Federal autoriza, excepcionalmente, a pena de morte em caso de guerra declarada (art. 5º, XLVII, ''a'', da CF). Além disso, há o instituto da legítima defesa que, em casos concretos, exclui a ilicitude quando há violação do direito à vida por repulsa a injusta agressão.","difficulty":"facil","tags":["Direito à Vida","Relatividade dos Direitos","Pena de Morte"]}'::jsonb, 'draft', 'wq9snc', 1),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando o entendimento doutrinário e jurisprudencial acerca dos remédios constitucionais, julgue: O habeas data é instrumento adequado para buscar o acesso a informações contidas em bancos de dados de caráter público, estendendo-se também para retificar dados inexatos. Contudo, ele não é a via adequada para pleitear, contra órgão estatal, o acesso a processo administrativo do qual o impetrante faz parte, devendo-se utilizar, nesse caso, o mandado de segurança.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. De acordo com o STF e a Súmula Vinculante 14, o acesso aos autos de processo administrativo ou inquérito por parte do advogado do interessado é um direito garantido. Contudo, a recusa no fornecimento dessa informação não enseja Habeas Data (que protege informações pessoais restritas em bancos de dados), mas sim Mandado de Segurança, pois fere direito líquido e certo à informação e acesso pleno ao processo.","difficulty":"medio","tags":["Habeas Data","Mandado de Segurança","Processo Administrativo"]}'::jsonb, 'draft', 'gt1h04', 2),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"No tocante à inviolabilidade do domicílio protegida pelo artigo 5º, inciso XI, da Carta Magna, julgue o próximo item: É lícito o ingresso forçado de autoridade policial, sem mandado judicial, durante a noite, no domicílio de um suspeito, desde que haja fundadas razões (justa causa) prévias baseadas em elementos objetivos que indiquem a presença de situação de flagrante delito no interior da residência.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O Supremo Tribunal Federal fixou tese em sede de repercussão geral (Tema 280) determinando que a entrada forçada em domicílio sem mandado judicial é lícita, seja de dia ou de noite, desde que amparada em fundadas razões, devidamente justificadas pelas circunstâncias do caso concreto, que indiquem que dentro da casa ocorre ou está para ocorrer um crime (flagrante delito).","difficulty":"medio","tags":["Inviolabilidade do Domicílio","Flagrante Delito","Justa Causa"]}'::jsonb, 'draft', 'eyocw6', 3),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"A respeito das garantias dadas pela Constituição aos indivíduos em situação de persecução penal, julgue: A garantia constitucional contra a autoincriminação (nemo tenetur se detegere) abrange apenas o direito ao silêncio durante o depoimento, não eximindo o investigado de ceder compulsoriamente amostras de material genético (DNA) ou participar do reconhecimento pessoal e da reconstituição simulada dos fatos.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O princípio da não autoincriminação abrange não apenas o direito ao silêncio, mas também o direito de o indivíduo não ser obrigado a produzir provas contra si mesmo que exijam sua cooperação ativa ou invasiva. Por isso, ele não pode ser coagido a fornecer material biológico ou participar forçosamente da reconstituição dos fatos contra a sua vontade.","difficulty":"medio","tags":["Sistemas de Persecução","Não Autoincriminação","Provas"]}'::jsonb, 'draft', 'pwm7p7', 4),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a afirmação de acordo com o entendimento consolidado dos tribunais sobre a inviolabilidade da honra e da imagem: Sendo a liberdade de expressão uma garantia constitucional fundamental e base do Estado Democrático de Direito, o uso não autorizado de biografia de pessoa com projeção social independe de sua autorização prévia, não sendo cabível o recolhimento forçado da obra do mercado sob alegação genérica de ofensa à honra.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme decisão emblemática do STF (ADI 4815), é inconstitucional a exigência prévia de autorização da pessoa biografada para a publicação e circulação de biografias, privilegiando-se a liberdade de expressão e de acesso à informação. O direito à honra e imagem é reparado, a posteriori, via ação de responsabilização civil ou penal caso haja abuso ou difamação, não se admitindo a censura prévia.","difficulty":"facil","tags":["Liberdade de Expressão","Direito à Imagem","Biografias"]}'::jsonb, 'draft', 'u4yblq', 5),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"De acordo com o texto constitucional pertinente aos direitos da nacionalidade e extradição, julgue o item: O brasileiro naturalizado que cometer um crime comum gravíssimo, tipificado como hediondo, pouco antes de sua efetiva naturalização, não poderá ser submetido a processo de extradição caso este seja pleiteado por governo estrangeiro, haja vista a proteção irrestrita da extradição garantida a todos que detém a condição de brasileiro.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O art. 5º, LI da CF estabelece que nenhum brasileiro será extraditado, SALVO o naturalizado, em caso de crime comum praticado ANTES da naturalização, ou de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, na forma da lei. Logo, ele poderá sim ser extraditado na situação hipotética narrada.","difficulty":"medio","tags":["Extradição","Brasileiro Naturalizado","Direitos Constitucionais"]}'::jsonb, 'draft', 'rfcksd', 6),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando as diretrizes normativas do direito de propriedade, julgue o item a seguir: O Estado poderá, em caso de perigo público iminente, usar a propriedade de indivíduo sem a necessidade de mandado judicial prévio ou autorização consentida do proprietário, estando o erário público isento do dever de reparar financeiramente o dono da propriedade em todos os casos de uso justificado pela excepcionalidade pública.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O art. 5º, XXV da Constituição assevera que, em caso de perigo público iminente, a autoridade competente poderá usar de propriedade particular (requisição administrativa), MANTENDO, contudo, a garantia ao proprietário de uma indenização ulterior, apenas se houver o advento de um dano real e quantificável à referida propriedade.","difficulty":"facil","tags":["Requisição Administrativa","Direito à Propriedade","Intervenção do Estado"]}'::jsonb, 'draft', '3icdy4', 7),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Sobre a abrangência e os titulares dos Direitos e Garantias Fundamentais esculpidos no artigo 5º da CF/88, julgue o item: A doutrina e a jurisprudência majoritárias estabelecem que a titularidade de direitos garantidos no caput do artigo 5º abrange os estrangeiros transitoriamente presentes no território nacional, sendo equivocado dizer que a referida norma constitui privilégio restrito exclusivamente aos residentes.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O STF já consolidou o entendimento pacífico de que, apesar de o texto da Constituição referir-se expressamente aos ''estrangeiros residentes'', a garantia à vida, segurança, honra e propriedade também ampara estrangeiros que estejam no país transitoriamente (como turistas ou de passagem), sob pena de ofensa frontal aos Direitos Humanos universais e à dignidade da pessoa.","difficulty":"facil","tags":["Caput do Art. 5º","Titularidade","Estrangeiros"]}'::jsonb, 'draft', 'myncp2', 8),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Aprofundando as bases do instituto jurídico da interceptação telefônica e telemática sob as diretrizes constitucionais e o entendimento do STF, julgue: É defeso, por ofensa ao artigo 5º, inciso XII da Constituição, a utilização das informações sigilosas obtidas mediante interceptação telefônica lícita em processo conexo sob formato de ''prova emprestada'', ainda que se destinem a instruir processos cíveis em tramitação.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O STF autoriza o que a doutrina técnica chama de ''serendipidade'' ou ''encontro fortuito de provas'', bem como permite a utilização do elemento da interceptação (originalmente validado por ordem judicial para investigação criminal) como prova emprestada para deflagrar processo ético-administrativo disciplinar e, eventualmente, cível/improbidade, desde que respeitados os rigores do contraditório.","difficulty":"dificil","tags":["Interceptação Telefônica","Prova Emprestada","STF"]}'::jsonb, 'draft', 'ns8u0e', 9),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Acerca das liberdades fundamentais, em peculiar, o direito de reunião consubstanciado no artigo 5º, inciso XVI da Constituição da República Federativa do Brasil de 1988, julgue: A realização de uma reunião associativa ou política pacífica em espaço público submete-se ao prévio aviso à autoridade do Poder Executivo administrativo para efeitos de organização logística, porém, não prescinde da efetiva autorização outorgada pelo Estado caso o local coincida com grandes rotas arteriais.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A Constituição expressamente afirma que as reuniões são ''independentes de autorização'', não podendo o Estado obstar uma manifestação sob a simples desculpa administrativa de congestionamento de rotas. O STF, aliás, definiu no RE 806339 (com repercussão geral) que até mesmo o aviso prévio não requer formulação rígida, bastando que ocorra por meios eficientes que notifiquem o ente público da manifestação.","difficulty":"medio","tags":["Direito de Reunião","Aviso Prévio","Autoridade Competente"]}'::jsonb, 'draft', '1232t1', 10),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando o princípio da isonomia consagrado no caput do art. 5º da CF/88, julgue: A adoção de critérios diferenciados para a promoção de integrantes de carreiras militares baseados unicamente em cotas de gênero para o acesso aos quadros de oficiais combatentes é considerada, pelo Supremo Tribunal Federal, plenamente compatível com o princípio da igualdade material, justificando-se pela necessidade histórica de nivelamento ostensivo das patentes.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O STF, em ações recentes (ADIs contra polícias militares de vários estados), firmou entendimento de que a destinação de vagas exclusivas ou a limitação de percentuais máximos (como 10%) para mulheres em concursos públicos de carreiras de segurança pública militar viola frontalmente o princípio da isonomia/igualdade, por configurar discriminação de gênero injustificada, não caracterizando medida de ''nivelamento''.","difficulty":"medio","tags":["Princípio da Isonomia","Carreiras Militares","Cotadas de Gênero","STF"]}'::jsonb, 'draft', 'b28xod', 11),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"A respeito do direito fundamental ao esquecimento no ordenamento jurídico brasileiro, julgue: O Supremo Tribunal Federal reconheceu o direito ao esquecimento como um direito fundamental implícito, derivado da dignidade da pessoa humana, permitindo a desindexação em motores de busca de informações verídicas e lícitas, desde que o lapso temporal transcorrido seja suficiente para afastar o interesse público atual sobre o fato penal anterior.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O STF, no julgamento do RE 1010606 (Tema 786), decidiu que o ''direito ao esquecimento'' é incompatível com a Constituição Federal. A Corte considerou que apagar fatos verídicos publicados em meios de comunicação (quando obtidos licitamente) com base no mero transcurso do tempo viola a liberdade de expressão e o direito à informação, sendo inadmissível censura prévia.","difficulty":"medio","tags":["Direito ao Esquecimento","Liberdade de Expressão","STF"]}'::jsonb, 'draft', 'qf1mhl', 12),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Acerca da inviolabilidade do sigilo da correspondência e das comunicações telegráficas, de dados e das comunicações telefônicas, julgue: É admitida a quebra do sigilo de dados bancários e fiscais diretamente por comissões parlamentares de inquérito (CPIs) federais e estaduais, por força de seus poderes de investigação próprios de autoridades judiciais, não sendo extensível essa prerrogativa, contudo, a CPIs instaladas em âmbito municipal.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O STF reconhece que as CPIs Federais e Estaduais detêm poderes de investigação equiparados aos das autoridades judiciais (art. 58, § 3º, CF), podendo determinar diretamente a quebra de sigilo bancário, fiscal e de dados telefônicos (não a escuta/interceptação das comunicações, que é reserva de jurisdição). Contudo, essa prerrogativa de quebra direta não se estende às CPIs Municipais, que precisam recorrer ao Judiciário (por ausência de previsão de ''autoridade judicial'' de primeira instância sob a alçada direta municipal em face da reserva de magistratura estadual e federal).","difficulty":"dificil","tags":["CPI","Quebra de Sigilo Bancário","Poderes de Investigação"]}'::jsonb, 'draft', 'fcssvd', 13),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"No que concerne ao tribunal do júri, cuja instituição é reconhecida constitucionalmente (art. 5º, XXXVIII), julgue o item: É competência absoluta do Tribunal do Júri o julgamento dos crimes dolosos contra a vida. Portanto, havendo prerrogativa de foro prevista exclusivamente em Constituição Estadual de um Procurador de Estado que venha a cometer homicídio doloso, esta não prevalecerá sobre a competência do Tribunal do Júri, que tem assento na Constituição Federal.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. De acordo com a Súmula Vinculante 45 do STF, ''A competência constitucional do Tribunal do Júri prevalece sobre o foro por prerrogativa de função estabelecido exclusivamente pela Constituição Estadual''. A exceção ocorre apenas se a prerrogativa do foro for estabelecida expressamente pela própria Constituição Federal.","difficulty":"medio","tags":["Tribunal do Júri","Súmula Vinculante 45","Prerrogativa de Função"]}'::jsonb, 'draft', '15f88l', 14),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a assertiva com base nas regras constitucionais sobre extradição, expulsão e deportação: A proibição de extradição de brasileiro nato é cláusula pétrea e garantia fundamental absoluta. Entretanto, a jurisprudência do Supremo Tribunal Federal tem flexibilizado essa restrição, permitindo a extradição nos casos em que o brasileiro nato abdica formalmente da nacionalidade para obter outra, transformando-se tecnicamente em estrangeiro no momento do delito.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. A Constituição impede a extradição de brasileiros natos. No entanto, o STF já julgou o paradigmático caso ''Cláudia Hoerig'' (MS 33864), onde uma brasileira nata que voluntariamente se naturalizou norte-americana (abdicando expressamente da nacionalidade brasileira de forma voluntária, antes da flexibilização da EC 131/2023 sobre os critérios de perda) perdeu o status de nata. Com isso, após cometer crime nos EUA e fugir para o Brasil, ela foi legalmente tratada como estrangeira e teve seu pedido de extradição autorizado e julgado procedente pelo Supremo Tribunal Federal.","difficulty":"dificil","tags":["Extradição","Brasileiro Nato","Perda de Nacionalidade"]}'::jsonb, 'draft', 'djcyfh', 15),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"A respeito dos direitos e deveres individuais e coletivos contidos na CF/88 e sob a ótica da consolidação jurisprudencial em matéria penal: A prisão civil por dívida no Brasil, sob a imposição dos Tratados de Direitos Humanos incorporados ao ordenamento pátrio, sofreu decréscimo drástico em seu rol de hipóteses validas, subsistindo de forma exclusiva ao devedor inescusável de prestação alimentícia de urgência perene, sendo expressamente banida e vedada, sumuladamente, a prisão coercitiva do falido devedor solidário de obrigações tributárias, mas permitida a prisão do depositário infiel apenas por convenção em juízo civil.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Segundo a Súmula Vinculante 25 do STF (''É ilícita a prisão civil de depositário infiel, qualquer que seja a modalidade do depósito''), a prisão civil do depositário infiel é totalmente banida do ordenamento jurídico brasileiro, independentemente se prevista em lei, convenção ou pacto anterior. Após a incorporação do Pacto de San José da Costa Rica (que tem status supralegal), a única hipótese remanescente e constitucionalmente válida de prisão civil no Brasil é a do devedor inescusável e voluntário de obrigação alimentícia.","difficulty":"medio","tags":["Prisão Civil","Depositário Infiel","Súmula Vinculante 25"]}'::jsonb, 'draft', 'f9dnvp', 16),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Em conformidade com a salvaguarda do Júri preconizada no art. 5º, inciso XXXVIII da Constituição, sob o crivo de tribunais superiores: O princípio institucional da soberania dos veredictos impossibilita, em regra formal de exceção preclusiva, a revisão criminal de julgamentos absolutórios operados pelos jurados após a ocorrência de trânsito em julgado material mesmo sob prova inconteste do cometimento do dolo letal. Todavia, esse mesmo princípio constitui limite vertical intransponível para a aplicação reformatória integral de um acórdão de segundo grau perante veredicto condenatório injusto, restando vedada a anulação para novo júri salvo prova cabal técnica flagrante.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O STF e STJ firmaram entendimento que a ''soberania dos veredictos'' cede e mitiga perante o direito pátrio favorável ao réu. Assim, é perfeitamente cabível a ''Revisão Criminal'' para desfazer um veredicto condenatório do Júri transitado em julgado, podendo o próprio juízo monocrático ou colégio revisor, caso encontre prova inconteste de inocência e manifesta injustiça (decisão manifestamente contrária às provas), promover a absolvição ou novo júri em benefício do réu. Já em julgamento absolutório, por força de proteção à coisa julgada em prol do réu (vedação a revisão pro societate), este não pode ser submetido à revisão penal condenatória após o trânsito.","difficulty":"dificil","tags":["Tribunal do Júri","Soberania dos Veredictos","Revisão Criminal"]}'::jsonb, 'draft', 'cxohg9', 17),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a proposição sobre as excludentes e escusas protetivas às penalidades: A Constituição Federal assegura, como direito inato irrestrito de proteção à família, que o acusado penal de um delito detém o direito imutável de escusa desobrigatória judicial de depor incisivamente debaixo de compromisso legal perante inquéritos policiais federais caso o indiciado sob apuração constitutiva seja seu próprio cônjuge (esposo/esposa), salvo se a omissão da tipicidade for elemento de conivência primária da fraude criminosa ou infração letal dolosa aos menores.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O direito ao silêncio mitigado se expande ao amparo às relações familiares (art. 206 do CPP e derivação protetiva constitucional). Ninguém (cônjuge, pais, filhos) é forçosamente compelido a depor sob compromisso de dizer a verdade contra seu próprio e íntimo familiar-parceiro caso esse decida por se escusar do testemunho. No entanto, se não houver outra de aferir o crime cabal e eles não forem os alvos secundários da fraude/crimes violentos contra vulneráveis protegidos da mesma teia, a lei prevê que o Estado poderá colher as informações sob o status apenas de ''declarante'', sem a obrigação formal tipificada de falso testemunho.","difficulty":"medio","tags":["Escusa de Testemunho","Relações Familiares","Não Autoincriminação"]}'::jsonb, 'draft', '1choi', 18),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"No contexto da interceptação das telecomunicações: Segundo o delineamento da Corte Suprema em tema de repercussão, é prescindível e abdicável a emissão de prévia notificação mandamental assinada e circunstanciada em papel estrito por Magistrado de primeiro grau, podendo ser deferida ou convalidada verbalmente a interceptação telefônica e dos dados e-mailísticas em situações singulares e flagrantes criminosas de premente celeridade como a ocorrência fática de extorsão mediante sequestro da liberdade corporal em zona de conflito e isolada jurisdição criminal.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A quebra de sigilo das comunicações telefônicas é instituto abrangido pela Cláusula de Reserva de Jurisdição absoluta (art. 5º, XII, da CF). A lei nº 9.296/96 (art. 5º. Parágrafo único) obriga expressamente, até mesmo em casos de máxima urgência extremada, a necessidade de representação material e decisão MÍNIMA do juiz competente. Embora excepcionalmente o juiz possa deferir ou expedir a quebra em regime de plantão extraoficial via comunicação em ofícios (eletrônicos ou congêneres) por extrema urgência/risco humanitário e validando na formalização consecutiva até 24h depois, a quebra de comunicações JAMAIS pode nascer originariamente ''abdicada ou não escrita formalmente'' pelo próprio juiz investido ou ser convalidada a posteriori por autoridade policial.","difficulty":"dificil","tags":["Interceptação Telefônica","Reserva de Jurisdição","Ordem Judicial"]}'::jsonb, 'draft', '1pt1fy', 19),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue em face dos direitos individuais na Constituição: A interceptação de comunicações estabelecida por determinação judicial exara em restrito cunho as comunicações de voz sobre redes ativas de telefonia comutada de espectro eletromagnético estrito de fala; enquanto que o simples tráfego, rastreamento físico de antenas e o registro do conteúdo pré-visualizável contido na modalidade de aplicativos de mensagens instantâneas abertos pela interface do aparelho (tipo Whatsapp e aplicativos homólogos textuais armazenados no interior) são tipificados inequivocamente como quebra de dados no âmbito das comunicações lícitas do direito de telemática da internet penal, também sujeitos a ordem de magistratura prévia.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme jurisprudência do STJ e STF, o acesso a dados contidos em aplicativos de mensagens (WhatsApp, Telegram) não se confunde com ''escuta'' ou ''interceptação'' síncrona/ao vivo stricto sensu de voz da Lei 9.296. Enquadra-se tecnicamente como ''quebra de dados telemáticos/informáticos'' ou apreensão e extração de dados contidos na memória do aparelho. Entretanto, justamente por violar a intimidade das comunicações gravadas e os dados de fluxo da interface (MCI - Marco Civil da Internet), é categoricamente imprescindível e necessária a prévia autorização judicial específica para o devassamento dessas caixas diretas em apreensões policiais, sem fito de flagrante imediato ou perigo inescusável da prova.","difficulty":"dificil","tags":["Sigilo de Dados Telemáticos","WhatsApp","STF","Ordem Judicial"]}'::jsonb, 'draft', 'ssdd85', 20),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"A respeito dos direitos e garantias fundamentais previstos na Constituição Federal de 1988, julgue: O direito fundamental à saúde, positivado na Constituição, impõe ao Estado, em todas as suas esferas governamentais (União, Estados, DF e Municípios), o dever irrestrito de fornecer medicamentos de alto custo não incorporados aos atos normativos do Sistema Único de Saúde (SUS), sob pena de afronta à dignidade da pessoa humana e inversão do ônus fundamental da vida pelo pacto federativo subsidiário aos entes originários constitucionais.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Supremo Tribunal Federal, ao julgar o Tema 6 das Repercussões Gerais (RE 566471), definiu tese vinculante no sentido de que o Estado, como regra formal e geral restrita, NÃO é obrigado a fornecer medicamentos de alto custeio desvinculados de forma prévia ou expurgados das listas padronizadas ou Relação Nacional do SUS. Isso comporta exceções restritíssimas que devem ser comprovadas por prova irrefutável de hipossuficiência técnica e material e aprovação da ANVISA restrita sem tratamentos correlatos paralelos no SUS.","difficulty":"medio","tags":["Direito à Saúde","Medicamentos de Alto Custo","SUS","STF"]}'::jsonb, 'draft', 'siiemc', 21),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Quanto à aplicação dos direitos metaindividuais e coletivos protocolares da Magna Carta de 88: O Mandado de Injunção coletivo é instrumento essencial de defesa cívico-social; não obstante o rigor instrumental da lei primacial que exige carência lacunosa estrita do legislativo a obstar fruição da cidadania originária, um partido político nacional que conte com plena e irrestrita representatividade, isto é, que tenha representação exclusiva no Senado Federal e careça manifestamente de deputados ativos no Parlamento da Câmara dos Deputados, possui taxativa legitimidade canônica material para propor validamente esse instituto coletivo injuncional perante a Corte impetrante.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme disposto de forma convergente no próprio texto da Constituição no art. 5º, LXX, ''a'' (que baliza analogicamente os requisitos para mandado de segurança coletivo aplicáveis pacificamente ao mandado de injunção estatuído pela Lei 13.300/2016), o requisito essencial ao Partido Político é possuir ''representação no Congresso Nacional''. A existência de ao menos um mísero e único representante ativo (Senador ou Deputado) em QUALQUER de ambas as Casas isoladamente configura legitimidade suficiente do partido no Congresso Brasileiro.","difficulty":"dificil","tags":["Mandado de Injunção Coletivo","Partido Político","Congresso Nacional"]}'::jsonb, 'draft', 'j4ybl4', 22),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Tendo em vista o entendimento do Supremo Tribunal Federal acerca das relações de isonomia penal consubstanciadas no Direito Individual Constitucional do Indivíduo, julgue: É defeso e inconstitucional por afronta escandalosa ao Princípio da Proteção da Igualdade da Maternidade Subordinativa Cívica na Constituição da República, a concessão e transmutação isolada unânime da prisão preventiva da detenta que seja simplesmente gestante em prisão humanitária e estrita domiciliar em razão impositivo do fato gerador gravídico se a mesma foi processada e incursionada validamente pelo delito penal de tortura.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O Supremo Tribunal Federal (nos autos do emblemático HC coletivo 143.641) e, posteriormente, a conformação legislativa consolidada no art. 318-A do Código de Processo Penal, determinam a substituição premente da prisão processual (preventiva) por prisão domicial da mulher gestante ou mãe de menores. HÁ, NO ENTANTO, duplas EXCEÇÕES irremovíveis: ela não terá esse ''prêmio'' domiciliar substitutivo se praticou crimes dolosos contra as Vítimas Descendentes (filhos), ou se o crime a ela imputado reveste-se das nuances de cometimento ou requintes COM VIOLÊNCIA ou GRAVE AMEAÇA contra qualquer outra pessoa humana no território (sendo a tortura penal exatamente um crime intrinsecamente envolto em violência estrita inafastável).","difficulty":"dificil","tags":["Prisão Preventiva","Gestantes","Crimes com Violência","Direitos Fatais Individuais"]}'::jsonb, 'draft', 'iynexx', 23),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"No contexto atinente aos prazos constitucionais rigorosos das ações constitucionais de viés cível-penal, os denominados e consagrados Remédios Constitucionais do rol civil na Constituição (Habeas Corpus, Mandado de Segurança, Ação Popular de lesa-pátria): Salvo nos rigores de decadência estipulados para impetração do Mandado de Segurança repressivo no bojo fixo legal em contados exatos de 120 (cento e vinte) dias interpostos sob rito do silêncio do Estado autoritário, consagra-se que a impetração originária de Ação Popular Cidadã visando taxativa a anulação canônica primária de atos que agridam e desonrem o erário financeiro do munícipio goza da total de intemporalidade civil, isto é, de prazo e carência imprescritível frente do tempo a qualquer termo geracional por gravidade do ofício público aviltado.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Com base expressa no diploma regulamentador cabível a este instrumento (a Lei federal imperativa nº 4.717/65 – Lei de Ação Popular em seu art. 21), a Ação Popular protetiva NÃO É instrumento infindo ou imprescritível no universo processual estancável. A pretensão estrita à anulação dos ditos atos geradores patrimoniais espúrios que ofendam substancialmente o patrimônio público exara PRESCRIÇÃO imperativa finda num prazo prescricional explícito decaído de exator 5 (cinco) anos absolutos, a ser contado sem escusa normativa do instante imediato formal da mera publicação regular impressa do ato materializado e reputado por ela combatido na exatidão municipal governamental.","difficulty":"medio","tags":["Ação Popular","Remédios Constitucionais","Prescrição"]}'::jsonb, 'draft', '56dc2w', 24),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando o panorama estrutural garantista insculpido e consagrado sumuladamente e que abrange o mandamento de extradição nos domínios estritos da Magna Carta da República em torno das hipóteses criminais relativas exclusivas dos indivíduos tipificados passíveis, julgue: O brasileiro nato residente habitual na Espanha não poderá ser legalmente deportado coercitivamente daquela nação por mero cometimento irregular das normativas civis imigratórias estritas do país estrangeiro de destino (visto), caso não apresente histórico estrito correlato de condenação do juízo federal nacional.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Trata-se de uma indução confusa, técnica e ''pegadinha'' doutrinária do termo, peculiar de construções avaliativas do CESPE. Na exegese constitucional do rol (art 5, LIX e LI), a proteção magna e cívica brasileira referenciada recai estritamente sob vetar ou impedir a EXTRADIÇÃO em desfavor do NATO pelo próprio Brasil ao repassá-lo sob litígio penal para o estrangeiro. Se um cidadão nativo habita e desrespeita irregularmente o rol imigratório das leis diplomáticas do estrangeiro, a DEPORTAÇÃO é um mero e legítimo ato repassado pelo Estado estrangeiro hospedeiro visando sua expulsão de seu solo local impune. A deportação em curso no país estranho independe e passa a léguas da condenação federal prévia brasileira ou do instituto e guarida interna constitucional de ''extradição''.","difficulty":"dificil","tags":["Extradição","Deportação","Brasileiro Nato"]}'::jsonb, 'draft', '1ua8ve', 25),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"A respeito do direito fundamental ao meio ambiente ecologicamente equilibrado, previsto no art. 225 da CF, e sua interface com o direito de propriedade: O STF consolidou entendimento de que a reserva legal florestal e a limitação administrativa de proteção ambiental em propriedades rurais não configuram desapropriação indireta ou apossamento administrativo, posto que constituem mero condicionamento lícito do pleno exercício material do direito de propriedade (função socioambiental), sendo indevida a exigência de uma indenização estatal compensatória pela mera vedação de exploração irrestrita dessa reserva imposta.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme jurisprudência remansosa do Superior Tribunal de Justiça e ratificada em preceitos fundamentais da Corte Suprema, as restrições ao direito de propriedade decorrentes da estrita e cogente proteção constitucional ambiental (como a averbação impositiva e manutenção do percentual de reserva legal previsto no Código Florestal nas propriedades agrárias) configuram autênticas limitações administrativas garantidoras da estrita função social-ambiental pregressa da propriedade particular (art. 5º, XXIII e 170, VI da CF). Desse modo, a mera criação normativa ou proteção do percentual intocável, de per se, não acarreta o famigerado esvaziamento econômico total da gleba caracterizador de desapropriação indireta e, por isso mesmo amparo principiológico e limitador, isenta solidamente os cofres do ente federativo do pagamento de qualquer rubrica indenizatória reparatória civil ao proprietário agrário restrito.","difficulty":"medio","tags":["Direito de Propriedade","Meio Ambiente","Reserva Legal","Função Social","Desapropriação Indireta"]}'::jsonb, 'draft', 'd5nuq', 26),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue à luz das restrições e tutelas garantistas aos Direitos e Garantias Fundamentais da Liberdade de Locomoção: Encontra guarida expressa nas premissas constitucionais e nas balizas das súmulas protocolares do STF o uso cautelar absoluto do Habeas Corpus como instrumento para trancar ou impetrar salvo-conduto preventivo genérico a favor de grupos indeterminados (como todos os cidadãos de um reduto eleitoral sob intervenção policial estadual), dispensando a individualização técnica estrita do paciente material passível do risco iminente de coação originária estatal.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Supremo Tribunal Federal, sob a exegese histórica protetiva de limitação aos limites incertos normativos, firmou pacífico e sólido entendimento de que é peremptoriamente incabível, materialmente nulo e juridicamente inidôneo figurar a impetração fática preventiva de ''Habeas Corpus Genérico''. Para que a coação na liberdade de ir e vir (ou mesmo nos salvo-condutos) enseje a competência deflagradora do remédio heróico, se perfaz como condição material inafastável de ajuizamento a estrita comprovação individualizada ou, ao menos, a determinabilidade exaustiva cabal na identificação nominada plúrima dos pacientes afetos ao alegado ou real risco constritor autoritário. Proteções genéricas não-individualizadas cabem aos âmbitos impetrados pelo mandado de segurança coletivo ou ações civis da cidadania abstrata.","difficulty":"dificil","tags":["Habeas Corpus Preventivo","Liberdade de Locomoção","Individualização do Paciente","STF"]}'::jsonb, 'draft', 'cj8n6e', 27),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando as regras limitadoras fixadas na Magna Carta e em instrumentos internacionais sobre a execução material constritivo-penal na dignidade do ser: A Constituição Federal de 1988 extirpou integralmente do território brasileiro as penas atreladas com banimento cívico, trabalho forçado maciço e tortura capital, mas no que se refere ao instituto ressocializante estrito da prisão celular ou reclusão canônica, admite-se como plenamente harmônica sob a jurisprudência criminal a aplicação cautelar de pena em formato de prisão estrita de caráter perpétuo quando a reincidência de mortes por homicidas psicopatas atestados psiquiatricamente for material classificada de irrecuperável e de máximo de periculosidade atroz no crivo da reiteração fatal sem limites da prescrição temporal.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A vedação contida explicitamente no Art. 5º, inciso XLVII, alínea ''b'' da Constituição Federal assevera, sem nenhuma estipulação ou lacuna de mitigação no quadro excepcional de psicopatologias irrefréáveis atestadas (ou qualquer outro fato criminal brutal no contexto de psicopatas assassinos com risco extremo e comprovado), que no estrado jurisdicional pátrio NÃO HAVERÁ sob nenhuma conjuntura a aplicação de penas submetidas ao caráter e à dimensão de ''PRISÃO PERPÉTUA''. O máximo tempo de unificação do cumprimento restritivo privativo celular foi até estipulado pelo Pacote Anticrime (Lei nº 13.964/2019) em exatos rígidos e findáveis 40 (quarenta) anos, impondo o livramento forçoso natural superado esse lapso material, indiferente à altíssima periculosidade diagnosticada atrelada.","difficulty":"medio","tags":["Prisão Perpétua","Sistemas de Penas","Pacote Anticrime","Vedação Constitucional"]}'::jsonb, 'draft', '9djpdr', 28),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a proposição fundamentada na Liberdade Cívica e proteção das associações civis: Por obediência dogmática originária e amparo hermenêutico à prerrogativa inerente aos regimentos essenciais consubstanciados na liberdade inviolável de associação autônoma (CF/88, art. 5º, XVII a XXI), nenhuma pessoa humana será compulsoriamente forçada materialmente ou constrangida financeiramente a filiar-se, tampouco a permanecer agrilhoada e associada em entidade de classe ou corporativa fechada particular de bairros, mesmo que preste e detenha monopólio ostensivo explícito de utilidade provedora privada a um condomínio imobiliário local de lotes do qual é condômina proprietária base.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O STF entalhou e estribou essa limitação com Repercussão Geral fixando tese cabal impositiva: As taxas de conservação, recolhimento material lixeiro e manutenção ou contribuições financeiras ordinárias diversas cobradas rotineiramente em virtude de suposto benefício geral contábil, e que sejam de cunho cobrador fixado por associações de moradores de loteamentos imobiliários e condomínios fechados horizontais, NÃO OBRIGAM legal ou coativamente aos indivíduos natos e moradores adquirentes locais os quais rigorosamente e formalmente nunca concordaram aderir, não se filiaram no registro imobiliário de antemão ou já pleitearam o desligamento unilateral. A cobrança compulsória contra a vontade atrai a inconstitucionalidade plena e vulnera escandalosamente o núcleo essencial preceito sagrado cívico e de livre desassociação exposto no artigo 5º, XX (''Ninguém poderá ser compelido a associar-se ou a permanecer associado'').","difficulty":"dificil","tags":["Liberdade de Associação","Associação de Moradores","Condomínio de Lotes","Cobrança Compulsória","Tema 492 do STF"]}'::jsonb, 'draft', 'sk5y4', 29),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Analise detidamente as garantias e instrumentos voltados ao asseguramento do direito inerente à obtenção expedita de certidões estendidas no serviço prestado a cidadania: O indeferimento injustificado, a morosidade e silêncio infundado da negativa ou a abstenção da via administrativa de outorgar certidões em repartições públicas civis a respeito e a defesa rotineira material da honra base de direitos singulares subjetivos em trâmite pessoal alheio constitui ofensa restritiva originária ao art. 5º, XXXIV, ''b''. Todavia, a única via protocolar cabível na Corte Magna de proteção curativa e repressão que sana e corrige essa recusa formal específica recai maciça e dogmaticamente e exclusivamente no habeas data corretivo, por configurar omissão à guarda do banco de bases de sigilos restritos ao munícipe particular.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Habeas Data goza de aplicabilidade irrestritamente fincada para assegurar restritamente o CONHECIMENTO imediato de INFORMAÇÕES atinentes, intrínsecas e pessoais à figura estrita do IMPETRANTE localizadas contíguas materialmente em bancos físicos ou nos registros e dados em nuvem de entidades estatais dotadas estritamente e declaradamente ao público. No caso do puro e inequívoco requerimento do ''FORNECIMENTO fático oficial em documento exarado e selado de CERTIDÕES'' (esteja a sua solicitação embasada em defesa de direitos ou meros fins informativos gerais sem trânsito sigiloso oculto em banco restrito passivo à manipulação de retificação da ficha de dados imetrificáveis do cidadão), a simples e rasa recusa estatal deflagra exclusivamente, via doutrina e tribunais absolutos de defesa coletiva, proteção exata sob as premissas deflagratórias protetivas estritas da alocação de ofício pelo ato do MANDADO DE SEGURANÇA. Resumindo a máxima sumulada consolidada na doutrina penal da corte: Direito violado ou omissão abusiva ilícita e infundada estatal à certidão documentada pura se ataca materialmente e rotineiramente apenas com Mandado de Segurança, sem resquício legal protetivo no Habeas Data individual restritivo.","difficulty":"dificil","tags":["Direito de Certidão","Habeas Data","Mandado de Segurança","Ação Cabível","Bancos de Dados Pessoais"]}'::jsonb, 'draft', 'm78hsc', 30),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a asserção no tocante à prerrogativa irrestrita ao Direito Fundamental à livre associação de cunho originário e político-classista sindical insculpido formal e basal nas alíneas estritas no caput magnânimo e rol material do arranjo tutelar na CF: Diferentemente de autarquia estrita de categorias monopolísticas na máquina representativa estatal civil dos médicos formados em CRM rotineiro, o Conselho de Fiscalização de Ética e Atuação dos Contabilistas Ativos da base municipal exara, pela exegese da corte atípica, exímia natureza autárquica administrativa do crivo estatutário da União federal restrita. Conquanto revestido do rol de entidade atípica disciplinadora do labor base contumaz, a sua respectiva filiação material e financeira de alíquota e anuidade passiva da chancela oficial baseada na atuação fiscal formal, a contragosto escandaloso isolado unânime do profissional certificado originário livre de associação, vulnera inescusavelmente o dito mandamento basal sagrado constitucional pretoriano de liberdade material rotineiro da desfiliação contumaz cívico exaurível base classista estrita unívoca do indivíduo passivo autônomo perante essa classe originativa.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Supremo Tribunal Federal, ao distinguir com maestria técnica apurada os institutos inerentes associativos puros civis avulsos em oposição franca aos Conselhos de Fiscalização e Disciplina Profissional de classe (OAB - entidade sui generis - bem como CRMs, CREAs, CRCs - autarquias especiais federais monopolísticas essenciais base), reitera pacificamente: A filiação compulsória ou exigência formal basilar do pagamento do múnus rotineiro de anuidades oficiais a esses Conselhos legalizados de estrita fiscalidade técnica laborada do governo PÚBLICO para que o indivíduo capacitado atue na praça NÃO VULNERA nem atenta sob nenhuma restrição abusiva isolada material a garantia ou Liberdade de Associação exposta no artigo 5º da CF. Isso decorre de premissa basilar jurídica cível, pois essas entidades originárias revestem-se essencialmente de feição e roupagem pública, com o poder-dever de polícia administrativa para exercer imperativamente e compulsoriamente a rigorosa fiscalização em defesa e benefício primaz superior cabal e coletivo da sociedade atuante.","difficulty":"medio","tags":["Conselhos Profissionais","Liberdade de Associação","Filiação Compulsória","Anuidade","STF"]}'::jsonb, 'draft', 'wpeifd', 31),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Diante das minúcias de impetração de Habeas Corpus: Constitui preceito dogmático originário basilar de impetração da ação libertadora garantida, consoante jurisprudência restritiva formal da corte do habeas cível penal, que a exigência estrita civil inibitória atrelada e exigida inescusavelmente de comprovação técnica ou recolhimento e pré-depósito contábil ou emolumentos para o precesso de ajuizamento rotineiro das bancadas recursais materiais atípicas originadas decorrente restrito (tal como o cabível preparo material estanque nas lides criminais ativas do Recurso Ordinário Constitucional RHC e os Recurso Especiais isolados restritos criminais base inibitória atinentes derivado desse mesmo HC), são totalmente vedados ou inibidos pelo mandado da gratuidade originária do ato penal do próprio rol da Constituição pátria originária.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme estigmatizado sob a estrita égide protetória consubstanciada e cristalizada nas cláusulas magnas pétreas e nos regulamentos jurisprudenciais, a Carta de 88 estabelece cabal e textualmente (no artigo 5º, inciso LXXVII): ''São de forma inescusável, irrefutavelmente e cabalmente GRATUITAS sob tutela restritiva civil material estrita rotineira, material e de amparo estatal todas e quaisquer ações originárias fundamentadas da submissão processual atinente de HABEAS CORPUS, HABEAS DATA, e na forma regulada irredutível da regulamentação ativa basilar da lei ordinária as estritas lides atreladas perenes com os indispensáveis primazia atípica e restrita forma originária aos estritos recursos decorrentes estritos (inclusive os decorrentes penais como o RHC, REsp e agravo estrito afins base destas matrizes processuais de fundo criminal perene restrito)''.","difficulty":"medio","tags":["Habeas Corpus","Gratuidade da Justiça","Recursos Constitucionais","Cláusula Pétrea"]}'::jsonb, 'draft', '7xbfxw', 32),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a exegese normativa sobre a ampla defesa e seus corolários no ambiente processual atípico: Apesar do primado garantista da Magna Carta que defere, estipula rotineiramente e não flexibiliza material a Ampla Defesa técnica nos processos penal, cível-administrativo rotineiro e as restritas condenações materiais ativas sancionadoras pregressas dos militares: A aplicação restritiva singular oficial disciplinado estancada no regulamento castrense punitivo perene consubstanciado na cominação restritiva punitiva originária do crivo penal disciplinar (sem amparo criminal oficial atrelado de juizado) da ''Punição de Restrição Formal a Transgressões Militares'' ou os atos administrativos sancionados a soldado passível em quartel sob pena da punição disciplinar material e não judicial (a exclusão fática basilar castrense imposta unicamente pelo oficial estanque originário militar) revestem-se maciça irredutível do crivo impeditivo do ato judicial base ou amparos perenes judiciais restritos, escapando totalmente formal da via corretiva do judiciário para anulação cabal originária formal da mesma sansão rotineira irredutível base estanque e desfundamentada.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Trata-se de entendimento exato basilar já ultrapassado (fatos do antigo regime). A CF diz no art. 142 que não cabe Habeas Corpus no MÉRITO penal-disciplinar puramente restritivo exímio ou discrionário estrito militar. ENTRETANTO, o STF consagrou que O JUDICIÁRIO federal pátrio detém perfeitamente o pleno direito inibidor e formal material para revisar amplamente E CORRIGIR atos originários administrativos disciplinares castrenses, e punições militares, SE houver neles, nas estritas roupagens processuais formativas originárias: a inescusável ausência exímia de devida motivação legal, vício claro originário do rito formal atrelado na apuração subalterna ou a preclusão e ofensa flagrante às formalidades inescusáveis cabais ou o desrespeito material amplo e manifesto inescusável isolado basilar e rotineiro ao sagrado ato originário cívico do Contraditório ou ausência inescusável base originária estanque impetrada restrita basilar do princípio canônico rotineiro originário irredutível garantista normativo ininterrupto restritivo da ampla defesa das bancadas oficiais castrenses impeditivas atípicas atrelada.","difficulty":"dificil","tags":["Revisão Judicial","Punições Disciplinares Militares","Ampla Defesa","STF"]}'::jsonb, 'draft', 'ou4vbn', 33),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Avaliando a interface principiológica das prisões constitucionais restritivas estipuladas civis ordinárias fáticas inibitórias da ordem de amparo: Em derrogação clara das excludentes do status criminal irredutível, o mandamento imperioso da imunidade civil canônica de prerrogativa parlamentar outorgada restritiva preceitua aos Senadores atípicos, caso perca e evada de seus recintos e esferas originárias de bancadas, imunidade prisional total irredutível basal (vedação absoluta fática de estarem constritivos perante rito prisão restritiva prévia de prisão em flagrâncias exímias temporariamente até a condenação), mesmo sob crivo letal de amparadas fáticas cabais estipuladas do cometimento de ato material estrito exímio flagrante da ocorrência ativa fática isolada contínua atrelada em inescusável infração formal hedionda passível a crime inafiançável civil base nacional.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. De acordo expressamente textual nas entrelinhas e base com os ditames constitucionais primordiais fáticos das imunidades absolutas parlamentares da magna Carta (artigo exato basilar material e originário restrito 53, § 2º): Deputados rotineiros isolados subalternos nativos cabais e exímios e também e inesquecivelmente todos os atuantes Senadores efetivos não logram desfrutar ou reter atrelada a tão restritiva alocada ou inatingível roupagem fática imunidade estrita unânime isolada originária passível basilar inescusável blindada para atos rotineiros prisionais. A ÚNICA e excepcional brecha amparada legal que exara a quebra cabal de ofensa prisional dessa imunidade prisional prévia cautelar parlamentar impeditiva é precisamente quando este mandatário político e legislador passivo atrelado venha cabalmente e faticamente vir a ser interpelado preterido pego materialmente no estrito momento inescusável base perene inibitório da própria conduta rotineira basal cabal (''Em Fato Gerador ou FLAGRANTE'') exímio e contínuo pela consecução material da prática isolada basilar criminal classificada unânime cível estrita base inibitória atípica restritamente preterida fática hedionda passível inesquecível de infração tida oficialmente na regra pátria perene tipificada no canônico e irredutível estancamento inibidor dos ''CRIME INAFIANÇÁVEIS'' originários da estrita nacional restritiva (ex: Tortura, terrorismo, hediondos etc).","difficulty":"medio","tags":["Prisão Parlamentar","Imunidade Material","Crime Inafiançável","Flagrante Delito","Constituição Federal"]}'::jsonb, 'draft', 'v3vnhs', 34),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"À luz do mandamento constitucional a respeito das custódias protetórias irredutíveis temporárias fáticas de prisões temporárias da alçada cível estanque passível inibitivas de exceção processual investigativa do ordenamento: É defeso e nula peremptoriamente de ofício basilar pela lei federal processual estipulada a concessão ou chancela da imposição mandamental isolada canônica atípica judicial unívoca de prisão fática isolada investigativa protetora na exata base penal cautelar formativa na nomenclatura ''preventiva ou temporária'' pautando preterido base isolada preterida exclusivamente única, material rotineira estritamente passível, na necessidade abstrata base ou clamor unívoco cível passível retórica social na finalidade pura inibitória originária garantista inescusável do indivíduo passível exaurível de ser coagido, por ofensa, base perene do preceito canônico estancado preterido originário do garantismo das estritas declarações processuais estipulada passível para obter cível material coercitiva ou forçar o investigado ao depoimento base de delação ou à referida confissão inescusável e estrita restrita cível policial criminal inquisitória originária passível do auto.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Isso está expressamente assentado. A confissão formal ou fático ato material interrogatório processual atípico cível ou mesmo a obtenção penal do depoimento (que embasavam as antigas e nulas mandamentais de ordens para investigações fáticas ilegais como p.ex ''Condução coercitiva'' que depois fora banida originária do crivo penal). Nenhum indiciado isolado estanque inibitório ou réu inescusável pode figurar e ser constrito material legal prisional basilar na rubrica fática temporária inescusável preventiva por pauta judicial ou mandado puramente embasado, por parte de estado passível, preterido basilar cível impetrado rotineiramente unívoco no objetivo punitivo rotineiro inibitório puramente estatal de extrair base ou conseguir o crivo de sua pura base material inibitória rotineira delação premiada coercitiva estrita ou obrigá-lo inibido a produzir rotineiramente provas confessionais atípicas isoladas base fáticas judiciais punitivas atreladas a dilações inquisitoriais policiais oficiosas, sob gravíssima e afrontosa ofensa rotineira da Corte Constitucional basilar à premissa material irredutível da presunção de inocência irredutível e, preterido isolado do rol cível impetrante, do instituto perene de escusa e amplo do silêncio de ''Nemo tenetur se detegere''.","difficulty":"dificil","tags":["Prisão Preventiva","Confissão Genérica","Delação Coercitiva","Presunção de Inocência","Nemo tenetur se detegere"]}'::jsonb, 'draft', 'vtpr6c', 35),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Sobre a abrangência e os titulares dos Direitos e Garantias Fundamentais esculpidos no artigo 5º da CF/88: A Constituição veda textualmente, sob pena de responsabilidade imprescritível, que pessoas jurídicas (associações e institutos estrangeiros de capital aberto em atuação multinacional na bolsa) pleiteiem materialmente ou atinjam resguardo originário inerente ao puro titular nato ou individual e fundamental basilar nos Direitos Humanos sob a alçada constitucional civil basilar, vez que o escopo material rotineiro da Corte limitou a titularidade das garantias cíveis fáticas (como sigilo telefônico, integridade de honra no meio judicial) pura e estritamente ao ente de substância atípica carnal do homem vivente na sociedade.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Embora as garantias e ''Direitos Individuais Humanos e Fundamentais'' apontem originária e literalmente no texto basilar canônico constitutivo do texto puro para a guarda essencial cívica protecional originária da dignidade da essência ou da pessoa ''física'' (ser humano), é consolidado irrefutavelmente na doutrina pátria universal e nas rotineiras reiteradas jurisprudências atípicas estritas preteridas basilares do Egrégio Supremo (STF) que As **Pessoas Jurídicas** gozam integralmente rotineira e plenamente civil isolada basilar passível material (também e até mesmo sendo elas associações ou entidades fundadas estrangeiras transnacionais de atípico capital externo com lides regulares fáticas preteridas na união) à rigorosa estrita salvaguarda do amparo garantista fundamental do caput. Podendo fruir e exigir a proteção rotineiramente canônica em defesa preterida inibitória a: Honra rotineira objetiva, Inviolabilidade da base estrita de suas comunicações sigilosas telemáticas ou dados estancos atípicos e preceitos rigorosos rotineiros civis impetrados processuais de amplo do rito defensório cível, por deterem existência e direitos submetidos cabais perene materiais constitucionais de resguardo estatal.","difficulty":"facil","tags":["Titularidade dos Direitos","Pessoas Jurídicas","Estrangeiros","Honra Objetiva","Sigilo de Dados"]}'::jsonb, 'draft', 'qc8s9s', 36),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue em sede da garantia cívico-constitucional de locomoção fática preterida: Caso ocorra o acionamento irrefutável de imposição originária legal atípica deflagrada da formal e temida rubrica do ''Estado de Defesa'' exarado no país com fático decreto fático ratificado restrito originário do parlamento, subsiste legal cominada unânime e explicitamente admitida a total suspensão imediata e restrição absolutória da chancela protetora recursal inibitória restrita basal do remédio constitucional do resguardo de fática do Habeas Corpus como instrumento puramente mitigatório judicial a eventuais rotineiras violações isoladas cívicas dos excessos flagrantes temporários militares ou restritivas dos policiais estaduais autorizados.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Esta afirmação carrega exato e gravíssimo erro protetivo formal atrelado. Pela sistemática impositiva rigorosa pátria dos direitos, sob estipulada e basilar forma cabal normativa rotineira, e consubstanciado textualmente cível no texto magno (Art. 136, § 3º, IV), preceitua que, ATÉ MESMO NA PENDÊNCIA ou vigência rotineira basilar de decretação canônica fática inibitória e excepcional extrema rotineira do temido **Estado de Defesa**, É VEDADA categoricamente inescusável rotineira qualquer mitigação, exclusão base, afastamento exaurível isolado fático ou a famigerada irredutível proibição e paralisação dos foros processuais limitadas rotineiras e subalternas nativas impetradas ao rito inibitório **Habeas Corpus** aos judiciários regulares. Ele subsiste sempre ativo para coibir excessos. Apenas no Estado base restrito letal superior de *Sítio* (e dependendo estrita da dimensão excepcional originária), as chancelas base ou medidas poderiam vir inescusáveis excepcionalmente a abalar parte de trânsitos isolados fáticos estritos judiciais rotineiros, mas ainda sob tutela da proporcionalidade da Corte Constitucional originaria.","difficulty":"dificil","tags":["Habeas Corpus","Estado de Defesa","Estado de Sítio","Suspensão de Garantias"]}'::jsonb, 'draft', 'kmsuks', 37),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Sob a hermenêutica estrita exaurível do STF referente aos trâmites garantistas basilares formativos do sigilo cível restritivo originário protetório do sigilo bancário: O repasse automático originário estanque em massa por preceito fiscal e obrigacional restritivo impetrado irredutivelmente (informações canônicas compulsórias sistêmicas isoladas cruzadas na malha fina), transferindo exatas operações estipuladas do fluxo global fático, sem nenhum mandado unívoco inibitório prévio da base de magistrado judicial, desde a instituição do foro das fáticas rotineiras matrizes das Instituições Financeiras para o repasse inescusável base aos bancos auditores restritivos investigativos da SRF (Receita Federal) preterida não constitui, no acórdão rotineiro e material base unânime isolada do Pleno do STF, vulneração do Direito Individual fático inibidor estatuído da garantia preterida de inviolabilidade e escusa constitucional impetrada.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. O STF, em julgamento pacífico e rotineiro emblemático de base de (Repercussão Geral, Tema 225 e RE 601.314), declarou expressamente válida, regular basilar obrigatória e inteiramente e rotineiramente constitucional inescusável a obtenção direta fático inibitória, pura e material normativa (sem mediação de ordem isolada unívoca preterida atípica do Judiciário rotineiro inescusável) pelas autoridades de bases fiscais fáticas investigativas primordiais matrizes (a SRF e Fisco) aos dados inescusáveis base sigilosos de fluxo ou estrato atrelados estritos base e transferidos isoladamente unânimes e repassados por bancos/instituições estipuladas financeiras perante à Lei Complementar. Trata-se, tecnicamente basilar impetrado da rotineira basilar na nomenclatura originária do julgado do que se denominou de mera **''transferência civil protetiva irredutível rotineira da guarda de sigilo''**, e não de simples preterida material quebra ou devassa. O fisco as recebe as bases irredutíveis sigilosas em lote estatuído base cível preterido e mantém o resguardo blindado isolado perene do sigilo (e se vazar ou publicar o fisco repassado será criminalizado).","difficulty":"dificil","tags":["Sigilo Bancário","Receita Federal","Transferência de Sigilo","Acesso a Dados Financeiros","STF"]}'::jsonb, 'draft', 'qc105b', 38),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Avaliando os pilares garantistas irredutíveis estritos originários na persecução preterida penal do contraditório: A confissão material pregressa inquisitorial atípica basilar do rotineiro processo de inibição extraída passível rotineiramente fática e validada cabalmente material da referida premissa ou atípica conduta cabal primaz atípica penal inibitória rotineira voluntária na esfera do mero auto de inquérito preterido de prisão preliminar base preterida na Polícia Federal, e se estipulada e validada em ata sem coação letal ou prova isolada física restrita, afigura e estipula basilar exata forma absoluta prova irredutível preterida para uma base canônica penal irrecorrível exímia, independentemente originária rotineira de ser ou não ratificada isolada e faticamente nas vias protetórias matrizes inibitórias do juízo sob o manto e o contraditório do escrutínio judicial.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Com as alterações rigorosas do Pacote Anticrime, corroborando uma exegese fática do Direito Penal e pautando a materialidade dos princípios fundantes protocolares do crivo garantista restrito cível processuais constitucionais: O parágrafo único inserto faticamente irredutível no rito basilar restritivo normativo atual do Art. 155 do CPP atesta inescusável fática estritamente base inibitória cabal unívoca unânime que o **Magistrado NÃO pode faticamente fundamentar** sua referida premissa penal isolada atípica de materialização da sua liminar ou condenação do indivíduo EXCLUSIVAMENTE calcada exímia basal preterida em qualquer dos ditos e puramente meros elementos ou indícios rotineiros estritos probatórios formados estritamente na fase rotineira puramente policial investigativa dos balcões inquisitivos (ex: a confissão solene inibitória prestada unicamente basilar na base passível apenas ao Delegado de polícia sem ratificação material isolada posterior formal fática na lide da via presencial e processual atrelada sob a chancela fático judicial basilar estipulada sob fogo cabal do rito inescusável do *contraditório*). Devem os fatos essenciais base ser reproduzidos na fase da juízo cível, sob o crivo perene isento do Advogado passível originário rotineiro ou com o adendo irredutível atípico exímio rotineiro fático extra de mais robustez material (como flagrantes indiciários físicos inibitórios).","difficulty":"medio","tags":["Confissão Extrajudicial","Inquérito Policial","Princípio do Contraditório","CPP","Juízo"]}'::jsonb, 'draft', '4xu2ar', 39),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Face às premissas basilares restritivas rotineira amparadora fático originária do Tribunal base protetivo de Justiça Penal atípico originário preterido cível em apelo basal de ofensa a lides: Em razão inescusável de ofensa sumulada originária garantista passível e inibitória exímia à celeridade base e das tutelas normativas civis aos tribunais judiciais canônicas unânime de julgamento base por inescusável matrizes fáticas restritivas passivas do princípio originário da Soberania exímia dos Inescusáveis limitados estritos julgamentos e as preteridas rotineiras sentenças atreladas na referida instituição originária e formativa do ''Tribunal Estipulado do Júri Prático Popular Nacional'': Nenhuma Corte puramente isolada recursal superior e atípica de togados base estipulada no rito cível criminal, em apelação fática interposta e fundamentada fática perene na tese rotineira e basilar inibitória civil estanque irredutível originária de que o veredicto estipulado restrito se apoiou basilar fático irredutível e faticamente de modo manifesto e exaurível irredutível contrário à inescusável base das provas puras rotineiras plúrimas processuais inescusáveis base da autoria, deterá autorização inescusável e o poder para cassar referida e isenta estatuída decisão preterida, por configurar reexame cabal do mérito vedado inescusável inibitório à esfera estrita da constituição na dita soberania nativa passível dos Jurados.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O consagrado e irredutível Princípio originário protelado estritamente e rotativo encartado com exímia de fático cívico na CF rotineiro chamado e estatuído na base cível sob ''Soberania Formal Absoluta fática inescusável Rotineira basal unânime Inibitória preterida Estrita dos Veredictos'' cabal originário do Júri Popular civil NÃO confere à dita formatória estrita atípica uma blindagem insuscetível isenta inibitória rotineira absolutória ou condenatória irrecorrível material impenetrável unívoca inescusável estritamente irrevogável em sentenças preteridas. Conforme preceitos fáticos do próprio rol passível do Código Cível Penal (CPP), e sumulado base pelos rigorosos limites protetivos isolados preteridos dos STF e matrizes judiciais de cortes nativas exauríveis superiores: é perfeitamente admitido legalmente e impetrante e exarado faticamente de ofício o Apelo originário isolado fático cabal estipulado preterido nas circunstâncias bases restritivas e excepcionais cíveis onde a votação inibitória referida final da dita banca leiga (o veredito basilar passível rotineiro) se mostrar faticamente ''manifestamente rotineira inescusável civil e inequivocamente preterida isolada contrária cabal unívoca estanque fático e irredutível frontalmente a base isolada de TODAS AS provas atípicas unânimes processuais''. Nesse caso canônico estrito impeditivo atrelado, deferido o apelo inescusável basilar inibitório protetivo pelo TJ/Tribunal revisor fático originário passível limítrofe material, a câmara rotineira de desembargadores base irá **cassar material e unânime isolada passível a sentença**, submetendo cabal e irredutivelmente e inescusável o referido réu passível a um novo e lícito rotineiro preterido julgamento material inédito e inibitório prático em frente à nova junta fático formativa de conselho de nativo jurado estipulada leigo base rotineira.","difficulty":"dificil","tags":["Tribunal do Júri","Soberania dos Veredictos","Apelação","Decisão Manifestamente Contrária","CPP"]}'::jsonb, 'draft', '8omof1', 40),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a asserção no tocante à garantia protetiva da propriedade e desapropriação no texto magno cívico: O confisco agrário base originário inescusável rotineiro inibitório preterido de terras fáticas na Constituição, estatuído em caso de cultivo e tráfico ilícito puro de substâncias canônicas entorpecentes psicotrópicas em dita gleba isolada da União, configura modalidade de sanção punitiva material inescusável irredutível ao proprietário estrito; assim sendo, e diversamente da expropriação agrária basilar inibitória rotineira por falha em cumprimento basal de função social, a desapropriação confiscatória não exara qualquer restrita e prévia retribuição originária material ou indenização pecuniária fático cabal inibitória em títulos federais ao titular negligente ou faltoso do lote esmerado cível atípico exaurível.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme estabelecido no art. 243 da Constituição Federal, as propriedades rurais e urbanas onde forem localizadas culturas ilegais de plantas psicotrópicas (ou exploração de trabalho análogo à escravidão) serão EXPROPRIADAS e destinadas à reforma agrária ou a programas de habitação popular, SEM qualquer indenização ao proprietário e sem prejuízo de outras sanções penais cabíveis (''expropriação-confisco''). Diferente da desapropriação sanção vinculada ao descumprimento inibitório rotineiro da mera função social pura preterida da terra agrária fática, que garante puramente rotineiro inescusável isolado um formal e rigoroso cível basal pagamento civil prévio, ainda que em TDA (Títulos irredutíveis da Dívida Agrária restritos plúrimos do governo).","difficulty":"medio","tags":["Desapropriação Confiscatória","Expropriação","Cultivo Ilícito","Sem Indenização"]}'::jsonb, 'draft', 'novdhe', 41),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Avaliando os pilares garantistas irredutíveis estritos originários na garantia de extradição e expulsão preterida: É defeso e inconstitucional por afronta escandalosa rotineira ao regramento cível protetivo do refúgio e dos exilados basilar a extradição preterida rotineira formal inescusável do indivíduo estrangeiro fático residente no solo amparado isolado caso os preceitos puros das sentenças matrizes alienígenas solicitantes estipuladas fáticas o condenem e o requeiram cabalmente originário exaurível pela consecução unívoca estanque criminal e prática irredutível preterida originária material civil exclusiva atípica de crimes puramente de viés ou vertente militar fática ou de lides eminentemente e estritas classificadas unânime inibitória nas sedes políticas exímias e crimes de opinião governamental subversiva do estrangeiro amparo base restrito fático penal isolado atrelado.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. A Constituição da República proíbe expressamente, no rol dos seus Direitos e Garantias Individuais (art. 5º, LII), a concessão material da Extradição inescusável de base formal protetória restritiva originária do indivíduo EXTRANGEIRO isolado rotineiro que for unicamente requisitado inibitoriamente base no rol ou processado criminalmente lá fora em virtude puramente cabal atípica impetrante de tipificação irredutível classificada e embasada preterida de excluso ''CRIME POLÍTICO ou de basilar inibitório CRIME DE OPINIÃO''. O STF também consolida essa vedação inescusável (Lei de Migração inclusa) que estrangeiros puramente perseguidos em crimes rotineiro políticos não exaram extradição formal cível. Da mesma sorte estanque rotineira atrelada, os puros chamados ''crimes estritamente militares rotineiro'' são estipuladas e pacíficas na Corte fático que não exaram amparo inibidor de extradição pátria na fática do STF e tratados.","difficulty":"facil","tags":["Extradição","Estrangeiro","Crime Político","Crime de Opinião"]}'::jsonb, 'draft', 'jzg7gi', 42),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando os balizamentos pretorianos sobre a Inviolabilidade base estrita rotineira das Comunicações telefônicas (escritórios e dados telemáticos fixos): O sigilo basilar inibitório constitucional resguarda estrita as correspondências preteridas epistolares civis amparadas fáticas postais. No entanto, por base rotineira da segurança penitenciária de massa inescusável base irredutível fática coletiva impetrada isolada material normativa de exceção e sumulada do rol amparado do Judiciário: A base protetiva originária do administrador penitenciário fático civil base exímio preterido ou Diretor estanque de prisão local rotineira detém estrita e inescusável passível amparada liminar a estatuída discricionária puramente administrativa basal e irredutível para interceptar basilar ou mesmo invadir, abrir estrita, violar unívoca isolada fisicamente as bases inibitórias atípicas exauríveis das puras cartas materiais estipuladas postais e correspondências fechadas nativas rotineiras unânimes recepcionadas estritas do indivíduo recluso presidiário nato ou base detento inibitório subalterno originário do foro isolado atípico preterido amparado estanque, e, destarte unânime civil, apreendê-las faticamente formal restritiva como base de material indiciário prévio material inescusável criminal inquisitório do Estado se achar perigoso.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se de uma excepcional mitigação sumulada da inviolabilidade originária das correspondências. Segundo pacífica construção basilar civil rotineira fático atrelada inescusável probatória inibitória e do núcleo basal do STF e do amparado estrito no art. 41 da Lei Base restritiva de Execução Penal (LEP): Os direitos e amparos restritos natos individuais formais da dignidade preterida dos puros base PRESOS base recolhidos do sistema prisional sofrem atípicas e originárias e naturais restrições legais isoladas baseadas em estrita tutela probatória cabal segurança do regime unívoco. Sendo plenamente material lícito puramente exímio fático irredutível rotineira à puramente estrita basilar DIREÇÃO ou administração do base fática isolada do presídio material abrir exaurível rotineira isolada e reter ou interceptar base a correspondência fática escrita exímia amparada (cartas postais originárias) destinadas ou emanadas exatas das esferas do presidiário se houver rotineira suspeita inibitória ou justificativa de cometimento originário isolado ou plano basal de rotina fático puramente criminal base material inibidor na segurança coletiva sem necessitar, para o exclusivo fato rotineiro inibitório da leitura base escrita epistolar do presidiário, de prévia canônica impetrante fática formal Ordem protetiva de juiz civil.","difficulty":"dificil","tags":["Inviolabilidade das Correspondências","Sigilo Epistolar","Sistema Prisional","Preso","LEP"]}'::jsonb, 'draft', 'stagki', 43),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a proposição sobre as excludentes ou imunidades judiciais rotineiras formatadas para proteção puramente impositiva à maternidade civil estanque basilar amparadas pós Emenda exaurível de Proteção: A autorização rotineira fática exímia material impetrante liminar atípica judicial unívoca de puramente base fática prisão estrita basilar puramente investigativa protetora inibitória e da dita rotineira cautelar preventiva formativa cível na puramente basilar fática isolada prisão estanque impetrada restrita basilar domicial fática de caráter cautelar inibidor puro ao alvo de exímia restrita e provada MULHER basilar puramente GESTANTE basal, mesmo que acusada cabal civil isolada e processada estanque em flagrante trânsito da unívoca imputação inescusável do crime perene rotineiro preterido por Tráfico basilar inibitório material de narcóticos puramente letal rotineiro nas bases de base sem violência fática preterida estanque, prescindirá puramente de autorização da referida câmara revisora se tiver puramente filhos amparados dependentes de colo isolado.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. A matéria exarada base fática atípica inescusável puramente isolada preterida cível restritiva no STF nas rotineiras esferas do HC isolado 143.641 (e fixado base cível irredutível no artigo do CPP atual): Às base puramente Mulheres fáticas GESTANTES ou puramente mães estritas atípicas de crianças fáticas até exímios 12 anos rotineiros base (ou preteridos dependentes estritos inibitórios rotineiros estatuídos com puras deficiências exauríveis) É DEVIDO basal, rotineiramente puramente isolado da câmara inescusável do regime fechado preventivo, a dita SUBSTITUIÇÃO base material inibitória isolada da dita originária estanque PREVENTIVA basilar prisional pela chamada exímia GUARDA civil inibitória ou ''Prisão rotineira puramente Domiciliar''. Essa fática exímia garantia só possui DUAS exceções preteridas inibidoras fáticas absolutas rotineiras e não flexíveis inescusáveis de não ser dada base: se o referido base crime investigado impetrado na imputação rotineiro basilar foi efetuado inescusável materialmente com PURA GRAVE rotineira VIOLÊNCIA isolada exímia basal ou ameaça cabal na base da conduta atípica física fático originária inibitória rotineira contra pessoa... OU base puramente rotineira fático se foi crime amparado puramente de modo rotineiro doloso preterido isolado da dita ascendente restrita base atrelada diretamente aos puramente estritos filhos fáticos rotineiros em questão inibitórios da prole perene do dependente. O puro fático inibitório e hediondo isolado do TRÁFICO puramente lícito comercial atípico de Entorpecentes formal e rotineiro basilar em si NÃO constitui crime cometido puramente com violência basal inibitória atípica inescusável letal fática à pureza civil na dicção exímia material do STF, cabendo o benefício protetório rotineiro inescusável limítrofe material unívoco rotineiro nela basal de domiciliar isolada amparada na gestante preterida fática.  A redação truncada e extensa simula enunciados do CEBRASPE para causar confusão.","difficulty":"dificil","tags":["Prisão Preventiva","Prisão Domiciliar","Mães e Gestantes","Tráfico de Drogas","STF"]}'::jsonb, 'draft', 'mpn7z4', 44),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a asserção no tocante à garantia de duplo grau de jurisdição e a ausência absoluta de tribunais atípicos na referida formação cível do foro basilar da União rotineira preterida impetrante fática: Apesar do estrito garantismo fático originário em preterida isolada basilar inibitória civil no artigo basilar e rol rotineiro magno restrito à vedação basilar pátria civil (Art 5, inciso preterido estrito de vedar os ''Tribunais atípicos inescusáveis de basilar Exceção fática rotineira isolada unívoca preterida na persecução fática''), A Corte Constitucional originária preterida puramente civil de viés inibidor sumulou base puramente unívoca rotineira isolada fática inescusável o entendimento exaurível liminar que não atenta puramente contra essa câmara restritiva originária proibitiva do dito tribunal de exceção, a exímia constituição civil posterior fático e isolada formativa puramente base das rotineiras pautas e da restritiva preterida de criação institucional das chamadas exímias ''Varas puramente base Especializadas'' da Justiça (ex: criação nativa varas em crime inibidor agrário de lavagem do dinheiro fático ou especializadas rotineiras fáticas em violência estrita).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme balizamento e julgados do STF, a VEDAÇÃO constitucional de rotineira basilar criação de TRIBUNAIS DE EXCEÇÃO fáticos rotineiros visa impedir a rotina atípica da formação ou estruturação material de currais inibitórios ou fáticas justiças de juízes e foros criados ex post facto (depois do fato puramente estrito atrelado criminoso atípico já consolidado originário) apenas ou comitê isolado inescusável unicamente para julgar isolada e atipicamente uma pura ou certa pessoa inibitória ou estrito base caso preterido puramente isolado predeterminado de perseguição estanque pátria isolada inquisitória civil inibitória estrita (ex: tribunal ad hoc militar pós golpe). No entanto, não constitui fático ofensa a dita exímia proibição inibitória rotineira canônica magno a pura constituição, remembramento, organização rotineira ou fundação fático jurisdicional das denominadas isoladas VARAS ROTINEIRAS ESPECIALIZADAS civis inibitórias do juízo unívoco normativo natural por puros viés materiais ou por puras fáticas de matérias ou preteridas de rito (crime financeiro, varas protetivas de mulher nativa, vara exclusiva de lavagem e entorpecente).","difficulty":"medio","tags":["Juiz Natural","Tribunal de Exceção","Varas Especializadas","Garantismo Penal"]}'::jsonb, 'draft', 'a0mtke', 45),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando os mandamentos civis amparados estritos originários na proteção ao consumidor cível no rol magnânimo fático: O constituinte originário amparado cível estabeleceu, na preterida seara base de seus Direitos Fundamentais rotineiros do Título inibidor II taxativo fático (art 5, XXXII), que o estrito fático dever originário de promoção cabal inibitória da referida defesa civil do consumidor no âmbito preterido rotineiro basilar inescusável do país, deverá preterida ser incumbência cabal irredutível puramente civil isolada e delegada do Poder cível Judiciário rotineiro por força basilar estanque de norma regulamentada unívoca originária de matriz cível estipulada em tribunais de exceção cível fática nos estados amparados.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Trata-se da correta literalidade do dispositivo base da CF e a inteligência originária. O Constituinte originário grafou textualmente inibidor que ''O **ESTADO fático civil promoverá, e não o puro isolado poder Judiciário** em suas bancadas de fóruns limítrofes civis preteridas, na forma isolada irredutível protetiva legal cível editada e estipulada por LEI rotineira (que adveio depois com o CDC - Código cabal de Defesa pátrio civil Consumidor unânime rotineiro em 90), a dita defesa amparada basilar do preterido consumidor inescusável social''. Logo, a promoção e tutela base consumerista rotineira no Brasil NÃO é de incumbência primaz isolada originária rotineira e judicial das referidas liminares puramente de bancadas civis irredutíveis em fóruns. Mas uma chancela global impositiva fática na responsabilidade basilar irredutível preterida cabal (''o Estado'' como um todo nas esferas Executiva do Procon civil, Legislativa e Judiciária) por base e matriz preterida expressa ditame da inescusável basilar norma infraconstitucional preterida.","difficulty":"facil","tags":["Defesa do Consumidor","Dever do Estado","Constituição Federal","Literalidade"]}'::jsonb, 'draft', 'l9csew', 46),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a proposição protetora civil em face da extradição inibitória e dos Direitos Fáticos amparados de Naturalização: O brasileiro nato fático rotineiro que for unívoco originário inescusavelmente amparado e formalizado fático puramente com a preterida aquisição inibitória voluntária civil estanque na segunda fática cidadania exímia basilar da nação alienígena e americana inibitória (sendo este base não decorrente fática de puras e preteridas de normas basilares originárias do preceito de mero reconhecimento civil passível liminar de ''sanguinis puro originário europeu de nascença'' nem para gozo de exercício fático de diretos puramente inibitório civis atípicas obrigatórias isoladas exauríveis dos EUA por base de sobrevivência base migratória unívoca da labuta), SE EXPORÁ basilar inescusável rotineira material legal fático originário a preterida irrevogável e automática PERDA da estipulada Cidadania Nacional Brasileira rotineira e, destarte unânime fático cível, passa a ser exaurível classificado fático estrangeiro civil, tornando-se suscetível fático rotineiro base atípico originariamente em se submeter liminar no país cível rotineiro à amparada preterida Extradição basal pátria pura do Brasil por base cível se vier inescusável no solo pátrio cometer liminar estanque na nação o famigerado civil inibidor atípico ''Crime Comum irredutível''.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Esse é o entendimento fático atual amparado inclusive fático chancelado basilar da jurisprudência consolidada suprema rotineira fática em sede de RE cível inibidor no STF (caso fático da brasileira que cometeu homicídio cível nos EUA estanque e, após adquirir cidadania civil alienígena fática voluntária atípica para morar, fugiu para ca rotineiro). Conforme a base constitucional irredutível fática e originária estrita do fático da (CF, art. 12, § 4º, II): Se o basilar fático irredutível unívoco nato preterido opta rotineiramente por adquirir basal voluntariamente civil fático uma outra matriz da nacionalidade limítrofe americana amparada, o fático rotineiro inescusável isolado basilar e NÃO SE ENQUANDRA fático inibidor rotineiro liminar na estrita e cabal exaurível exceção de ''reconhecimento de nacionalidade pura civil rotineira originária amparada por descendência cível ou imposta por naturalização atípica isolada forçada fática para mero exercício puramente civil basal de direito trabalhista rotineiro'', ELE PERDE inescusavelmente AUTOMATICAMENTE a fática liminar inescusável nacionalidade pátria protetiva CÍVEL originária civil BRASILEIRA por portaria ministerial cível. E perdendo rotineiro puramente sua chancela civil nato protetivo, ele TRANSMUTA-SE fático basal em **Estrangeiro fático e cível no puramente crivo da restrita jurisdição**. É cediço base inibitório exaurível e cabal da lei magna que o fático ESTRANGEIRO CÍVEL (qualquer classe fática), inclusive o da nacionalidade basal americana protetivo que perdeu basilar inibitório rotineira a nossa fática, **PODE basal ser Extraditado puramente rotineiro civil isolada base exímia inescusável na ocorrência do cometimento estanque legal de Crime Comum civil irrevogável basal puramente**. Ele foi, de fato cível e ratificado rotineiro base no STF fático inibidor exarado, amparado fático formalmente EXTRADITADO material preterido cabal pátrio dos EUA.","difficulty":"dificil","tags":["Perda da Nacionalidade","Estrangeiro","Extradição","Crime Comum","Voluntariedade"]}'::jsonb, 'draft', '38vrko', 47),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue em sede do preceito de inafiançabilidade cível e imperscritibilidade formativa de crimes basilares magnos atípicos: A estrita consubstanciação material exaurível civil do mandamento e rol originário canônico dos fáticos restritos dos basilares denominados ''Crimens Hediondos preteridos irredutíveis'' exarada na estrita formativa base puramente magno constitutiva fático, além da puramente rigorosa inibitória de exclusão rotineira base unânime passível da Graça preterida unívoca rotineira isolada de amparada indultos presidenciais anistias civil, traz amparado na roupagem fática processual do judiciário a dita IMPRESCRITIBILIDADE puramente irredutível basilar inescusável do crime perante as fáticas esferas de perseguições da polícia basal atípica, devendo rotineira o trânsito impetrante e o julgamento exaurível basilar passível dos autores formativos puramente de extorsão ou tortura cabal ser inibitório deflagrado rotineiramente pátrio não importando estrito lapso do civil unívoco contábil originário rotineiro liminar preterido.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. As pegadinhas do CESPE base inibitória estrita fática amparadas nas distinções taxativas fáticas das excludentes basilares irredutíveis são clássicas e impetrantes: A MAGNA CARTA liminar cível basilar aponta puramente rotineiro originário como estritamente e rotativamente canônicos inibitórios unânimes atrelados CRIMES ''IMPRESCRITÍVEIS'' fáticos APENAS rotineiro exclusos OS SEGUINTES DOIS base formativa isolada exauríveis puramente atípicos: O cabal originário estrito **Racismo** e rotineira base liminar e preta inibitória a chamada de a preterida base ''Ação cível puramente fática de **Grupos impetrantes atrelados civis puros Armados** civis estritos preteridos ou Militares atípico originário restritivo contra inescusável puro baluarte civil da Ordem Constitucional Estado Democrático civil e irredutível fático''. Portanto basilar isenta e civil inescusável: A **Tortura**, os **civis Hediondos isolados**, O **fático Tráfico e o civil exaurível rotineiro Terrorismo (A famosa base civil sigla ''3TH'' das apostilas preteridas atípicas)** NÃO DETÊM base fática inibitória civil a imprescritibilidade rotineira exaurível magna (Eles PRESCREVEM puramente sim civis nos crivos originário inibitório exaurível estipulados materiais cíveis cabais preteridos unívocos da contabilidade basal rotineira processual e Código de Penas cível rotineira base normativo). O diferencial basal e rigoroso magno que a CF dita inibitória puramente civil para esses quatro rotineiros puramente (os 3TH exímios), é fático inibitório liminar originário preterido puramente de serem taxativamente rotineiros **INAFIANÇÁVEIS E INSUSCETÍVEIS de base cível originária Anistia ou Graça** civil unânime. SÓ.","difficulty":"medio","tags":["Crimes Hediondos","Imprescritibilidade","Racismo","Grupos Armados","Constituição Federal"]}'::jsonb, 'draft', 't9ptyu', 48),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Diante das normas de expropriação preteridas civis das alíquotas protetivas: O preterido basilar liminar exímio e rotineiro inescusável do processo base ou rito impetrante da exaurível impetrada Desapropriação originário civil inibitório, visando preterido finalidade isolada puramente de atendimento e destinação à mera Necessidade inescusável basal isolada pública de infraestrutura formativa municipal fático restritiva ou fático rotineiro em razão estrita exímia de fática exaurível inibitória e pura originária liminar de presunção amparada e irredutível por ''Utilidade amparada originária fático cabal pública'', demandará estanque e rotineiramente imperiosa e fática originariamente a imposição rotineira prévia material inibitória na rubrica de indenização justa civil compensatória liminar aos puramente expropriados pátrios cabais unívocos unânimes INCLUSIVE e restritamente no modal protetorio irredutível da emissão obrigatória estrita basilar de parcelamento contábil com lastro civil exaurível inibitório restritivo originariamente rotineiro preterido exclusivo pátrio e puramente exímio em Títulos Atípico preceituados nativos unívocos isolados fáticos civis de Dívida faticamente base originária em longo amparo e não em espécimes pátrio unânimes fático imediato dinheiro rotineiro da máquina da municipalidade estrita base para quitar formativa.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A Constituição da República prescreve expressamente fático irredutível puramente amparado e canônico no Seu artigo rotineiro 5º, exata na estrita inciso XXIV, que fático: a referida ''Lei limítrofe civil estabelecerá rotineiro fático unânime inibitório isolado e exaurível o procedimento material de basilar desapropriação por dita estanque civil inescusável fático **necessidade unívoca ou fática utilidade puramente civil rotineiro pública**, ou puramente basal por inibidor isolado atípico estrito de puramente civil **interesse social isolado**''. E impõe um duplo critério punitivo limitante fático no modelo retributivo cível formatado impetrante: Mediante base inibitória cível e **''PRÉVIA e rotineiro fático cabal inescusável e puro JUSTA indenização basilar amparada exclusa originária unânime civil exaurível EM DINHEIRO vivo pecuniário''** (Isso é regra geral originária e não em Títulos amparados civis da dívida rotineira). AS EXCEÇÕES preteridas cível basilar em Títulos isolados puros fáticos originário estritos da Dívida atípica rotineiros ou da unívoca de puramente de base fático Agrária base ocorrem SÓ E civil estrito puramente MEMENTE base nas específicas raras e isoladas desapropriações punitivas pátrias (''Punitiva fática rural impetrante - reforma ou Punitiva fático base civil inibitória Urbana rotineira'' quando inescusável não há cumprimento basal originários estrito fático base nas premissas das limitativas preterido da função social fática inibitória da referida rotineira isolada destinação cível liminar originária e unânime preterível).","difficulty":"medio","tags":["Desapropriação","Necessidade Pública","Utilidade Pública","Indenização Justa","Dinheiro"]}'::jsonb, 'draft', '4awcdi', 49),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Avaliando as hipóteses amparadas no habeas data pátrias pretorianas liminares e bases de restrição probatória inibitória: A utilização da peça civil exaurível unânime de exímia inibitória rotineira e inescusável do Mandado rotineiro irredutível base estanque e atípica de Segurança, em que se pese a prerrogativa isolada protetória de certidão unívoca basilar puramente administrativa ininterrupta liminar cível assegurada perene inescusável pelo incisivo estrito e formativo XXXIV rotineiro originário da Lei magna (a famosa CF) civil inibitor, se perfaz irredutível inibitório rotineiro inescusavelmente na jurisprudência atípica fática e cabal inibitória estrita como unicamente como inidôneo (fático nulo isento cível formativo originário) perante na basilar liminar amparado ao impetrante tentar e preterir isolado atípico inibitório e puramente garantir fático basilar civil a alocação puramente irredutível fática e estanque no seu respectivo puramente restrito civil acesso a base restritiva ou as originais puras e restritivas contábeis notas rotineiras atípicos de provas fáticas originárias do certame isolado unânime de exame atrelado estipuladas amparadas da avaliadora canônica de processos civis fáticos estritos preterido do ente concurso e vestibular estatal público.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Habeas Data basal NÃO DEVE base puramente isolado liminar fático preterida ser acionado puramente rotineiro amparado no fático como pleito atípico originário exímio restritivo rotineiro basilar inescusável de recurso cabal irredutível de candidato inibitório fático puramente comitê atrelado e puramente unívoco civil contra as bancas do vestibular inibidor cível unânime para mero fim passível isolado puro formativo originário de **ter liminar civil fático acesso às exauríveis suas e rotineiras puras correção de matrizes e contábeis NOTAS fáticas ou as suas pautas unânimes de espelhos puros base inibitórios atípicos cíveis em provas de certame/concursos base originária civil exaurível públicos da comissão limitadas rotineiras preteridos estancos**. Nesses estritos casos rotineiros limitados da doutrina impetrantes basilar e rotineiro cabal exímio em julgado do STJ, não há a presença no amparo basilar puramente legal originário das exigências fática originárias civil protetoras exclusivas de ''conhecimento limitantes puros de Dados restritos Pessoais do fático de banco originário ou apontamentos isolados de caráter amparados puramente cíveis confidenciais arquivados preterido de restrições puros liminares restritos civil de bases ou banco de puros dados unânime inibidor cadastrais atípicos em si base puramente civil sigilosa unívocos'' (que formam o estrito restrito fático balizador escopo do exarar de cabimento rotineiro puro do restritivo inibitório e da referida HD cível impetrante base formativa inescusável). No requerimento liminar de preterido acesso puramente do referido cível de espelho e estritas pautas e referidas ou puro vistas formativas civis de prova de processo base de do cidadão no certame, o negado injusto restritivo originária isolada ensejará preterido e basal inibitório, perfeitamente rotineiro e estanque na fático puramente amparada sumulada, no remédio base irredutível **Mandado de base cível inescusável Civil Segurança e jamais as pechas do basilar atípicos Habeas preteridos inibitórios exauríveis puramente rotineiros civis dos Data**.","difficulty":"dificil","tags":["Habeas Data","Mandado de Segurança","Acesso a Notas","Concurso Público"]}'::jsonb, 'draft', 'jy8znc', 50),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"A respeito dos remédios rotineiros originários de chancelas da estrita inibitória e civil de cunho cívico magnos: A doutrina e jurisprudência fática civil preterida chancelada pela corte em base inibitória e unânime suprema assenta expressa basilar isolada fática rotineira: O cabimento rotineiro puro do Mandado cível unívoco isolado estrito Inibitório e preterido cabal de basilar Injunção subentende fática a existência inescusável liminar de um originário dever cível estatal base atrelado e genérico de puramente fático isolado de chancelar norma, ou seja, de atípica de rotineira uma referida e pura inescusável ''ausência originária cabal de estrita norma civil unívoca amparada legal rotineira inibitória estanque'' que cabal inibitória base limite de modo fático a puramente outorgada inviabilidade civil ou o tolhimento prático de direitos fundamentais cíveis atípicos. E desta forma irredutível, o Poder basilar cível impetrante e fático restritivo Judiciário, em virtude do rotineiro Princípio canônico e puro formato da base Separabilidade isolada unânime rotineira preterida da civil base dos Poderes da União fático e originário, na dita decretação e mandado injuncional cabal julgado inibidor exarado, NÃO PODE basilar rotineiramente eximir e fático suprir inibitório ele mesmo isoladamente e judicial a ausência cível originária formativa basilar inibitória estrita de lei regulamentadora nem amparar de ofício a regra do amparo e direito de cunho limítrofe material, restando-lhe unicamente basilar a estrita notificação cabal e mora inescusável do Legislador rotineiro para puramente fático a chancelaria estrita da devida pauta rotineira e sanção da lei preterida inibitória rotineira.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Historicamente fático e até idos da década de base de 2000 inibitória, o STF cível isolado adotava e tinha rotineira a puramente inescusável referida tese de estrita (posição fático e inibitória basal canônica amparada dita e rotulada ''não-concretista atípica''). Entretanto inibitória, no clássico fático julgamento de base amparada rotineira cível isoladamente do MI da estrita chancelaria dos inibitória originário e base do Mandado rotineiro de fático Injunção da dita basilar fática ''Greve liminar de puro fático Servidores rotineiros Públicos'', O Supremo Tribunal basal originário fático civil de Justiça Cível **mudou OBRIGATORIAMENTE para a dita jurisprudência protetora cível base ''CONCRETISTA pátria fática isolada'' (Lei 13.300 estrita fática amparada)**: Hoje irredutível, ao dar fático rotineiramente provimento cível originário ao MI inibitório puramente, o Judiciário rotineiro NÃO APENAS puramente isolado decreta fática a estrita Mora limítrofe do base Legislativo inibitório estanque, MAS **ESTABELECE faticamente de ofício as chancelas de condições bases e preceitos rotineiros puros fáticos exímios amparados inibitórias basilares na lei estanque** para o integral exercício cabal inescusável atípico e liminar do Direito fundamental base do requerente (suprindo temporariamente, sim rotineiramente, a inibitória ausência da fático norma com amparo liminar material).","difficulty":"medio","tags":["Mandado de Injunção","Posição Concretista","Omissão Legislativa","Separação dos Poderes"]}'::jsonb, 'draft', 'xdfeol', 51),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Considerando os preceitos puros amparados estritos base cíveis irredutíveis magnos na chancela limitadora protetiva base da punição e retroatividade inibitória de leis sancionativas civis: O postulado irredutível base penal de limitação constitucional inibitória (Art 5, XL) rege inescusavelmente de forma originária amparada que ''a referida liminar estrita cabal rotineira lei cível penal e base não rotineira fática e inibitória exímio retroagirá inibitório civil isolado para punir estanque'', estatuindo o inibidor princípio civil e rotineiro excluso estrito fático originário irredutível cabal da basilar restrita chancelaria da irretroatividade. Todavia assevera fático originariamente amparado que a referida exceção rotineira e atípica de retroação cabal benéfica em sede fática originária para o mero favor do indivíduo puramente basilar penal (''lex mitior basilar'') tem preterida e isolada unívoca sua estipulada validade limítrofe inibitória rotineira base unânime fático cessada obrigatoriamente e impedida com exclusão sumário liminar do respectivo Trânsito basal inescusável do Julgado da sentenciada estanque restritiva penal condenatória inescusável fática cível, isto é cabal unívoco, após inibitório exaurível e cabal transitar passível inescusavelmente rotineira em via de fático estrito da puramente rito de julgamento fático julgado cível não é mais admitido inibitória o recálculo benigno ou revogação limítrofe com base isolada numa nova e amparada lei base rotineira.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Segundo preleciona a basilar rotineira garantia magna (art 5, XL): ''A lei rotineira puramente fática liminar inibitória penal atípica não retroagirá cível estanque, **SALVO basilar isolado fático exaurível cabalmente para poder civil beneficiar inibitório fático o inescusável rotineiro originário réu cabal**''. A Constituição originária civil NÃO IMPÔS amparada ou condicionou nenhum basilar civil obstáculo ou puramente limite civil e temporal amparado (como exaurível fático impeditivo do trânsito inibidor liminar em julgado basilar) para inescusável exarar a referida retroatividade benéfica rotineira fático irredutível (lex liminar pura exímio mitior preterida). E o puro e cabal formativo Código de basilar e rotineiro fático Penal Cível fático corrobora estrito rotineiramente inibitório em seu amparo Art. 2º civil preceito: As puramente exaurível isoladas disposições irredutíveis atípicas e benéficas aplicam-se liminar e exímios originariamente aos FATOS puramente ou exatas isolados sentenças limítrofe ANTERIORES e atrelados de fáticas, **''AINDA puramente amparado inibitório QUE rotineiro irredutível cabal DECIDIDOS puramente isolada liminar por pura estrita SENTENÇA rotineira base e originária CONDECATÓRIA cível TRANSITADA unívoca basal EM inibitória fático canônica liminar preterida originária fática cabal JULGADO rotineira''**. Inclusive cabal, cabe preterida ao Juiz irredutível originário amparado fático de puro amparo inibitória na estrita e cabal da puramente rotineira rotulada Vara originário atípico de amparada preterida Execução penal cível liminar (Súmula inibitória amparada 611 originária do cível do STF exarada) a pura exímio aplicação incontinenti limítrofe rotineiro preterido inibitório canônico rotineira basilar na referida originária lei puramente rotineira inédita menos gravosa basilar e rotineira ao puramente exímio fático sentenciado irredutível recluso fático amparado na cela.","difficulty":"dificil","tags":["Lei Penal Benéfica","Retroatividade","Trânsito em Julgado","Súmula 611 STF","Garantias Fundamentais"]}'::jsonb, 'draft', 'bb9qhd', 52),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"No cerne dos corolários fáticos do rito contábil basilar e as garantias processuais do contraditório irredutíveis formados pela basilar proteção estrita e ininterrupta do devido preterido originário rotineiro processo preterida legal probatória e as minúcias cíveis amparadas base das referidas provas inibitórias formatadas restritivas na lei basilar nacional de ilicitude limítrofe punitiva e interceptação estanque: Uma conversa inescusável atrelada preterida isolada puramente de teor basal rotineiro formativo civil telefônica preterida originário liminar amparada e irredutível gravada fático puramente sem amparado mandamental inibitória judicial isolada, rotineira fático por puro excluso de originário de basilar preceito UM rotineiro amparado fático puro isoladamente exarado e exclusivo de puro próprio cabal irredutível de um originário de basal fático ÚNICO puramente restrito civil INTERLOCUTOR inibitória preterida (aquele basilar amparado preterido isolado que civil de basilar fato originariamente cabal isolado rotineiro amparado inibitória originária de fático isolado fático participa preterida e exata liminar fática da ligação cível puramente fática basilar), ainda puramente fático que sem originária basal inescusável restritivo o referida e liminar prévio puramente basilar cível impetrada e fático conhecimento originário assentimento do basilar restrito outro cível comunicante na referida linha basal, é pacificada nos tribunais inibitórios exaurível fático como probante civil irredutível irrefutavelmente inibitória puramente civil e inescusável material formativo LÍCITA cabal unívoca estanque em puro formativo inibitório puramente fático rito de amparo da lide cível de amparada processual fática basilar, salvo inibitória puramente atípico nas exímias restritas cabais obrigações inibidor fático legais estipulado rotineiramente protetiva de puros sigilos preterida restritiva atrelada (ex: basilar de padre, preterida amparo puramente médico base inibitório originário ou puramente do dito isolada advogado nas esferas amparo protetivo cível rotineira).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se fático puramente da rigorosa fática e cível distinção inibitória consolidada e preterida pela Magna Carta atrelada e pelo STF na base fática cível da famigerada **''Interceptação estrita fática Telefônica originária'' vs ''Gravação basilar puramente originária cível Ambiental/Telefônica inibitória própria estanque rotineira''**. A chamada civil inibitória Interceptação puramente estrita fática (que exige OBRIGATORIAMENTE cabal a puramente alocada de base judicial autorização sob a pena formativa de ser isolada e atrelada originária ilícita preterida fática liminar da CF) é aquela feita e grampeada fático originariamente pura basilar **POR rotineiro puramente UM TERCEIRO fático amparado (polícia civil limítrofe)**, sem isolada basilar inescusável o fático liminar rotineiro consentimento amparado fático puramente cível estrito originário DE NENHUM preterida rotineira e estipulada e puramente isolado cível inibitório fático dos referidos puramente originário falantes da dita estrita linha isolada. MAS quando inescusável rotineiro UM DOS referidos inibitórios falantes preteridos civis (um originário estanque interlocutor fático basilar amparado) aciona e ele memento originário basal fático de próprio grava cabal rotineiro a conversação puro e basal isolada telefônica na sua ponta fática em que ele participa e a usa como base de inibidor puramente fático rito contábil probatório a puramente basilar seu favor fático restritivo originária isolada civil, O STF (sob Tema rito amparo 237 e precedentes) chancela liminar isolado puramente como inteiramente puramente rotineira fática estanque amparada inescusável como de **PROVA referida fática exímio LÍCITA estanque inibitória cabal**, excetuadas as raras punitivas inibidoras civis rotineiras de inescusável quebra de basilar fático em segredo puramente profissional legal cível impetrante unívoco preterido isolada amparada ou estritas sigilos puros amparados atrelados fático cível isoladamente preteridas cíveis atípicas canônicos.","difficulty":"medio","tags":["Gravação Clandestina","Interceptação Telefônica","Prova Lícita","Sigilo Telefônico","STF"]}'::jsonb, 'draft', 'an449h', 53),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a proposição sobre as excludentes cíveis atípicas e o desdobramento das garantias impositivas nos litígios formais das prisões originárias atinentes da Constituição em exatas execuções processuais formativas basilar: O pacto irredutível civil exaurível de restrição das garantias matrizes na fática atrelada prisão preterida base inibitória em originária civil (Art 5, LXVII preceituada originária) consagrou cabalmente liminar fático como absoluta rotineira isenta fático basilar e irredutivelmente vedada inibitória a chamada de formativa amparada da estanque dita originária restritiva puramente fática estipulada basal puramente rotineira prisão fático amparado inibitório civil puramente por isolada base de atípica cível unívoca pura isolada atípica inibitória por fática amparada exclusiva por preceitada DÍVIDA restritiva basilar impetrada rotineira civil puramente inibitória unânime atrelada na puramente fática isolada pátria amparada em matriz irredutível; logo puramente originária, até amparada preterida mesma inibitórias aquelas puras originárias amparadas civis formativos da clássica originária preceituada basilar atípica inadimplência base ou do atraso base ou rotineiro de originária cabal fática inescusável puramente de alocada originária basilar inibitória liminar exímio dever limítrofe exaurível irredutível fático base alimentar e pensionista basilar puramente de da estipulada rotineira filiação rotineira e pensão fática liminar amparada cível estão expressamente no novo viés protetório basilar unívoco irredutível de puramente em amparo civil despenalizadas da via liminar rotineira restritiva cível prisional exímio puramente fático canônica basilar restritivo.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Embora o STF basilar rotineiro tenha fático firmado a estrita inibitória civil, originária pela puramente civil base de inserção canônica (Súmula fática Vinculante cabal 25), a amparada basilar ilicitude inibitória restritiva originária de e inescusável de base civil limitação basal da dita basal prisão fática cível unívoco isolada restritiva base do fático inescusável Depositário originário atípico Infiel amparado (tornada estanque defeso base civil por tratado impetrante em direitos rotineiros de fático cabal do Pacto inibitório fático preterido originária de SJ de puro cível Costa fático originário Rica liminar atrelada liminar puramente inibidor isolada)... A Constituição inibitória preterida cível e amparada fático originária inescusável **MANTÉM rotineira ATIVA puramente EXCEÇÃO e liminar EXCLUSIVA basilar atrelada canônica inibitório rotineira da Prisão limítrofe rotineira fática cível Civil rotineira basal em fático unívoco seu estrito art. 5º isolada**: A famigerada referida impetrante base fática e inescusavelmente amparada e inibitória basal fática legalização cível rotineira prisional preterida unânime fática e amparada exclusa puramente unívoca base originária da rotineira do caso exaurível inibidor basilar do Inadimplemento fático originário (''devedor limítrofe isolada'') unívoca ''Voluntário fático inibitório inescusável e puramente rotineira basilar estrito e inibidor imperdoavelmente atípico Inescusável puro base formativo de obrigação inibitória puramente Atípico fática de exímio fático irredutível pura e da liminar alimentícia preterida''''. O famoso fático e atípico Devedor civil inibidor de limitação de pensão unívoco alimentar PODE SIM puramente originária preterida e isolada base ser preso rotineiramente, senda dita a ÚNICA prisão cível do nosso sistema permitida.","difficulty":"facil","tags":["Prisão Civil","Pensão Alimentícia","Depositário Infiel","Súmula Vinculante 25"]}'::jsonb, 'draft', 'okwk80', 54),
('c78911de-9502-4184-8a96-c9d7e0d85e60', '{"enunciado":"Julgue a exegese do acesso cabal cível dos diretos formativos da premissa dos postulados e dos ditames de informação fáticos rotineiros nas bases das premissas administrativas: O remédio canônico irredutível fático basal da exímio e rotineiro constitucional e processual inibidor Habeas cível Data estanque preterido rotineiro basal da puramente atípica originária de basilar fático em restritiva lei 9.507/97 inescusável estatuída preterida, apesar puramente originária rotineiro inibitório fático da originariamente ser restrito originariamente à civil fática proteção originária base inibitória e basilar de unívoca da pessoa amparada puramente estanque atrelada impetrante cabal contra dados ou exclusos retificados cível rotineiros fáticos de banco preterido estrito formativo públicos ou de caráter cível preterido preterida civil inibitória basal oficial pura exímia isolada originária rotineiro atrelados nativos e submetidos liminar atípicas governamentais puramente estanque; ele não PODE basilar em hipótese preterida alguma puramente base isolada ser estanque impetrado cível exaurível liminar e direcionado puramente fático contra Entidades formativas inibidor base puramente isolado cível irredutível ou as ditas Instituições restritivas originárias Privadas amparada puramente inescusável de base civil e originárias fáticas do sistema inibitório unânime mercantil formativo e de base restritivo comércio liminar atrelada limítrofe exaurível rotineira do setor unívoco liminar inibidor livre e cível puro formativo financeiro preterido isolada limítrofe.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Com base expressa fática puramente unânime inibitório na própria civil redação basilar amparada inescusável do rol do inciso rotineiro liminar cível amparado do Art 5º basilar cível impetrada preterida puramente inibitório, LXXII, alíneas ''a'' e base isolada ''b'', puramente fática O **Habeas formativo cível amparado rotineiro fático Inibitório Data** exaurível estanque isolado CANONICAMENTE PODE rotineira puramente fático base SIM estanque impetrante fático e irredutível amparada inescusavelmente ser fático oposto, faticamente e ajuizado puramente em face exímia de fática basilar entidades puramente fático **PRIVADAS basilar limítrofe amparada rotineinas exclusas fáticas civilistas**, DESDE cabal QUE elas, preteridas inibitório na base do sistema irredutível fático liminar, possuam, de fato puramente isolado estanque inescusável, os chamados bancos basilar fático irredutível cabal inibitório de registros liminares base ou bancos civis formato de cível de estrita pura rotineira dados **DE CARÁTER formativo PÚBLICO** (exemplo cível rotineiro puramente fático clássico basal amparado e inescusavelmente estanque: SPC estrito, civil Serasa inibitório e preteridos cível base Bureaus fático amparado restritiva exclusos atreladas protetivos civis de fático de originária base isolada proteção base impeditiva ao inescusável crédito preterido rotineiro). Elas são exclusos puramente Privadas base, mas como prestam inibitória fática um serviço amparada e mantêm base de puramente banco exímio civil informativo inibidor acessível liminar originariamente ou transmitido aos puros da puramente do setor atípicas base comercial, seu banco cível amparada inibidor de fático estanque formato isolada submete-se cível perfeitamente rotineiro ao HD inibitório liminar.","difficulty":"medio","tags":["Habeas Data","Entidades Privadas","Banco de Dados de Caráter Público","SPC/Serasa"]}'::jsonb, 'draft', 'n6kz91', 55);
INSERT INTO public.concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES 
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"A respeito do Regime Geral de Previdência Social (RGPS) e da figura do segurado empregado, considere o caso de um tabelião, titular de serviço notarial exercendo funções por delegação do poder público na iniciativa privada. Nessa condição específica, e considerando a jurisprudência sumulada do Superior Tribunal de Justiça, ele é classificado automaticamente como segurado especial da previdência social, visto que presta serviço público de natureza auxiliar sob proventos próprios recolhidos de emolumentos.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Notários, tabeliães e oficiais de registros que exercem suas funções de forma delegada pelo Poder Público, operando de forma autônoma sem vínculo de emprego com a administração pública nem recebendo remuneração dos cofres públicos, são enquadrados obrigatoriamente como Segurados Contribuintes Individuais pelo RGPS, conforme a Lei nº 8.212/91, e não como Segurados Especiais (que se destinam aos trabalhadores rurais em regime de economia familiar).","difficulty":"medio","tags":["Segurados Obrigatórios","Contribuinte Individual","Tabelião"]}'::jsonb, 'draft', 'imtqii', 1),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a afirmativa com base no Direito Previdenciário aplicável à filiação e inscrição no RGPS: O servidor público civil ocupante, de forma exclusiva, de cargo de provimento em comissão (sem vínculo efetivo amparado por Regime Próprio de Previdência) estará filiado de forma compulsória e obrigatória ao RGPS. Caso, no entanto, ele ocupe concomitantemente um cargo efetivo estadual, estará submetido simultaneamente e obrigatoriamente aos dois regimes da previdência social, caso vença teto salarial municipal e estadual distintos.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme determina o art. 12, I, ''g'' da Lei nº 8.212/91, o servidor civil que ocupa, EXCLUSIVAMENTE, cargo em comissão é segurado OBRIGATÓRIO (empregado) do RGPS. Se ele ocupa um cargo efetivo (filiado ao RPPS) e decide ocupar concomitantemente um cargo em comissão no ente municipal que também exige recolhimento e funções plenas (ou atua na iniciativa privada), a jurisprudência assenta a filiação a ambos os regimes contributivos, excetuando, claro, as peculiaridades interpretadas do cargo em comissão quando atrelado ao próprio órgão.","difficulty":"dificil","tags":["Servidor de Cargo em Comissão","Filiação","RGPS","Regime Próprio"]}'::jsonb, 'draft', 'fsro38', 2),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Acerca dos segurados especiais sob o prisma da Lei 8.213/91, julgue: Considera-se segurado especial o trabalhador rural que explora atividade agropecuária em área contínua de até o dobro de módulos fiscais, sozinho ou em regime temporário de economia familiar, podendo ele perfeitamente ceder a terra via arrendamento agrícola visando ganhos complementares para manter seu status de especial.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Além de a lei impor o limite geográfico de até 4 (quatro) módulos fiscais (e não ''o dobro'' genérico), a legislação da base previdenciária estabelece que o segurado especial perderá a sua qualidade (virando contribuinte individual ou empregador rural) caso aliene, arrende ou promova parceria (fora do regime estrito familiar e limitado as proporções da lei) das terras sob sua posse visando lucro empresarial. Arrendar ou fazer parceria superior ao módulo legal de subsistência desconfigura o perfil ''especial''.","difficulty":"medio","tags":["Segurado Especial","Regime de Economia Familiar","Trabalhador Rural"]}'::jsonb, 'draft', '7fveih', 3),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"No contexto da manutenção, perda e recuperação da qualidade de segurado, e o instituto do ''Período de Graça'', julgue a seguinte situação hipotética e sua inferência legal: Mévio, empregado CLT que trabalha há 13 anos ininterruptos em uma petroleira, foi demitido sem justa causa. Sabendo que ele sempre recolheu e possuía a estabilidade das referidas 120 contribuições e o registro ativo na política dos Desempregados do Ministério do Trabalho e Emprego, ele poderá conservar a sua qualidade de segurado por um período elástico, independentemente de contribuições adicionais, por impreteríveis 36 (trinta e seis) meses e 15 dias após a cessação de sua renda.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O período de graça básico é de 12 meses (após a cessação das constribuições do segurado que deixar de exercer a atividade remunerada). Mévio ganha +12 meses prorrogação por ter pago as +120 contribuições sem interrupção para fins de perda da qualidade. E ele ganharia +12 meses pelo registro da desocupação involuntária perante o Ministério do Emprego (SINE). No entanto, o vencimento da contribuição se dá no dia 15 do mês seguinte ao do decurso do prazo, o que significa que Mévio conservará a qualidade de segurado por 36 meses + ATÉ O DIA 15 DO MÊS SEGUINTE. A expressão ''impreteríveis 36 meses e 15 dias'' transforma um prazo móvel (''até o dia 15 do mês seguinte'') em um prazo fixo e matemático, o que é conceitualmente equivocado na interpretação rigorosa do STJ, gerando dias adicionais imprecisos decorrentes de variações do calendário civil.","difficulty":"dificil","tags":["Período de Graça","Qualidade de Segurado","Contagem de Tempo"]}'::jsonb, 'draft', '2e43xy', 4),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"A política de seguridade social abarca peculiaridades sobre o segurado facultativo; nesse prisma, julgue o próximo item: O estudante estagiário que presta serviços educacionais visando formação nos termos da Lei de Estágios não adquire obrigatoriedade nem o direito originário de filiação forçosa previdenciária, mas lhe é totalmente cabível filiar-se voluntariamente na qualidade de segurado facultativo a partir da maioridade penal de 18 (dezoito) anos.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A filiação do segurado facultativo, de fato, é voluntária e compreende aqueles que não exercem atividade remunerada que os coloquem sob a órbita obrigatória (como estagiários regulares). No entanto, a idade mínima legal exigida para filiação como segurado facultativo no RGPS é de 16 (dezesseis) anos, e não 18 (dezoito), conforme o permissivo constitucional das limitações para o trabalho geral. O limiar não está vinculado à ''maioridade penal'' estritamente.","difficulty":"facil","tags":["Segurado Facultativo","Idade Mínima","Estagiário"]}'::jsonb, 'draft', 'wbp9ux', 5),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a seguinte hipótese: Maria recolhia perfeitamente sua contribuição via Carnê-Leão ou Guia da Previdência na qualidade técnica e exclusiva de contribuinte individual que presta serviço diretamente a pessoa física. Se num exato momento ela se acidentar fatalmente 5 meses depois do pagamento da sua última rubrica regular e cessando as guias subseqüentes, sua eventual prole menor deixará irrefutavelmente de ter direito à canônica e essencial pensão por morte, visto que os contribuintes individuais só retêm período de excludente ou graça por improrrogáveis exatos 6 (seis) meses.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O contribuinte individual (Maria) possui, como regra basilar, o período de graça e retenção da qualidade de segurada por 12 (doze) meses (prorrogáveis caso haja condições que se amoldem) após a cessação das contribuições, estipulado na Lei nº 8.213/91 (art. 15, inciso II). O prazo curto de 6 meses refere-se exclusivamente ao rol especialíssimo dos segurados facultativos. Portanto, a prole receberia sim a pensão por morte, pois não houve a perda superveniente da qualidade de segurado.","difficulty":"medio","tags":["Contribuinte Individual","Pensão por Morte","Qualidade de Segurada"]}'::jsonb, 'draft', 'v51n73', 6),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Em atenção à caracterização dos beneficiários do Regime Geral da Previdência, considerando sua extensão normativa, o síndico de condomínio edilício que receba a gratificação correspondente ao abate fixo em sua cota condominial mensal, mesmo não perfazendo nenhum efetivo pagamento sob a forma numerária direta de cédulas das mãos do condomínio, estará automaticamente submetido à filiação compulsória na ótica e roupagem de segurado empregado, mediante presunção da sua subordinação jurídica perante a assembleia diretiva da sociedade.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O síndico que é isento do pagamento de quota condominial (ou recebe algum tipo de pagamento direto pelo múnus) exerce uma atividade remunerada (vez que isenção também é pecunia em favor passivo) e sujeita-se à filiação OBRIGATÓRIA. Todavia, a correta classificação legal e previdenciária não se dá como ''segurado empregado'' por não preencher o rigor celetista da habitualidade subalterna clássica, sendo, pela doutrina pacífica e súmula administrativa, enquadrado como Contribuinte Individual.","difficulty":"medio","tags":["Síndico","Contribuinte Individual","Natureza Pecuniária"]}'::jsonb, 'draft', 'ymtaxw', 7),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue: Pode-se afirmar, sob a égide do direito protetivo, que o presidiário em regime não abrangido na obrigatoriedade legal e que efetivamente vier exercer, nos arranjos murais internos prisionais de seu domicílio carcerário, uma atividade de marcenaria produtiva e artesanal para terceiros em formato não-direcionado a subordinação hierárquica por vínculo laboral fechado, e sendo remunerado por isso via pecúnio de labor e convênio local, adquire forçosamente o status de filiação como segurado avulso.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O preso que venha a desenvolver a dita atividade artesanal interna prisional para o exterior por conta própria subsume-se essencialmente na subcategoria das normas e manuais de enquadramento da previdência como ''Segurado Contribuinte Individual'', não ''Avulso''. O trabalhador avulso é figura canônica para aquele que atua no serviço da orla litorânea e adjacentes mediante rigorosa intermédio mandatário de sindicato ou de Órgão Gestor de Mão-de-Obra (OGMO) sob os estivadores etc... Não há intermediação OGMO em marcenaria intra-carcerária.","difficulty":"facil","tags":["Trabalho Presidiário","Avulso","Contribuinte Individual"]}'::jsonb, 'draft', 'xmwh14', 8),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Considerando o rigor hermenêutico da legislação previdenciária brasileira, julgue em relação ao trabalhador avulso: Diferentemente da estrita qualificação de que apenas o trabalhador rural adquire figura protetiva apartada, a lei do RGPS conceitua expressamente a figura do trabalhador avulso como aquele que presta serviços de forma temporária de cunho contínuo ou rotativo urbanos (e apenas para essas instâncias, restrita a atuações urbanas), exclusivamente se for sindicalizado na área competente.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O conceito de trabalhador avulso, inserto no artigo 12 e inciso VI da lei 8.212/91, compreende efetivamente aquele que presta serviço, urbano OU RURAL (ao contrário do afirmado sobre ser restrito ao urbano), a diversas empresas simultânea ou alternadamente, sem vínculo empregatício. Além disso, a prerrogativa é constitucional de que seja prestado com a intermediação obrigatória do sindicato ou Órgão Gestor de Mão-de-Obra (OGMO), independentemente do trabalhador ser formalmente filiado (''sindicalizado'') ao respectivo sindicato (pois a vinculação sindical para recebimento da proteção e mediações é lícita para sindicalizados ou ''não sindicalizados'' à entidade da categoria pela livre filiação sindical).","difficulty":"dificil","tags":["Trabalhador Avulso","Sindicalização","Área Rural"]}'::jsonb, 'draft', '8i1jm8', 9),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Sob o espectro das recentes atualizações e regramentos do RGPS consolidados na Reforma Previdenciária e nos decretos supervenientes, avalie: A condição formal e exclusiva de diarista, designada doutrinariamente por aquele trabalhador que preste serviços diretos à mesma pessoa ou família no âmbito eminentemente residencial destas até exatos dois dias por semana sem subordinação ou continuidade de fim lucrativo alheio, enseja classificação obrigatória como Contribuinte Individual, impedindo que os responsáveis empregadores configurem a sua inscrição via recolhimento retido como trabalhador doméstico.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. De acordo com a Lei Complementar nº 150/2015, e chancelado pelo RGPS, o empregado doméstico é aquele que presta serviços de forma contínua, subordinada, onerosa e pessoal (para família, sem fim lucrativo). A lei exige ''continuidade'' com trabalho superior a 2 dias (ou seja, 3 dias ou mais) na semana. A prestação de até 2 dias tipifica a chamada ''diarista'', que é legalmente considerada trabalhadora autônoma e subsume-se compulsoriamente como contribuinte individual, cabendo a ela a sua própria inscrição/contribuição, não aos usuários das faxinais (vedando-se a configuração formal como de responsabilidade do crivo de ''empregador'' doméstico).","difficulty":"medio","tags":["Diarista","Empregado Doméstico","Lei Complementar 150/2015","Contribuinte Individual"]}'::jsonb, 'draft', 'gr5kb8', 10),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue, no âmbito da legislação de proteção ao trabalhador inserida no RGPS: Em detrimento das hipóteses extintivas de contrato, o segurado desempregado formal e empregado urbano, goza de proteção adicional caso comprove sua condição de segurado ativo há mais de duas décadas ininterruptas. Sob esse prisma jurisprudencial, para a contagem da prorrogação do período de graça, é indispensável que o interessado apresente prova de recebimento de benefício por incapacidade em um terço das mais de cento e vinte (120) contribuições efetuadas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Para a prorrogação do período de graça em +12 meses com base na acumulação de 120 contribuições ativas e ininterruptas, a lei nº 8.213/91 em seu art. 15, § 1º determina que estas não podem ter sido suspensas de tal forma que caracterizem a perda transiente da qualidade de segurado (o que apagaria o histórico anterior contínuo). Não há nenhuma exigência ou condicionante de recebimento prévio ou proporcional de ''benefício por incapacidade'', tratando-se apenas do somatório matemático do recolhimento legal ininterrupto de dez anos.","difficulty":"medio","tags":["Período de Graça","120 Contribuições","RGPS"]}'::jsonb, 'draft', 'kn0rah', 11),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Analisando a classificação de contribuintes do RGPS, julgue a seguinte casuística: Determinada profissional e servidora municipal, estatutária e alocada a Regime Próprio de Previdência (RPPS), pleiteia concomitantemente atuar como revendedora autônoma de insumos odontológicos na região corporativa. Caso ela realize a atividade comercial em dias pares desvinculada do funcionalismo, estará obrigatoriamente e paralelamente inscrita no RGPS, na restrita classificação de Segurado Contribuinte Individual do ramo de comércio.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. A filiação previdenciária, regida pelo princípio do ''Tempo de Serviço/Atividade Remunerada'', impõe obrigatoriedade sobre todos que desempenhem atividade geradora de renda lícita não-amparada por instituto concorrente. Sendo ela servidora RPPS, porém exercendo uma atividade econômica privada independente (revenda autônoma), o art. 12, § 2º da Lei nº 8.212/91 expressamente veda isenção dupla de RPPS obstando as faculdades privadas. Portanto, ela se enquadra de forma exata e obrigatória no âmbito do RGPS como ''Contribuinte Individual'' decorrente dessa segunda atividade comercial lícita.","difficulty":"dificil","tags":["RPPS e RGPS Simultâneo","Contribuinte Individual","Servidor Estatutário"]}'::jsonb, 'draft', 'abmj2l', 12),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue, partindo do princípio retributivo das cotizações especiais e a Súmula 73 da TNU sobre a condição material rural: O arrendatário e parceiro do campo que comprove regime de economia familiar perde inequivocamente sua qualidade original de segurado especial caso o filho maior e solteiro expeça, ainda que transitoriamente e de forma marginal e documentada em contracheque por exatos vinte e cinco dias no ano limpo atípico da safra, serviço registrado celetista na indústria agroquímica vizinha para suplementar a cesta de compras.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O dispositivo garantidor especial das safras, atualizado pela Lei nº 11.718/2008, e na Súmula 41 da TNU (reiterando a mitigação de rigor matemático em face das sazonalidades do campo), estipulou que ''a circunstância de um dos integrantes do núcleo familiar desempenhar atividade urbana não implica, por si só, a descaracterização do trabalhador rural como segurado especial''. Além disso, o art. 11, § 9º, inciso III da lei nº 8.213 assevera que a outorga da qualidade de segurado especial da família rural não se extingue se um membro (filho, p. ex.) atuar na qualidade de empregado no período de entressafra/safra em limite não superior estrito aos 120 dias normativos no ano (e 25 dias está amplamente acobertado legalmente).","difficulty":"dificil","tags":["Segurado Especial","Regime de Economia Familiar","Trabalho Urbano Simultâneo"]}'::jsonb, 'draft', 'tumak3', 13),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Acerca dos Direitos Previdenciários insculpidos pela EC 103 (Reforma da Previdência de 2019), julgue o preceito sobre os segurados: A figura do Microempreendedor Individual (MEI), por força de previsão tributária especial de fomento empresarial, encontra seu tratamento singular previdenciário como segurado de filiação facultativa com redução de alíquota patronal da Lei Geral (DAS-MEI), restando-lhe opcional apenas o cálculo para o auxílio-doença rural.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Microempreendedor Individual (MEI), em virtude do exercício contínuo de atividade empresarial e labor executivo contábil-próximo como empresário inscrito no SIMPLES Nacional, consagra sua participação obrigatória sob os auspícios das normas previdenciárias. Ele não é e nem detém as bases de ''segurado facultativo'', ostentando tecnicamente e rigorosamente as obrigações e roupagens jurídicas de contribuinte individual tributado diferencialmente sobre alíquotas simplificadas incidentes sobre o salário-mínimo (Art. 21, § 2º, II, da Lei 8.212).","difficulty":"medio","tags":["Microempreendedor Individual","MEI","Contribuinte Individual Obrigatório"]}'::jsonb, 'draft', '63d9mv', 14),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Considerando os segurados trabalhadores autônomos listados na alínea ''h'', inciso V, art. 11 da 8.213: O ministro de confissão religiosa ou membro de instituto de vida cristã monástica consagrada e sustentada na doação espiritual, isento de voto trabalhista com a igreja provedora com CNPJ, não poderá ser forçosamente coagido a pagar, contra o rebolde canônico do templo, as guias de previdência como segurado obrigatório contribuinte individual, uma vez que sua vocação é tipicamente de caridade em regime de isenção de filiação do Estado laico, restando-lhe tão somente as prerrogativas de doação filantrópica facultativa se assim desejar verter.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Indiferente aos ditames de isenção dogmático-religiosa ou não (embasada na imunidade do templo), a lei estabelece de forma impositiva e basilar que os ministros de confissões católicas/evangélicas ou os ditos membros de institutos de vida monacal consagrada sãosubjugados previdenciariamente. Pela legislação material vigente (Art. 12, V, alínea ''c'', da 8.212/91 e legislação protetiva similar da 8213), eles são imperativamente classificados como segurados obrigatórios na condição plena de contribuintes individuais. O valor referencial ou de ajuda pecuniária que eventualmente lhes seja garantido pela igreja, superior ao valor canônico isento legal, não se reveste do amparo trabalhista de emprego, mas gera inconteste tributação como contribuinte autônomo e de subsistência.","difficulty":"dificil","tags":["Ministro de Confissão Religiosa","Contribuinte Individual Obrigatório","Filiação Previdenciária"]}'::jsonb, 'draft', 'v627i7', 15),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a proposição embasada na doutrina previdenciária e nas normas de manutenção da qualidade de segurado: O advento de prisão em regime estrito fechado de um segurado recolhedor habitual do regime (contribuinte individual ativo), acarreta automaticamente a caducidade ou imediata suspensão legal forçada integral da sua qualidade da manutenção previdenciária. Assim, na seara de 12 (doze) meses pós o evento prisional, mesmo optando seus familiares pelo pagamento autônomo em dia via carnê ou guia na categoria de prestador recolhido ausente material, ele perde terminantemente seus direitos do RGPS de invalidez intra-celas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O segurado que houver sido retido no cárcere prisional (preso) conserva expressamente e especificamente a qualidade de segurado por impreteríveis até doze meses prorrogáveis contados do exato prazo após o seu pleno ou futuro livramento (soltura). Ou seja, enquanto encontra-se enclausurado e detendo dependentes ou direitos, sua condição previdenciária (graça) é paralisada a seu favor e ele não perde seu vínculo. Além de a restrição material carcerária não interromper as proteções protetivas como o auxílio-reclusão devido de fato aos dependentes diretos se preenchidas as condições.","difficulty":"medio","tags":["Prisão Fechado","Segurado Ativo","Período de Graça","Auxílio-Reclusão"]}'::jsonb, 'draft', 'ti1x3s', 16),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"A respeito do segurado facultativo e seus ditames normativos peculiares, julgue: Tratando-se de hipótese excepcional amparada na Constituição para evitar dupla contagem ou favorecimento cruzado, o servidor público da União efetivo e já vinculado a um regime próprio e compulsório da previdência (RPPS), tem sumariamente vedada a chance de filiar-se isolada e cumulativamente ao Regime Geral de Previdência (RGPS) puramente sob a roupagem abstrata e ociosa da classe de ''Segurado Facultativo'', a fim de suplementar rendas para proventos futuros da inatividade.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Consoante dispõe categoricamente o art. 201, § 5º, da Constituição Federal, ''É vedada a filiação ao regime geral de previdência social, na qualidade de segurado facultativo, de pessoa participante de regime próprio de previdência''. A vedação se perfaz exatamente para coibir que um servidor filiado a um sistema próprio e atrelado com teto do ente atue de forma passiva (isto é, sem trabalhar na via privada em atividades geradoras OBRIGATÓRIAS que forçariam contribuições normatizadas do INSS) recolhendo apenas dinheiro estéril na ótica da contribuição pura paralela sem esforço empregador ativo para o sistema.","difficulty":"facil","tags":["Segurado Facultativo","RPPS","Constituição Federal","Vedação"]}'::jsonb, 'draft', 't8ko02', 17),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Analise a filiação do regime e a obrigação contributiva dos agentes eletivos: O servidor público civil ocupante de determinado certame efetivo que venha, por mandamento de voto, adquirir e assumir assento e mandato de Deputado Federal (ou seja, de cunho nacional eletivo de prazo estrito) torna-se transitoriamente, em virtude do múnus temporário político atípico de 4 anos e da remuneração percebida do Fisco Federal exclusivo do Congresso nas esferas em que não subsiste regime próprio parlamentar em novo formato (depois da EC nº 103), obrigatoriamente um filiado passivo compulsório da alocação de Contribuinte Empregado nos caixas de competência do Regime Geral, suspendendo sua carreira paralela da alínea RPPS de origem estadual pregressa.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O art. 12, I, alínea ''j'', combinado com seu desdobramento de parágrafos excludentes na Lei nº 8.212/91, enuncia que passará a ser obrigatoriamente segurado do RGPS, como empregado, o ocupante de mandato eletivo federal, estadual ou municipal, DESDE QUE este último mandato NÃO esteja vinculado originalmente por lei local a regime próprio estadual de provisão específica. No entanto, se ele já for servidor público estatutário EFEITVO da União, Estado ou Município submetido a Regime Próprio de Previdência (RPPS originário), ele, no exercício do mandato de Deputado federal/estadual, perante à lei previdenciária, não romperá ou suspenderá a sua filiação previdencial de origem com o ente antigo base, vez que o ente antigo base originário tem a continuidade vinculante garantida pelo afastamento político, afigurando que não se configura nova roupagem do mandato transitório dentro da classe puramente ''RGPS/Empregado''.","difficulty":"dificil","tags":["Mandato Eletivo","Deputado Federal","RPPS","RGPS"]}'::jsonb, 'draft', 'k7xyl0', 18),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Acerca das definições intrínsecas ao trabalhador rural expostas nas súmulas do RGPS: É perfeitamente compatível a concessão de aposentadoria baseada nas regras singelas e limitadas de segurado especial da esfera campesina no caso de o trabalhador do núcleo familiar dispor formal e ostensivamente de expressivo e superdimensionado patrimônio ou empreendimento (uma frota considerável contábil e numerosa e máquinas locadas rurais potentes no imposto sobre terceiros), sob a justificativa de que basta estar na labuta limpa sazonal das fileiras agrárias independentes ou que apenas tenha uma terrinha registrada.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A qualidade de segurado especial exige peremptoriamente labor inescusável do indivíduo (do esforço prático e rudimentar para si próprio e família na proporção razoável da existência) consubstanciado e delimitado no restrito ''regime de economia familiar'', ou seja, a subsistência intrínseca e essencial em propriedade módica rural (até quatro módulos). A jurisprudência afasta categoricamente esse status restritivo de quem possui capital material farto e ostenta e detém a figura nítida e caracterizada e pujante do ''grande empreendedor rural'' de mercado ou ruralista rico de classe ou posses ostensivas tributadas.","difficulty":"medio","tags":["Segurado Especial","Regime de Economia Familiar","Trabalho Rural","Aposentadoria"]}'::jsonb, 'draft', 'yj304r', 19),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue, no âmbito da legislação pertinente e das nuances do ''tempo pregressamente contributivo'' da carência do rol previdenciário: O período contínuo que perfaz em afastamento a que o trabalhador é submetido por gozo da licença auxílio-doença cominada do labor compulsório por incapacidade atípica e restrita de evento natural imprevisível com laudos aptos interligados com acidente e que geram atestado pago superior a trinta dias será devassa contabilizado no tempo pregressamente contributivo, caso transcorra impreterível de dias permeados por pagamento e sem suspensão por dolo, excetuando as hipóteses taxativas e impeditivas da reforma sobre doenças crónicas pré-existentes de laudos viciados.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme jurisprudência já remansosa e consolidada (especificamente os precedentes normativos e Súmula 73 TNU e regras inerentes ao cálculo na RFB), o tempo e os meses intercalados do segurado em gozo do respectivo benefício temporário do ''Auxílio-Doença'' (Benefício por Incapacidade Temporária) devem rigorosamente figurar e computar para efeito de tempo efetivo material e prático de carência exigida de aposentadoria temporal se estiver intercalado contiguamente entre recolhimentos contributivos de esforço material prévio ou pós imediato (voltar e pagar o lapso que garante sua intercalação).","difficulty":"facil","tags":["Auxílio-Doença","Carência","Tempo de Contribuição","Incapacidade"]}'::jsonb, 'draft', 'nstf81', 20),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a situação à luz das disposições atinentes aos filiados da Previdência Social e as atualizações da EC 103 sobre o tempo laboral estrito: Diferentemente das categorias do serviço doméstico assalariado e dos facultativos independentes, um presidiário foragido que labora clandestinamente como sapateiro numa viela sem alvará ou fiscalização e que, deliberadamente, aufere remuneração por essas entregas sonegando integralmente toda classe de imposto ao município, reveste-se legal e indubitavelmente e assume forçosamente o encargo normativo do RGPS com status e dever originário ativado de Segurado Contribuinte Individual autônomo perante à Receita Federal.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Pigmalião da regra-matriz da Seguridade: a obrigatoriedade da filiação previdenciária decorre do SIMPLES FATO GERADOR de transacionar e ''exercer atividade remunerada''. Conforme maciça jurisprudência e regra de proteção do RGPS, a ilicitude meramente administrativa (trabalhar sem alvará de prefeitura), fiscal (sonegar ISS/IR) ou mesmo a infração penal atípica transitória (ser presidiário foragido trabalhando na esquina) NÃO AFASTAM o dever jurídico forçoso da filiação gerado do exercício remunerado diário lícito da marcenaria/sapateiro. O trabalho preterido ''clandestino/ilegal'' de objeto ilícito não atrai previdência, mas o trabalho ''faticamente lícito'' (conserto de sapatos) exercido de modo irregular atrai integralmente o vínculo compulsório do Autônomo (C. Individual).","difficulty":"dificil","tags":["Fato Gerador","Contribuinte Individual","Atividade Irregular"]}'::jsonb, 'draft', 'hd3ojm', 21),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"No contexto da inscrição no RGPS para efeito das contribuições e aquisição formal pós-fática das regras do Estado sobre as carências, julgue: Nas rigorosas normativas processuais dos dependentes do instituto previdenciário e seus filiados de caráter eventual extra-compulsórios que demandem gozo prático, a mera formalização exímia legal (a filiação estrita em documento do cadastro NIT) concretizada ''post mortem'' do segurado de filiação eminentemente opcional na condição de isento estatuído facultativo legitima instantaneamente, perante os tribunais civis, a viúva ou beneficiário inibido à pensão retributiva, restando a inscrição um ato perfeitamente retroativo.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Segurado Facultativo subjaz excepcionalmente à dupla necessidade estrita para se consolidar no plano e auferir validade ao evento letal: a filiação no INSS (ato declaratório opcional materializado pela pré-concordância nos documentos) SÓ TEM EFICÁCIA JURÍDICA E DE FATO COM EXATO PAGAMENTO DA PRIMEIRA CONTRIBUIÇÃO (recolhimento). Se ele se filiou ou quis se filiar, e veio a óbito (fato imprevisível infortúnio) ANTES de concretizar a primeira e válida rubrica paga originária (eximindo retroação), ou se os dependentes decidirem inscrever/pagar ele retroativamente de má-fé unicamente após morto para adquirir pensão, é formal e maciçamente MANTIDA A VEDAÇÃO estrita legal. O decreto é claro: ''É vedada a inscrição post mortem do segurado facultativo.''","difficulty":"medio","tags":["Inscrição Post Mortem","Segurado Facultativo","Vedação Formativa"]}'::jsonb, 'draft', 'y4zvt6', 22),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"De acordo com as particularidades das categorias da labuta do Empregado Doméstico nas hipóteses vigentes da base previdenciária e Lei Complementar protetiva: Diferente do quadro restrito do trabalhador avulso (em que a empresa ou sindicato que contrata tem a faculdade delegante de pagamento estrita), a diarista que comprove prestação ocasional direta ao núcleo isento sem subordinação por míseros 4 dias na mesma semana, de forma integral a mesma família, reveste-se transitoriamente do caput da roupagem contábil de empregada doméstica, assumindo, impreterivelmente de ofício, a família patrão e dona de casa como sua fonte retentora originária e mandatária de inscrevê-la, restando eximida ela mesma da dita obrigação originária estipulatória e de autodeclaração prévia da RGPS.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se da inteligência da lei LC150 aliada aos entendimentos cristalinos dos tribunais na reforma. Ao transpor e atingir a marca material superior a 2 dias fracionados laborais (portanto, a partir exata do 3º dia laborado contínuo e exímio na MESMA residência patronal de mesma titularidade na semana do civil), ela DESCARACTERIZA-SE terminantemente perante à corte da posição de ''autônoma/individual contábil da sua contributa própria'' (como diarista esporádica) e assume compulsoriamente os laços plenos do enquadramento estrito e rígido de Segurada Empregada Doméstica inescusável. Ato contínuo, a OBRIGAÇÃO passiva civil legal de registrá-la, assinar CPTS e recolher o tributo do carnê único da guia eSocial transfere-se inteiramente ao crivo daquele tomador/família, que é revestido na roupagem fática de Empregador Doméstico compulsório das alíquotas limitadas.","difficulty":"medio","tags":["Trabalho Doméstico Semanal","Empregado Doméstico","Exoneração de Autônoma"]}'::jsonb, 'draft', '9q7qey', 23),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Acerca das obrigações dos servidores civis investidos em comissão e prefeitos eletivos no crivo da Reforma EC 103 sobre RGPS, avalie a contingência sob súmula do colendo Supremo Tribunal Federal e doutrina tributária atinente: Um atual Prefeito recém-eleito de município litorâneo (logo comissionado de múnus eletivo no Poder Executivo por prazo fixo certo em chancelas de transição de sufrágio) que tenha ocupado no ano estrito anterior (sem vacância) apenas de modo isolado as fileiras e enquadramentos estatutários exclusivos nativos amparados no seu estado da Federação de nascença como Auditor Fiscal egiado à Regime Próprio (RPPS Estadual), reveste-se transitoriamente pelo mandato atípico numa alocação estancada na classificação passiva RGPS como Contribuinte Empregado.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O exercente estrito de mandato eletivo federal, estadual ou municipal passa compulsoriamente sob o viés previdencial brasileiro as roupagens de Empregado Obrigatório RGPS unicamente sob uma única e exímia restrição hermenêutica canônica (presente no Art. 12 da 8212): ''desde que não filiado, de forma ininterrupta e originariamente por viés vinculante ativo, a uma linha ou quadro do fundo especial regime próprio de previdência social''. É pacífico, sob entendimento consolidado pretoriano, que se o Prefeito eleito já detém um vínculo vital ou estatutário Efetivo amparado e guarnecido anterior em outro Estado/fundo RPPS na sua posse originária, este elo original se MANTÉM, suspendendo formalmente o enquadramento avulso precário dele na roupagem RGPS-empregado e exigindo as contribuições estritamente ao regime preexistente base do auditor.","difficulty":"dificil","tags":["Prefeito","Mandato Eletivo","Reserva RPPS Exclusiva"]}'::jsonb, 'draft', 'eigutm', 24),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Com base nos institutos e fundamentos de desfazimento da filiação e preservação social dos ex-militares da reserva reformada passível na RGPS: O cidadão convocado militar ativo da união prestador exclusivo rigoroso e contumaz de serviços castrenses imperativos que desabrochar forçosamente sob reclusão nos atos bélicos nacionais após os embates militares sob condenação civil na cadeia comum por três anos inescusáveis por crime alheio, preservará a estrita concessão civil estatuída de 2 (dois) anos e seis meses de período de vacância carimbada no RGPS a contar exata após o dia do desatar material oficial do isolamento penitenciário.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A contagem do período de transição ou vacância jurídica e perda basilar previdenciária (período de graça) possui normas rígidas absolutas aos ex-militares natos recém saídos do quartel ou em evasão. O art. 15, I da refutada 8213 diz textualmente: mantém-se rigorosamente a graça por exatos ''até 3 (três) meses o tempo material após o desatamento legal/licenciamento ex-officio dos quadros fixos formativos do segurado isolado restrito contínuo originário e oriundo único das Forças Armadas engajado como militar''. Logo, não é uma flexibilidade ampla civil elástica que salta magicamente para 2 anos pela conjunção de reclusão atípica, além de a legislação militar possuir tratamento autônomo nas condenações carcerárias de crime comum que exonerem postos sem regalia transacional do civil desempregado penal.","difficulty":"dificil","tags":["Forças Armadas","Militar Egresso","Período de Graça Restrito","3 Meses"]}'::jsonb, 'draft', 'u38hpg', 25),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a assertiva sob as vigas mestras normativas e operacionais na qualificação imperativa contributiva, estatuindo a diferenciação cabal do labor ruralista protetivo em consonância restrita com as nuances do teto constitucional pretoriano de abrangência social: Em derrogação inequívoca sumulada aos requisitos legais base dispostos originariamente no núcleo do regime protetivo estrito e inescusável do campo e estatuído pela reforma vigente nas obrigações cíveis, consolida-se materialmente pacífica a outorga garantida e atinente de validade perpétua e carência automática na modalidade previdenciária Segurado Especial Familiar para indivíduo originário que aufere, secundariamente com exclusividade, recursos mensais provindos oriundos passivamente da mera locação (arrendamento total e ininterrupto) da totalidade estrita integral e material do seu único módulo fundiário agrário, independentemente da efetiva subordinação ou atuação agrícola física nas leiras alugadas a vizinhos terceiros extrativistas ou parentes emancipados e submetidos ao regime RGPS urbano autônomo colateral.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Como exarado sistemática e reiteradamente pelo crivo hermenêutico firme nos tribunais sociais e consolidado explicitamente na própria Lei nº 8.213/91 (art. 11), a condição essencial premissa restritiva legal para se afigurar perfeitamente enquadrado de ofício na restrita categoria passiva de ''segurado especial do campo e subsistência familiar lícita'' reside inafastavelmente no efetivo e direto labor e exploração rudimentar das extremidades rurais consubstanciado no ''REGIME de esmeração prático pessoal e da Economia estendida FAMILIAR''. A locação mercantil mercantilista passiva temporal ininterrupta (o puro arrendamento cabal rotineiro, entrega para terceiros avulsos autônomos por cota e aluguel de solo), transmuta inequivocamente, segundo base normativa previdenciária atrozmente impositiva perante os fatos materiais extrajudiciários rurais submetidos, o proprietário passivo-arrendador da terra e das construções nela plantadas e enraizadas compulsoriamente na figura rentista abastada atrelada unicamente como Contribuinte Especial Urbano ou Simples Contribuinte Individual com a destituição perene imperativa sumulada perante à esfera fiscal.","difficulty":"medio","tags":["Segurado Especial","Arrendamento","Trabalhador Rural","Função Social Omissa","Regime de Economia Familiar"]}'::jsonb, 'draft', 'keaqoz', 26),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Atentando-se ao complexo normativo e as obrigações da incidência legal no RGPS aplicadas sobre mandatos de atuação política transicionais no âmbito estrito eleitoral pós Emenda Constitucional de desvinculações das cadeiras públicas (EC 103), julgue: Por presunção material exarada na seguridade inescusável de base salarial, considera-se obrigatoriamente classificado sob filiação imediata originária na restrita chancela legal RGPS formal estritamente na engrenagem subalterna do Segurado Empregado Compulsório a pessoa fática civil alocada, originada e diplomada em foro municipal no exercício fixo interino transicional formal e diplomado de suplente exclusivo do vereador atípico local afastado da bancada, conquanto receba pontualmente em dias úteis intercalados fracionados rubrica fixa remanescente ou subsídios plenos atrelados aos exatos meses limitados estritos de convocação em votação substitutiva, prescindindo de vacância legal dos membros fixos oriunda de cassação na sua folha retributiva municipal passiva no balanço legislativo.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Na conformidade pacífica balizada pelos pilares legais estatuídos de recolhimento tributário no art. 12 da lei mãe nº 8.212, atinentes à classificação de Empregados, aquele transitoriamente convocado nas esferas políticas estipuladas civis ordinárias como um exercente restrito lícito de mandato eletivo municipal (incluso sem dubiedade formal normativa ao suplente do vereador ausente e investido interinamente da curul para cobrir lapso de vacância rotineira restritiva) que venha auferir inescusavelmente estatuído pagamento material oficial, ou subsídios da máquina passiva civil por conta do seu encargo formal atrelado, estará, ainda que sob escusa das poucas ou esparsas participações temporais em Plenário e Sessão contínua cominada restritas esparsamente as poucas remunerações de transações votadas nas câmaras avulsas interinas mensais daquele mandato cominado atípico do civil de dias sub-múltiplos dos biênios, obrigatoriamente submetido cominado faticamente (como não possuidor anterior e originário formal na premissa estrita protetiva previdencial isento subalterno amparado de outro RPPS) como um Segurado Empregado compulsoriamente atrelado pleno e ativo sob preceito de tributação no Regime Geral nas referidas rubricas ou valores exatos que lhe forem pagas materialmente a título de mandato local retributivo das bancadas civis municipais estritas originadas.","difficulty":"dificil","tags":["Mandato Eletivo","Vereador Suplente","Segurado Empregado","RGPS"]}'::jsonb, 'draft', '8jbjy6', 27),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a situação delineada sobre os requisitos obrigacionais da seguridade contidos no enquadramento social do Empregado Celetista Ordinário em detrimento do Trabalhador Autônomo e congêneres desamparados laborais informais de rotatividade flutuante do balcão urbano e industrial preceituados: É perfeitamente impositivo o vínculo forçado e obrigatório submetido na tipificação inescusável do núcleo do rol de Segurado Empregado em sua estrita essência primária na Constituição para o oficial estrito de subordinação estatuída fática do Trabalhador Avulso e Sindicalizado originário fixado e estendido formal aos armazéns rurais adjuntos a fazendas atípicas e às portarias marinhas se as empresas passivas patronais que o acionam atípica, simultânea e cominadamente fracionam as jornadas diárias pagas nas rubricas da diária avulsa no fechamento contábil e o expõem diretamente por ordem estrita, restando eximido do viés formal individual autônomo rotineiro de livre ofício avulso da orla portuária local sob rodízio originário contumaz restritivo do conselho classista representativo estrito.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Segundo preleciona peremptoriamente as chancelas da lei e balizas estruturantes material celetistas do art. 12, inciso VI matrizes na seguridade inescusável ordinária RGPS nacional: O trabalhador Avulso (aquele convocado que presta serviço contínuo fracionado rural ou portuário sob sindicalização fixada) se insere rigorosamente sob subordinação restritamente originada a DIVESAS (várias) empresas tomadoras atípicas. Por consequência, a sua própria natureza inescusável de desvinculação não forja o liame celetista empregatício obrigacional patronal (o vínculo civil fixo clássico individual na rubrica do Segurado Empregado tradicional de CLT). Ele subsiste formal e categoricamente na rubrica previdencial expressa única denominada textualmente ''Segurado Trabalhador Avulso'' estrita. Ou seja, por mais ordens e diretivas interinas ou subordinação funcional intermitente efêmera contábil num turno em dada diária, a inexistência do viés vinculativo habitual (pois acionado e gerido por Órgão de Gestão de Mão-de-Obra ou sindicato rodízio rotineiro estrito), O IMPEDE inequivocamente e faticamente terminantemente de figurar a chancela obrigacional previdencial estrita forçosa formal e contábil classificada expressamente na figura individual do genuíno ''Empregado'' (aquela de habitualidade patronal monocrática contínua material exaurível).","difficulty":"dificil","tags":["Segurado Empregado","Trabalhador Avulso","Sindicato","Subordinação Celetista","Vínculo Previdenciário"]}'::jsonb, 'draft', '17mt9', 28),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Avaliando os desdobramentos operacionais legais dos segurados e restrições tributárias na base de dados civil-previdenciária atroz formalizada em súmula e normativas RFB atípicas, em consonância originária estrita de enquadramento na Reforma previdencial passiva e do INSS atrelada às donas de casa nas exceções de contribuições diminutas exclusivas: Por autorização originária inescusável e estatuída no RGPS protetivo pós-reforma base civil, a cônjuge formalizada que perfaz o rol ininterrupto e exclusivo estrito puramente de do lar e mantença dos trabalhos puramente estritos residenciais isentos sem cunho remanescente laboral subalterno remunerado passível preterido avulso rotineiro no mês, e que pretenda acionar formalmente ex e sponte própria recolher guia com a estrita, lícita e basilar finalidade canônica passiva isenta protetiva material exclusiva base de salvaguardar eventual o rol protetivo formal perene do viés e garantia protetiva da dita ''Pensões Civis Mortuárias ou Auxílios Básicos e maternidade restrita'', NÃO ostenta a prerrogativa compulsiva normativa ou discrionária lícita e estatuída de enquadramento como Contribuinte Individual inibindo legalmente sob esse código de ser registrada fática dessa alíquota civil estrita perante a SRF.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme estipula rigorosamente a fundamentação elementar da lei 8.212 em correlação e amparo estrito com os princípios fáticos balizadores da ausência total originária lícita de fomento rentável lícito ''material civil oneroso do mercado rotineiro de bens isentos e atípicos sem proveito na esfera extrafamiliar estrita'' (fator fático elementar irredutível do labor autônomo das C.I.): Aquelas (os) dedicadas apenas às singelas ''lides exclusivas do próprio lar doméstico subalterno civil diário não lucrativo isento'', sem nenhuma atuação empresarial paralela pregressa rotineira (donas de casa ou estudantes não estagiários não remunerados fixos), NÃO incorrem nos atos ou premissas primordiais dos contribuintes autônomos por prestação restritamente econômica onerosa atípica ativa estrita externa perante as normativas limitativas do Estado. Sendo-lhe imperioso o status passivo e estrito subalterno do ''Segurado Facultativo'' na guia (inclusive a subcategoria especialíssima de dona de casa filiada de baixa renda de isenção de guia a alíquota ínfima protetiva - facultativa). Portanto, ela formalmente, inequivocamente, NÃO pode legalmente recolher nem transvestir material contabilmente sua roupagem restrita cívica no código puramente imperativo do Segurado ''Contribuinte Individual'', vez que estaria deturpando as naturezas civilistas e falsificando atos passivos para sonegação presumida restritivamente perante à Previdência formal.","difficulty":"dificil","tags":["Dona de Casa","Lides do Lar","Segurado Facultativo","Contribuinte Individual Vedação","Inscrição Previdenciária"]}'::jsonb, 'draft', 'pffwvi', 29),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"A respeito dos desdobramentos atinentes aos institutos das perdas das graças temporais do segurado em virtude das lacunas inibitivas de preenchimento contributivo de origem transicional temporal de trabalho base ativo: Segundo regramento e a hermenêutica estrita sumulada aplicada reiterada protetiva às contagens, a perda cabal pregressa e irremediável submete o indivíduo segurado de ofício faticamente inibitório preterido ao final estrito do último dia formal corrido, subentendido e estatuído material do 15º (décimo quinto) dia prático exaurível civil contado isolado do mês cível subsequente atrelado e inerente em cômputos ao fim irremediável isolado exato matemático de encerramento cronometrado inescusavelmente total passível na órbita base civil do respectivo e estipulado ''período de prorrogações da graça temporal civil'' restrita fática sub-abrangente.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Trata-se da clássica pegadinha do tempo do vencimento exato no mês das Graças estendidas nos institutos contadores da Seguridade. A jurisprudência protetiva amparada do STJ e TNU sobre prazo residual fixo, aliado ao próprio comando normativo previdenciário base imposto basilar do legislador originário fático do art. 15 da 8.213: a dita e extirpada e irrecuperável temporária ''perda definitiva de materialidade e qualidade pregressa original da proteção do Segurado'' NÃO OCORRERÁ fatalmente rigorosa isolada no encerramento limítrofe inescusável restritiva civil fatal do 15º (décimo quinto dia legal) do lapso mês subsequente ao término dos meses. E SIM OCORRERÁ FATALMENTE SOMENTE NO DIA CIVIL PRÁTICO ORIGINÁRIO SEGUINTE, ou seja, materializado legal na alvora pontual estrita e isolada irretocável preterida fática irredutível do exato (décimo sexto - 16º DIA DO MÊS) estipulado liminar civil prático após à findarem liminar normativo de prazo de proteção rotineira inibida restrita originariam.","difficulty":"medio","tags":["Período de Graça","Prazo de Manutenção","Dia Seguinte ao Vencimento","Qualidade de Segurado","Perda"]}'::jsonb, 'draft', '8t39pr', 30),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a asserção baseada na hermenêutica estrita das imunidades materiais e subcategorias da carência estendida para filiados avulsos de cunho portuário: Ao trabalhador avulso sindicalizado originário, na eventualidade de afastamento suspensivo imperativo base do rol das atividades portuárias regulares e rotineiras preteridas ou rurais das quais é requisitado, em face de instauração ou resposta oficial de punição a processo apuratório disciplinar de sindicato, é categoricamente resguardada e estipulada de forma cível isolada e compulsória a sua plenitude contagem do período pregressa prorrogação na qualidade de segurado (período base da graça) pelo elástico lapso residual em meses irredutíveis preteridos limitados amparado por até cômputo máximo rotineiro de seis exclusos meses inibitórios pós fato deflagrado, assim idênticos ao segurado inibido facultativo.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O Segurado Trabalhador Avulso é estatuído expressamente originário da igualdade e equiparação material rotineira constitucional dos diretos garantidos a todo Segurado Empregado (Art. 7, XXXIV, da CF e premissa na base do Decreto 3048). Destarte, ele, diferente do que a pegadinha induz atrelando aos estritos curtos dos inibidos facultativos, desfruta faticamente perenemente da retenção basilar em regra prorroga (sem pagamento intercalado em recesso punitivo extra limítrofe suspensivo ou demissão avulsa) pelo período rigoroso base cível rotineiro de até **doze (12) meses** inescusáveis após a dita cessação oficial passiva, podendo inclusive usufruir de estendidos rotineiros adicionais a 24 ou 36 caso preencha os exatos demais requisitos plúrimo (desemprego/contribuições decenais) cabais à classe do empregado comum da base geral e da Seguridade cívica, sem se reportar isolado à limitadas fixas exauríveis da submissão curta do puro facultativo (seis meses).","difficulty":"medio","tags":["Trabalhador Avulso","Período de Graça","12 Meses","Equiparação a Empregado"]}'::jsonb, 'draft', '258too', 31),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Acerca das hipóteses protocolares inescusáveis de obrigatoriedade no cômputo formal do RGPS perante a prestação ocasional civil rotineira de autarquias inibitórias: O notário ou tabelião diplomado originário e nomeado isoladamente em serventia de foro cível extrajudicial estrita de delegação titular no município a partir estrita de sucessão após 1994, que já dispunha de base amparada material exclusiva formal preterida vinculada isoladamente da antiga chancela protetora passível cabal ao RPPS Estadual judiciário, não goza de excludente legal formal de proteção, transmutando-se compulsoriamente a obrigação inescusável do rol tributário estrito de Segurado Empregado pela chancela do serviço federal outorgado e fiscalizado diretamente em sua posse vitalícia irredutível do Estado da União.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Conforme alicerce e fixação basilar pacífica cristalizada reiteradamente na via cível do Supremo (com as ECs preteridas e o Art. 236 da Constituição Cidadã), bem como base normativa estrita consolidada protocola fiscalizatória da RFB na regência da Seguridade do artigo 11 da 8213: Os titulares de serventia extrajudicial e cartorários dos rotineiros foros (os tabeliães passivos notariais oriundos nomeados, estipulados de ofício ou ingressos após outorgados nos exauríveis regimes) exercem serviço civil inibitório público POR DELEGAÇÃO basilar de tutela e NÃO possuindo mais formal da dita rubrica ou caráter celetista de vínculo hierárquico, salário fixo outorgado ou habitualidade assalariada no órgão judiciário fático preterido do Tribunal de amparo; são remunerados material e privadamente em seu caixa pelos chamados peculiares rubricas de molumentos puros dos clientes. Portanto, eles NÃO SÃO enquadrados inibitórios passíveis como segurados empregados estatutários estritos da roupagem RGPS, mas impetrados rotineiramente classificados obrigatórios irretratáveis basilar, de pleno rigor autônomo puro na condição canônica exclusiva estanque de Contribuintes Individuais.","difficulty":"medio","tags":["Tabelião","Serventia Extrajudicial","Contribuinte Individual"]}'::jsonb, 'draft', 'n05kzz', 32),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Em face das regras restritivas civilistas dispostas para a apuração da contagem base de carências em auxílios prático-fáticos na classe dos inibidores facultativos donos de lar do regime cívico estipulado das mães de família de classe sub-renda (baixa-renda): É requisito preceituado estrito irredutível do RGPS na constituição formal atípica isenta rotineira para que o indivíduo preteridamente de base de renda familiar insculpida ou que integre esse escopo passível estanque recolha suas contribuições facultativas isoladas basilar exauríveis de míseros ''5% do menor fixo basilar do território vigente'' (Alíquota especial B-R), que a própria fática detentora inibitória ostensiva preterida no recinto atípico do lar isolado comprove originariamente perante a seguridade a auferição rotineira mensal inferior canônica limítrofe inescusável de dois exatos (2) limares basilares salários essenciais da união ou que comprove originário passível civil em Cadastro passivo único mantido ativo dos balcões assistenciais rotineiros da proteção originária estatal (CadÚnico).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se do exato balizamento legal protetivo consolidado da Reforma base protetórica incluído pela basilar Lei nº 12.470/2011 no seio da Previdência Cívica (na exegese do art. 21 da Lei de Custeios 8.212/91): Para ostentar basilar o preceituado viés de outorga irredutível e fazer o material jus passível fático de pagar exímios e abastados apenas parcos limites retidos na casa de inescusáveis rotineiros ''5% (cinco por cento) de sob incidência inibitória estrita calcada no Salário-Mínimo'', essa detentora ou passível chefe preterido dedicante exclusivo de lar e isolado trabalho cívico sem renda e filiado fático Facultativo irredutível precisa inibitoriamente figurar as DUAS excludentes originárias fáticas unânimes atreladas: (i) Estar rotineiramente com o núcleo preterido oficializado em cadastrado regular no preceito assistencial civil amplo basal CadÚnico do impetrante estatuído rotineiro governo e (ii) Inescusavelmente a aludida e isolada somatória estrita material integral bruta da renda basilar financeira dos agregados civis familiares passíveis rotineiro sob aquele mesmo restrito teto não superar o inibitório patamar formal máximo de estritos 2 (dois) vencimentos rotineiros do limítrofe basilar fático irredutível salário-mínimo nacional unívoco impetrado unânime no decurso mensal passível contábil.","difficulty":"dificil","tags":["Dona de Casa Baixa Renda","Alíquota 5%","Segurado Facultativo","CadÚnico"]}'::jsonb, 'draft', 'nyyh31', 33),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Analise a proposição sobre as excludentes formais de acúmulo das matrizes passivas base retributivas fáticas do Regime Celetista na qualidade perene originária e da filiação estanque e unívoca em cargos estaduais da RGPS/RPPS inter-bases: Servidor efetivo municipal estipulado civil regimental irredutível pertencente no Município subalterno ao seu viés estanque estipulado fático preterido ''Estatutário/Caixa Fixa de RPPS'', que concomitantemente estipula atuar num rotineiro e material base de vínculo diário à premissa empregatícia (com assinatura cível) celetista na fundação rotineira fática passível governamental puramente no amparo base Estadual do ente federativo vizinho fronteiriço vizinho cível da prefeitura, sofrerá base a inibitória ou exclusão estrita preterida unívoca compulsoriamente automática unânime de base de qualquer imposição basilar rotineira inescusável do rol do recolhimento originário atinente atípico no formato do RGPS, visto que ambos compõem esferas fáticas governamentais restritivas cíveis impositivas inibitórias da unânime da isenção celetista plúrima e atrelam as vedações do próprio Teto base fático irredutível Constitucional do cômputo civilista e de inibição cruzada de esferas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Trata-se da inteligência irredutível da norma originária do rol protetivo do sistema e do art. 12 basilar fático parágrafos estritos exaurível da regulamentação. O que garante exclusão material de participar basilar rotineiro e de se classificar fático como RGPS originário NÃO é base fático atrelada isolada de inibição à esfera estritamente ''governamental'' per se do ente isolado passível a do empregador, NEM a limitação unívoca salarial celetista puramente teta de base irredutível (Teto). O Servidor Efetivo de Município (RPPS local) que labora como empregado fático da base celetista na referida esfera na fundação governamental atrelada originária vizinha assume, no escopo basilar restrito desse rol secundário inter-vínculo exímio contratual em regime unânime rotineiro celetista, unicamente a qualidade exaustão atípica estrita rotineira originária forçada classificada obrigatoriamente perene e estanque de SEGURADO EMPREGADO na competência e arranjo fático RGPS (se a fundação fático basilar vizinha não aloca CLT no seu estrito estatuto para si num RPPS paralelo formatado do celetista). Há filiação basilar concomitante obrigatória lícita (incidindo descontos isolados autônomos por prestação preterida nos 2 regimes de matrizes fáticas atrelados sem inibição cruzada plúrima ou exclusão irredutível de isenção perante base tributária previdencial).","difficulty":"dificil","tags":["Vínculos Concomitantes","RGPS e RPPS","Servidor Público Celetista"]}'::jsonb, 'draft', '9ouh3k', 34),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue estritamente as hipóteses garantistas exauríveis formativas atreladas a manutenção cabal da graça no bojo inibitório puramente retentivo de proteção cívica basilar da Previdência Social no desempregado: Conforme as balizas rígidas estatuídas preteridas basilar de prazo civil pela autarquia e jurisprudências da matriz da lei geral: Se o cidadão segurado desempregado comprovar isolada e formal originária exímia inscrição basilar na base passiva no cadastro próprio unânime fático passível rotineiro fixo no formato retributivo estrito de pleito ao Seguro-Desemprego, materializado nos sistemas exímios protéticos da base labor do Ministério respectivo civil de amparo do Trabalhador restrito, tal ato inescusável isolado atípico confere amparo irredutível puramente originário estanque com o condão de deferir irredutível automática estatuídas basilar de prorrogação contábil material extra protetiva da manutenção garantida original inibitória pelo exato prazo estrito dobrado civil unânime inibitório complementar perene rotineiro fixado estritamente em **+ 24 (vinte e quatro) meses**, desconsiderando outras bases temporais.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Embora receosos ou confundidos com limites unânimes exatos rotineiros e de soma fático preterida, a jurisprudência base (como TNU) e a norma 8.213 são fáticas categóricas e cirurgicamente excludentes limitadas fáticas restritas em apontar: O puro mero e estrito isolado registro preterido contábil e civil de ausência material estanque inibitória e involuntária do desemprego auferindo rotineiro fático atrelado em cadastro irredutível base ao Ministério respectivo impõe exata e **apenas MAIS UMA extensão estrita basilar irredutível exaurível isolada unívoca de puramente LIMITADOS rotineiros E EXATOS + 12 (DOZE) meses** ao tempo rotineiro originário da estrita graça passível contábil fático. Ou seja, por si só, essa inscrição NÃO dobra irredutivelmente para um adicional direto rotineiro puro basal de + 24 isolado base cívica inescusavelmente contábil. Apenas se ele **JÁ tiver** somados os inibitórios exímios rotineiros base dos outros 12 da extensão garantista por tempo fático basal (120 meses preteridos estritos), é que ele somaria o combo 12 (base normal) + 12 (se 10 anos) + 12 (do registro) exaurindo aos famosos limites máximos de 36. Mas o ato do ministério exato rotineiro, ''per se'', confere exatos preteridos isolados rotineiro 12.","difficulty":"medio","tags":["Período de Graça","Desemprego","Ministério do Trabalho","Extensão Legal","Prazo"]}'::jsonb, 'draft', 'p3fyt3', 35),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a asserção no tocante à subordinação dos familiares dependentes das chancelas operacionais civis base do amparo mortuário restrito: O filho civil tutelado, o enteado validado estrito ou o menor sob guarda formal judicial permanente de avós aposentados detentores basilar do RGPS, assemelham-se originária e categoricamente faticamente pela via principiológica social e estatuída exímia do crivo normativo cível à alocação imperativa plena do ''filho nato equiparado'' na classe 1 (primordial basilar de dependentes preferenciais) no rol do Instituto base de Seguridade (INSS) do preterido provedor inescusável guardião falecido, desde que haja documentada puramente e isolada inibitória a respectiva inscrição em vida ou termo judicial cível outorgatório formal perene sem necessidade de prova autônoma prévia basal.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Com as alterações perpetradas historicamente pela Lei nº 9.528/97 na lei 8.213 originária, e corroborada com a recente Emenda EC 103 sobre a restrição de classe dependentes: o **menor sob ESTrita GUARDA** judicial rotineira ou estatuída foi **EXCLUÍDO taxativa e irredutivelmente** basal da referida lista fática e restrita canônica oficial protetiva legal do rol normativo de ''dependentes nativos ou equiparados''. Apesar de o Estatuto fático do ECA e alguns raríssimos entendimentos do STJ isolado terem amparado no passado teses de viés superior humanitário na guarda de avós, A LEI 8.213 estrita atual impõe textualmente que a estatuída base de ''equiparação basal a filho fático passível de dependência presumida exaurível na Classe 1'' restringe-se EXCLUSIVAMENTE ao estipulado INIBITÓRIO fático basilar ENTEADO ou ao MENOR TUTELADO. O Menor Tutelado e Enteado dependem, por normativas do INSS inescusável de exigência material: **comprovação cabal rotineira unânime fático da efetiva e irredutível base estrita pura de DEPENDÊNCIA ECONÔMICA EXCLUSIVA fática**, que no seu rol não é e não goza estipulada da inescusável presunção limítrofe material plena (que apenas favorece o originário formal ''filho civil nato ou formalmente dotado perene de adoção legal plena irredutível'' e cônjuge).","difficulty":"dificil","tags":["Dependentes Classe 1","Menor sob Guarda","Enteado","Tutelado","Dependência Econômica"]}'::jsonb, 'draft', 'g1mrot', 36),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue em sede da manutenção pregressa dos status formativos da graça temporal nas lacunas desempregadas estritas da lei, sob a inteligência exegética jurisprudencial contínua da Corte do regime e fática: Um cidadão rotineiro demitido estrito celetista (ativo com preteridas exclusivas bases 3 anos e recolhidos unânimes atreladas de guia) que, por vicissitudes irredutíveis temporárias ou reajuste exaurível rotineiro da labuta extra ou familiar basal de bico exímio inibitório durante sua suspensão patronal, emite em dita restrição passível de autônomo basilar puramente avulsa ''Notas Fiscais rotineiras esparsas isoladas sem vinculo fixo canônico de Contribuinte Inibitório Individual fático na sua inativação empregatícia mensal paralela'', detém faticamente e sumariamente extirpado preterido da sua essência basilar legal qualquer limítrofe formativos base rotineiro dos períodos irredutíveis remanescentes puros da carência fática pregressa passível estendida daquelas estritas das bases originárias contínuas estipuladas civis desempregadas oriundas do regime primário na rubrica exímia.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A consolidação jurisprudencial preterida estrita protetora da TNU (Turma Nacional puramente civil da uniformização) preceituou basilar firmemente inescusável no crivo da extensão formativa fática passível: O simples recolhimento ou o exercício preterido isolado e efêmero fático irredutível estancado transiente basal unívoco na classe estrita ''inferior autônoma e precária passível intermitente unânime estanque'' (bicos, pequenas prestação de MEI eventual inibitório transiente rotineiro de CI no hiato de demissão) realizados sem durabilidade basal continuada irretratável pelo segurado desempregado originário do lapso, **NÃO exime, suprime rotineira ou fatalmente destitui inescusavelmente ou zera a base civil e o direito basal passível à contagem de lapso estendido protetório fático unânime do amparo (24 rotineiros ou 36 restritos preteridos na rubrica pura inibitória isolada)** que ele conquistou liminarmente ou que mantinha unicamente amparado pela extensa originária base contábil temporal inibitória anterior da figura ''celetista rotineiro isolado empregado passível'' extinta sem justa exímia atipicidade. As qualidades intercaladas de esforço inibitório sem estabilidade plúrima inibitória na lacuna de ausência NÃO ferem a Graça originária estendida garantista preterida temporal cível desempregada.","difficulty":"medio","tags":["Período de Graça","Bico","Súmulas TNU","Desempregado","Trabalho Precário"]}'::jsonb, 'draft', 'wdz3g', 37),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Sob a égide do direito protetivo, a filiação compulsória rotineira canônica dos segurados individuais exauríveis e prestadores estritos preteridos civis não agenciados amparados pela SRF de ofícios: Para o trabalhador civil autônomo originário de lide eventual puramente intermitente que aufira num dado exato lapso de competência civil remuneração bruta estrita rotineira precária isolada mensal atada unicamente num valor abaixo inibitório taxativo cível formatado do Salário-Mínimo civil nacional, a sua referida base contábil exímia da prestação inescusável rotineira será exaurida sumariamente basilar atrelada desconsiderada ex officio pelo regime para todos os fins base pátrios protetivos (carências, lapso etc). Destarte, ele, sem prejuízos, tem inibida a outorga basal ou excludente da mera formal compensação contábil para suplementar o recolhimento das estritas referidas bases pecuniários faltantes atípicos isoladas sob sua livre discrição e cominação fático legal no escopo da base do limite piso.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. A Reforma da Previdência EC 103 estipulou basilar rigidamente e consolidou a restrição unívoca fática basilar: De fato irredutível, bases exclusivas civis recebidas em competência exata ou rubrica mensal rotineira puramente fática estanque que fiquem numericamente abaixo preterido cabal do Piso canônico salarial mínimo estipulado nacional e rotineiro inibitório **NÃO serão puramente consideradas ou validadas computadas estritas isoladas fáticas originária como ''lapso inescusável civil puramente temporal validado material contábil fixo de carência fática amparada''** inibitória em favor exclusivo protetivo do pleituário basilar (art. 195, § 14 da Constituição exaurível pátria unívoca). ENTRETANTO a assertiva erra material inescusável basal fatalmente ao decretar falsamente inibitório o total ''prejuízo e inibição das faculdades suplementares civis'', vez que O MESMO DISPOSITIVO magno basal da emenda GARANTE EXPRESSAMENTE três vias de salvação basilar e adequação retributiva exaurível ao cidadão passível inibitório no limite baixo: ele detém originariamente o estrito plúrimo e total direito de **COMPLEMENTAR civil fático a atípica do próprio bolso contábil extra** inibitório a referida base financeira a estrita até atingir integralmente unívoca esse limítrofe inibitório de piso rotineiro teto base mensal; ou estritamente fático o agrupamento civil estanque de bases de valores inferiores oriundos isolados preteridos formativos atípico inter-competências; ou puramente utilizar sobras e aportes de excessos excedentes bases plúrimo e inescusáveis financeiros oriundas cíveis preteridos pátrias fáticas de outro mês rotineiro cabal exaurível protetivo fático ao seu prol social unânime (ajustes compensatórios originários).","difficulty":"medio","tags":["Salário-Mínimo","Carência","Complementação de Contribuição","Competência","EC 103"]}'::jsonb, 'draft', 'h3i1mg', 38),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue em face dos delineamentos protetivos fáticos preteridos exauríveis consubstanciados originários cíveis da obrigação do Microempreendedor basilar: O microempreendedor passível estrito restritivo formal Individual (MEI rotineiro nacionalizado amparado pelo DAS-MEI civil de cota base redutora fática limitadora de alíquota de 5%), ao recolher exaurível de praxe a estrita chancela diminuta da base legal protetiva rotineira, exarará a renúncia taxativa inibitória cível basilar e cabal de valer-se base e utilizar de sua própria contagem irredutível exímia ou de amparo de proteção do referido base temporal laborado civil estritamente unívoca formativa em lapso restrito e tempo cronológico exaurível estatuído contábil para base puramente inibitória restrita e formal de chancela da concessão na Aposentadoria originária base rotineira da idade por viés de tempo exclusivo rotineiro estrito preterido material isolado fático cabal de inescusável de base contribuição, mantendo-se protetivo isolado basilar preterido do restritivo benefício fixo isolado de invalidez e ou o próprio unívoco isolado estrito preceito por idade.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se da pedra angular estruturante preterida fundante restritiva exímia protetiva das regras basilares rotineiros fixo e limitadas da classe dos optantes do regime de Segurado C.I. exaurível e MEI inibitórios. Segundo dispõe normativo taxativamente cível isolado rotineiro do § 2º do basilar rotineiro impositivo do art. 21 preterido unânime fático cível estanque cabal do ordenamento primacial da 8.212/91: Aqueles microempreendedores estritos formais civis restritivos que optarem, se filiarem rotineiramente isolados a título restrito do recolhimento exato basal fático do plano de alíquota rebaixada inibitória base diferenciada civil isolada da união (quer seja a cota base restritiva estrita preterida puramente inibitória isolada unânime de 11% ou formal MEI exclusiva base fática de 5% liminar amparada sobre o salário rotineiro), eles retém o gozo cível rotineiro da aposentaria restrita inibitória impetrada por limitação das estritas regras cabais da **Idade exclusiva fática ou na inibitória atrelada civil invalidez acidentária**. Estão inibitórios exauríveis EXCLUÍDOS normativamente formal de utilizar esse lapso recolhido puramente mitigado isolado basal atrelado liminar fático nas antigas e taxativas regras cíveis matrizes da impetrante e rotineira atípica basilar Ação Exclusiva da estipulada Aposentadoria Unívoca cabal irredutível pelo montante de estrito Tempo basilar canônico formal Civil material contábil inibitório puramente integral Ininterrupto Rotineiro Contributivo ou estanque (salvo raras compensações inibidoras futuras complementando faticamente até os 20% plenos na Receita unívoca exímia basilar isolado da união).","difficulty":"medio","tags":["Microempreendedor Individual","MEI","Alíquota 5%","Tempo de Contribuição","Aposentadoria por Idade"]}'::jsonb, 'draft', 'wxva04', 39),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"A respeito dos desdobramentos atinentes fáticos limitadores práticos processuais da seguridade perante às uniões matrizes base restritivas fáticas protetivas homoafetivas no direito basilar irredutível: É consolidada e imperiosa a outorga preterida e exaurível concessão canônica passível base do inibitório material preterido cabal basilar civil estrito unívoco benefício fixo isolado exímio estipulado de Pensão por óbito exaurível civil do RGPS material, a título base retributivo e da inibição estrita originária no crivo dos dependentes civis passíveis basilares primários cabais da rubrica classe I formados nos arranjos inibitórios fáticos rotineiro originário da sociedade rotineira exímia familiar dos cônjuges e conviventes homoafetivos inibitórios de estrito formato civil, ainda que o Supremo Tribunal Federal amparado restrito e irredutível exímio isolado cível formal exaurível base não tenha consolidado jurisprudência na base sumulada impetrante puramente restrita inibitória das exceções protetórias rotineiras atreladas da união originária material fática exímia atípica matrimonial formal rotativa base do pacto na autarquia matriz.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Há duplo comando afirmativo consolidado preterido da validade estrita material civil. Apesar da longa inibitória exímia atipicidade restrita normativa arcaica fática passada em leis ou da falta cabal exaurível preterida legislativa pretérita do judiciário nas bases inescusáveis do RGPS das leis isoladas estritas do antigo crivo restritivo originário previdencial atrelado em textos puros matriz, o STF (sob o balizamento histórico inibitório exímio rotineiro fático da famosa ADI basal cível impetrada 4277 e da basal base ADPF atrelada liminar civil originária 132) outorgou e declarou unânime e definitivamente rotineiro imperiosa e originária fática cabal inibitória da constitucionalidade preterida estrita protetora da união civil homoafetiva estanque fática passível. Por conseguinte irredutível passível cível legal cabal originária atrelada, a própria Seguridade rotineira inescusável normativa basilar (INSS matriz estrito em portarias conjuntas estritas formativas cíveis amparadas exímias originárias rotineiras), bem como os Tribunais formativos preteridos basilares, enquadraram preterido sumariamente isolado e irretratavelmente fático basilar civil restritivo sem preterições de gênero todos arranjos, cônjuges formativos atrelados passíveis homoafetivos ou ditos parceiros conviventes civis contábeis preteridos como **dependentes preferenciais inibitórios naturais rotineiros inescusáveis basilar na rubrica taxativa superior fático passível de Primeira Classe (I) nas regras do sistema (sem estrita fática exigência basilar originária comprobatória judicial inibitória basal probatória irredutível preterida de puramente bases econômicas exaurível isolada atípicas ou atreladas protetórias civis exímias, pois a dependência base preterida do regime cível deles exara formal unívoca passiva puramente base PRESUMIDA exaurível irredutível inibitória por base de lei conjugal civilista)**.","difficulty":"facil","tags":["União Homoafetiva","Dependentes Classe 1","Pensão por Morte","STF","Dependência Presumida"]}'::jsonb, 'draft', 'amj0d1', 40),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a asserção no tocante à perda da qualidade protetiva nos crivos cíveis exauríveis rotineiros de afastamento: Conforme basilar base normativa da TNU atrelada e balizas estritas do rol previdenciário rotineiro sobre preceitos passíveis inibitórios da vacância (período de fática graça originária da base), ainda que a segurada mãe originária autônoma ou empregada perca a sua isolada condição rotineira de segurada preterida na autarquia (por exaurimento canônico dos 12, 24 ou 36 meses estritos), ela possuirá base originária inibitória a manutenção integral basilar da tutela para a exata outorga rotineira pura civil do ''Salário-Maternidade'', conquanto e exclusivamente comprove ter estipulado rotineiro o nascimento base do referido fático infante exímio inescusável antes, exata e unicamente nos limiares fáticos passíveis dos inescusáveis 15 dias práticos puramente amparados irredutíveis rotineiros civilistas após da dita preterida data estanque do parto inibitório puramente isolado.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. O axioma principal do Direito Previdenciário consolidado impõe que as Maternidades preteridas da carência inescusável devem exarar a proteção fática pura e exclusa durante e atrelado ao próprio ''Período Base da Manutenção Restrita''. No entanto, para se auferir inescusavelmente ou ter direito rotineiro basilar irredutível adquirido fático isolado à rubrica do benefício exaurível protetor estrito ''Salário-Maternidade'', o requisito canônico basilar imposto pela Corte do regime e STJ é cristalino rotineiro inescusável: o evento base fático gerador canônico puramente (nascimento limiar do dependente ou adoção restrita formativa amparada) precisa e DEVE cabal e irredutivelmente ocorrer OBRIGATORIAMENTE **ENQUANTO preterido ESTIVER a referida mãe no gozo e acobertada rotineira legal da ESTIPULADA ''QUALIDADE fática liminar DE SEGURADA''**. Se o fato do nascimento basilar puramente inibidor isolado exaurível acorreu exato 1 (um) puro limiar mês inibitório APÓS ela extirpar material e preterido cabal perder isolada exímio sua Graça estrita temporal da proteção formal base civil do regime geral inescusável da base... Ela basilar NÃO deterá o amparo rotineiro base do salário em questão natal base (pois não perfaz inibitório retroativamente fático se no dia cível estanque ela já não rotineiramente integrava passível do sistema inescusável formal inibitório e da folha da Previdência Social no nascimento, cessa a cobertura).","difficulty":"medio","tags":["Salário-Maternidade","Período de Graça","Qualidade de Segurada","Evento Gerador","Nascimento"]}'::jsonb, 'draft', 'hm6jz9', 41),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue o preceito sobre as minúcias obrigacionais amparadas protetórias civis da chancela e sub-requisitos de reingresso carência rotineira atrelados da base: Caso um segurado rotineiro empregado puro ou o estrito de viés inibitório Contribuinte Individual sofra estatuída exclusão da qualidade de segurado (fique 5 anos ausente irredutível) e depois volte preterido material canônico a filiar-se restritivo ou trabalhar forçoso fático da união do sistema com novos inescusáveis inibitórios base rotineiros aportes de contribuições cabais plenas, para que ele inibitório exaurível tenha restaurada protetória civil e cômputo basal fático irredutível preterido pregressa isolada somada do tempo fático ou reativado atípico atrelado isolado unânime de todos os anos laborados bases anteriores e inibitórios velhos da perda para garantir eventual fático do puro isolado inescusável benefício do rotineiro exaurível de concessão de um benefício como Auxílio-Doença civil basal ou inescusável do Aposentadoria formativa por Estipulada Invalidez, as novas exclusivas emendas basilares impõe o recolhimento inédito compulsório rotineiro inescusável do mínimo taxativo inibidor puro formativo amparado e rotineiro exato da metade inteira irredutível das carências originais das concessões basilar passíveis (exatos e estritos exauríveis rotineiros puros de inibidores limites canônicos e atrelados).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Essa é a base fático canônica rotineira e estrita de preceito normativo puro (''Restabelecimento e Reforço irredutível Civil do crivo impetrante de Carência fática inescusável formativa após Limiar estrito rotineiro basilar da perda da liminar''). Com as recentes atípicas emendas legais fático-originárias isoladas unânimes (incluindo as normativas que mudam e reformam da 13.846 inibitória e Lei basilar formatória cabal do regime da 8.213 rotineiro civil): O cidadão inibitório exaurível estanque rotineiro basal que Perca fático a preterida Manutenção de Qualidade basal e queira originária inescusável unir basilar contábil material aos amparados passíveis restritos do INSS os cômputos fático-originárias estritos preteridos base ou carências exclusivas prévias isoladas, ele, após fático filiar rotineiro no INSS e retomar as bases inibitórias do labor puramente cível, DEVERÁ obrigatoriamente cabal irredutível inescusavelmente recolher **a preterida basilar metade inteira unívoca unânime do tempo exímio legal de carência originário civil rotineiro taxativo fático exigido liminar** pela própria fático chancela amparadora do aludido inibitório preceito de benefício rotineiro passível em lide (ex: como o Auxílio-doença exige exímias puramente 12 rotineiras unívocas; ele precisará base e unicamente na volta fático inibitória de recolher originária de base mais inibitório puras 6 novas cabais contribuições inescusáveis civis isoladas plúrimas). SOMENTE APÓS pagar essa taxativa ''meia unívoca inescusável basal isolada carência do novo ingresso fático atrelada'', o INSS descongela e une isolado fático unânimemente toda irredutível a estanque originária fática conta base de meses do passado canônico fático rotineiro unívoco dele civilmente na proteção unânime basilar formativa isolada exaurível atípica inescusável.","difficulty":"medio","tags":["Perda da Qualidade de Segurado","Carência","Reingresso","Auxílio-Doença","Metade da Carência"]}'::jsonb, 'draft', '3snqir', 42),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"De acordo com o complexo fático irredutível do crivo de filiação basal formativa e originária rotineira, as estritas categorizações preteridas atípicas exclusivas dos Ministros unânimes Religiosos civis: O Pastor fático e estrito titular inibitório rotineiro basal de igreja ou templo restrito material originário das confissões puras basilar religiosas unívocas na União (ou Padre fático inibitório congregado limítrofe atípico isolado basilar rotineiro), em preterido atípico fato e isolada alocação civil rotineira de labor unívoco e recebimento inescusável basilar de amparo pecuniário puramente sustentório (denominado Congrega social ou prebenda rotineira material) concedido isolado exaurível inescusavelmente pelas instâncias atípicas irredutíveis da Ordem religiosa basal da Instituição formativa originário passível civil exata, independentemente do teto e subordinação canônica inibitória rotineira interna religiosa fática impetrada ao bispo basilar diocesano na sua fé pura cível, **reveste-se ex officio e exclusivamente inibitório na roupagem fática rotineira isolada estrita basilar do INSS perante o rol autônomo e impetrante unânime restritivo normativo irredutível amparado do RGPS base na qualidade isolada da referida classe de base Contribuinte Individual estanque formativo.**","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se da hermenêutica estrita fático originária do enquadramento civil canônico e imposto do trabalhador religioso restritivo (e ratificada pela base no Decreto formativo do INSS 3.048 plúrimo e inescusável da restrição basilar civil rotineira estanque do art 9). O chamado Ministro fático originário em preterida isolada de cunho irredutível de puras e rotineiras inescusáveis de confissão religiosa estanque civil amparada (seja Padre, Pastores, Rabinos fáticos rotineiro ou congêneres estipulados de hierarquias afins de subordinações fáticas doutrinais eclesiásticas base das congregações cíveis limítrofes civis preteridas) são enquadrados OBRIGATORIAMENTE **e inescusável fático isolado de inibitório estanque de BASE COMO CONTRIBUINTES fáticos rotineiro INDIVIDUAIS base irredutível rotineira** perante fático formato da base civil da Seguridade do fisco inescusável e RGPS. Importa notar canônico inescusável (e por isso a dita ''pegadinha celetista basal cível liminar'' inibitória de muitas rotineiras provas fático na subordinação) que os Tribunais Superiores isolados restritivos de tutela rotineira Trabalhista atrelados basilar e o rol civil Previdenciário pacíficos e fáticos declararam que as puramente chamadas ''subordinações canônica inibitória puramente estritas exaurível do líder na doutrinar da fé ao bispado'' NÃO configura de fática forma inescusável subordinação cível de vínculo rotineiro formal puramente atrelada liminar jurídica civil celetista impetrante basal de ''Segurado Empregado puro ou vínculo empregatício rotineiro base da CLT''. Não gera base o status Empregado, logo é obrigatoriamente base na filiação inibitória amparada estrita autônoma do C.I.","difficulty":"facil","tags":["Ministro de Confissão Religiosa","Contribuinte Individual","Subordinação Canônica","Não Empregado"]}'::jsonb, 'draft', 'mo3w0p', 43),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"No contexto inibitório fático rotineiro prático originário estanque base amparado do Segurado Facultativo e suas rotineiras alocações: O Servidor civil canônico ou municipal inibitório estatal efetivo basilar inescusável rotineiro que for unívoco originário estipulado preterido (fiel ocupante rotineiro material atípico liminar no seu estado basilar originário da respectiva tutela impetrante do fundo do RPPS inibitório basilar) e caso rotineira formalmente exaurível seja amparadamente irredutível originário designado rotineiro irredutível a acompanhar liminarmente cônjuge preterido ou puramente isolado estrito ser cedido formal sem ônus ao inibitório exercício temporário basilar liminar exímio a um Organismo transnacional inibitório rotineiro basilar do ente diplomático Internacional fático ou das Nações Unidas na sua jurisdição exterior atrelada puramente no estrangeiro preterido por base inibitória isolado de 2 fáticos anos civis exaurível... e que por tal basilar inibitório inescusável fique faticamente puramente desobrigado base atípico rotineiro ou seja civil e isolado preterido legal da filiação irredutível pura contribuição rotineira e inescusável contínua e amparada ao seu anterior base rotineira RPPS e a Seguridade daquela matriz... ele não retém rotineira exímia a vedação constitucional originária cabal e PODE, excepcional fático inibitório isolado legalmente estanque basilar amparado, manter no crivo rotineiro originário da pátria a rotina filiação protetiva facultativa isolada inescusável unânime cível perante no fático regime do formato inibitório do Estado pátrio RGPS.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Esse é o ponto exato da exceção legal à famigerada irredutível ''VEDAÇÃO constitucional'' do Servidor do Estado. Regra Fática primaz Exímia: Servidor ocupante puramente basilar ativo do Regime fático estrito Próprio de referências (RPPS basilar do ente inibitório e preterido cabal rolista) MANTÉM cabal e está expressa inibitória e rotineira probitivamente unívoco EXCLUÍDO rotineira puramente fática isolada inescusável originariamente de atípico da estrita basilar inscrição ou rotineiro pagamento da rubrica paralela do inescusável estanque cível do ''Segurado Facultativo civil''. EXCEÇÃO irredutível base amparada (e constante inibitória unívoca unânime basal na norma formativa do Regulamento inibitório RGPS civil fático isolado Dec 3048, art. 11, do Decreto e em basilar portarias previdenciais do ente fático civil unívocas da RFB base amparada rotineira plúrima da pátria restrita atrelada): SÓ PODERÁ exaurível e inescusavelmente amparada o servidor base atípico do Estado inscrever-se base no facultativo do RGPS se estrito isolado da união estiver licenciado unívoco fático ou faticamente cedido puramente basilar irredutível sem o percebimento na base fática puramente unívoca rotineiro do da respectiva remuneração inibitória e civil pura ou rotineira base ou puramente se afastado civil inibitório e formalmente unívoco **sem remuneração base e desde fática irredutivelmente e unânime isoladamente em base do estrito rotineiro que o respectivo basilar inibidor Regime Próprio dele formativo não limite rotineira inescusavelmente ou ampare a sua manutenção passiva paralela puramente no referido regime**. Se o RPPS proíbe ou ele fica defeso civil, a brecha puramente rotineira inibitória e atípica preterida formal é ativada fático na tutela civil do facultativo da União isolada, permitindo cível amparo.","difficulty":"dificil","tags":["Segurado Facultativo","RPPS","Vedação de Filiação","Exceção ao Servidor","Afastamento Sem Remuneração"]}'::jsonb, 'draft', 'ue7ex0', 44),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue em sede do labor transicional inibitório exímio rotineiro fático da premissa dos Segurados Especiais de lides extrativistas inibitórias: O artesão originário preterido ou puramente estrito formativo garimpeiro inibitório originário que atue puramente basilar exaurível de referida cível rotineira e em mero sistema isolado e puro originário amparado basal do ''regime estrito familiar liminar'' inescusável originariamente civil inibitório no feitio manual estanque (Sem rotineiras remunerações preteridas inibitórias autônomas paralelas puramente de base ou o impetrante assalariamento diário isolado formativo fático alheio irredutível base e civil unívoco da contratação basal rotineira das restritas ferramentas de subempregados na equipe base rotineiro), é abarcado, para exímios liminares puramente fáticos e bases inibitórias da subsistência civil, na preterida chancelaria amparada de inescusável do estrito rol previdenciário base inibitório isolado originário e atípica de inclusão sumária do ''Segurado fático Especial rotineiro do sistema matriz rural''.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Trata-se da inteligência pura jurisprudencial preterida liminar fática inibitória consolidada exímia basal da corte pátria basilar restritiva do INSS civil estanque e dos estritos formais civis restritivas matrizes e da Lei inescusável base 8.213 plúrima e fática cabal preterida art 11: A lei arrola EXAUSTIVAMENTE isolada unívoca rotineira estanque do restrito fático e inibitório cível quem basilar puramente INSERE e tem legal fático do referido o condão originário fático atípico restritivo exaurível de ser amparado puramente de modo o restrito originário formativo de Segurado inibitório Especial isolado: O base Agricultor familiar, cível Seringueiro rotineiro extrativista fático basal sustentável e isolado puramente inibidor rotineiro Pescador base formativo artesanal civil e seus dependentes/cônjuges base isolados. O chamado base fática e puro ''Garimpeiro rotineiro basal e artesanal exaurível fático impetrante isolado'' e inibitório puramente ''Artesão urbano ou prático rotineiro unívoco manual da venda unânime da subsistência familiar'' (fazer redes manual ou pedra cível extração inescusável originária das bases do riacho), mesmo do formato inibitório basilar familiar isolado do labor fático restrito, **NÃO são mais enquadrados** inibitórios rotineiros na preterida exceção irredutível passível basal de base fática da figura cívica especial exaurível (O GARIMPEIRO FOI TIDO E DECLARADO BASILAR INIBITÓRIO EXPRESSAMENTE PELA Lei nº 8.398/92 DA UNIÃO formativo preterido civil inibidor de base estrita COMO PURAMENTE NO rol exímio e originário estatuído do CONTRIBUINTE basal INDIVIDUAL exaurível e rotineiro inescusável).","difficulty":"medio","tags":["Segurado Especial","Garimpeiro Artesanal","Contribuinte Individual"]}'::jsonb, 'draft', 'pyu6fq', 45),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Considerando os preceitos atinentes e o regime jurídico-protetório do auxílio-reclusão, com as alterações perpetradas em 2019 (EC 103 e MP 871 convertida na Lei 13.846/19), julgue: Atualmente, os dependentes de segurado de baixa renda que for recolhido à prisão cautelar ou preventiva (sem trânsito em julgado da respectiva condenação), para fruírem originariamente do amparo inibitório e da garantia cível do auxílio-reclusão, necessitam da emissão oficial da certidão carcerária e do recolhimento inescusável do indivíduo puramente basilar sob o regime rotineiro fechado ou do inibitório amparado semiaberto nas instalações penitenciárias, sob pena de perda total da concessão perante a autarquia previdenciária.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Com as alterações perpetradas rigorosamente pela base inibitória da referida Lei n. 13.846/2019 (conversão da MP 871), no tocante e estrita ao benefício base do Auxílio-Reclusão cível: (1) O respectivo amparado ou benefício **não é mais faticamente devido** nos rigorosos casos e prisões atípicas puramente **cautelares provisórias ou prisões puramente em rol unívoco temporárias ou preventivas**; mas tão EXCLUSIVAMENTE nas estipuladas amparadas irrefutáveis sentenças puramente já definitivas ou fáticas (cumprimento estrito liminar e fático puro unânime basilar de sanção das puras PENAS). (2) Não é mais exarado ou tolerado rotineiro o gozo irredutível do auxílio para reclusos em exímios regimes ditos semiabertos! O novo estrito formato fático originário inescusável inibitório RESTRINGE legal e objetivamente o benefício APENAS e inibitório taxativo EXCLUSIVO para as condenações cumpridas rotineiras rigorosas sob a exclusiva matriz de resguardo do **REGIME puramente basal canônico FECHADO**.","difficulty":"medio","tags":["Auxílio-Reclusão","Regime Fechado","Prisão Preventiva","Lei 13.846/2019"]}'::jsonb, 'draft', 'ktf2jh', 46),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue em face dos balizamentos basilares das exceções e recolhimentos rotineiros fáticos do regime e do Segurado Especial perante o RGPS: O indígena natural estipulado aldeado que puramente seja civilmente referida em base isolado inibitório do amparo registrado cabal preterido amparado nominal base na respectiva autarquia federal liminar tutelar fático dos silvícolas, e que exímia e atipicamente labore nas puramente tradicionais exauríveis fáticas matrizes extrativistas cíveis estritas do seio liminar puramente nas delimitações amparadas na terra indígena da União de subsistência cível estanque coletiva de seu povo originário (sem uso de empregados permanentes estranhos, ou mecanização), é, por base puramente normativo inibitório irredutível da matriz RGPS, incluído cabal inescusável liminar taxativo com as prerrogativas de filiação protetiva compulsória isolada na rigorosa fática inibitória roupagem cível estanque unívoca da base Segurado Especial do âmbito social, e destarte rotineiro, não impõe formal contabilidade de recibo obrigatória exaurível para fazer jus às rubricas fáticas básicas do subsistema civil restritivo (salário mínimo e pensão fática mínima).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme estabelece irredutível basilar e inescusável do parágrafo único puramente em rol civil do art. 2º exímio atrelado e também nas preteridas cíveis incisos rotineiros amparados da regulamentação no 11, VII da base civil pura matriz inibitória e basilar lei 8.213: **O Indígena fático** originário que rotineiramente atua puramente no dito regime exaurível rotineiro restrito familiar e que cabalmente for cível atípico isoladamente fático perante o crivo formativo no amparada liminar ou certificado civilmente basal pela dita Fundação de formato Nacional puramente canônica do base Índio (a rotineira FUNAI), ele será para amplos e rotineiros exímios civis efeitos protetivos da referida estrita isolada previdência fática isolada amparada **categorizado irredutível taxativo rotineiro como estrito SEGURADO puramente fático unívoco ESPECIAL**. Desfrutando dos mesmos exímios basilares fáticos e resguardos protocolares da dispensa do base carnê puro e de recolher inibitório as referidas e estritamente taxas na base cível sob os rendentes fáticos primordiais (subsistência irredutível) na outorga rotineira protetiva do estatuído preterido basal piso exaurível do Salário-Mínimo rotineiro na pátria civil da amparada aposentadoria.","difficulty":"facil","tags":["Indígena","Segurado Especial","FUNAI","Regime de Economia Familiar","Salário-Mínimo"]}'::jsonb, 'draft', 'hj11pp', 47),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Analisando as estipulações normativas sobre enquadramento estrito de síndicos e administradores de condomínio no RGPS: O mero condômino titular eleito legitimamente originário e impetrante e designado fático inibitório rotineiramente passível para preterida exercer cabal limítrofe inibitório civil isolado do múnus originário estanque no encargo passível de ''Síndico rotineiro originário da assembleia civil rotineira estanque do condomínio'' matriz, mesmo que preterido na convenção liminar originária e civil seja expressa e objetivamente exonerado de qualquer isenção na sua taxa rotineira contributiva puramente ou referida estrita amparada dispensa fática de rubrica inibitória ou puramente remunerativa (isto é cabal, atua puramente gratuito e não é puramente desonerado da base contábil nas taxas fáticas civis edilícias rotineiras mensais de seu encargo moratório puramente rotineiro do apartamento inibitório), reveste-se ex officio e compulsoriamente formativo na preterida rotineira basilar na filiação obrigatória atípica passível do sistema puramente RGPS, devendo amparado rotineiro o condômino exarar o recolhimento base por esta pura fática função na qualidade rigorosa atrelada fático de Trabalhador Autônomo ou referida pura base civil do C. Individual.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Segundo diretriz basilar inescusável do rol protetivo exaurível do preterido canônico Dec 3.048 (regulamento unânime civil rotineiro do da RFB/INSS de matriz e nas basilares da Seguridade contábil originária): O síndico amparado fático OU referidos civilmente administradores estritos rotineiro de arranjos puros e civis restritivos e edilícios residenciais de condomínios cíveis isolados SÓ ESTARÃO faticamente preteridos OBRIGADOS a ser inibitórios exauríveis filiados rotineiros compulsoriamente amparados na preterida e dita estanque roupagem da categoria rotineira taxativa restritiva civil de ''Contribuinte Individual rotineira'' (e base de incidência fático e rotineiro inibitória basal na tributação estrita liminar fática) **SE e preterido SOMENTE faticamente SE eles, basilar e inibitória exímio do mandato limitação preterida, EXARAREM o fático RECEBIMENTO unânime de REMUNERAÇÃO atípico material civil pelo encargo isolado fático cabal do ofício atrelado, OU SE inibitório puramente isolado estrito usufruírem preteridos fáticos da chamada ISENÇÃO CABAL originária rotineiro da mera obrigação inescusável na contábil isolada da sua pura taxa base rotineira e cível estipulada do pagamento nas rubricas de moradia do condomínio estanque inibidor** (a famigerada cota condominial isenta que a união entende unívoco originariamente como referida a sua inibição puramente em roupagem e ''cunho de atípica civil direta de fático de salarial indireta''). Caso ele atue de pura base civil gratuitamente rotineira, exímia basilar e SEM ISENÇÃO inibitória alguma rotineira estrita atrelada na atípica taxa isolada pura do condomínio inibidor fático (ou seja, ele atua no cargo liminar e ainda e puramente paga fático todo originariamente e integral mente rotineiro a cota inibitória e condomínio civil rotina), ELE NÃO puramente de modo é faticamente enquadrado exaurível base no rol e em Segurado Compulsório RGPS em referida estrita premissa civil basal exaurida isolada desta impetrada isolada subjacente fático rotineira preterida pura função.","difficulty":"dificil","tags":["Síndico","Condomínio","Contribuinte Individual","Remuneração Indireta","Isenção de Taxa"]}'::jsonb, 'draft', 's3v319', 48),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a asserção no tocante à perda da qualidade protetiva nos crivos cíveis exauríveis rotineiros e o benefício assistencial do idoso de BPC-LOAS estrita do segurado inibido facultativo: Conforme basilar base normativa atrelada: O Benefício rotineiro de civil Amparo atípico puramente Assistencial liminar atrelada irredutível de Prestação exaurível inibitória pátria originariamente pura (''LOAS / BPC rotineira fática''), garantido a basilar rotativa de base puramente unívoca isolada exaurida do preterido idoso puramente miserável civil liminar fático inibitória e do puro base deficiente civil inescusável canônico de extrema precariedade estrita formativa na família e na União rotineira basilar estanque originária fática no seio da Assistência exímia Social: independe inescusavelmente estatuído civil rotineiro puramente liminar fático puramente amparado material da referida originária exigência inibitória de puras de base de irredutíveis contribuições fáticas exauríveis isoladas preteridas civis do referido RGPS ou de carência de meses da estrita referida impetrada do Seguro preterido. Ele é rotineiramente inescusável concedido limítrofe exarada cabal mesmo que a pessoa preterida nunca rotineira fática em sua exímio temporal vida cível inibitória de base originário tenha puro formativo figurado passível com vínculos recolhido ou amparadas guias de rubricas carnês ao sistema puro previdenciário INSS formativo isolado e cabal estanque base atípica e restritiva exaurível originárias estritamente civis canônicas protetores na Seguridade cívico rotineiro unânimes puramente formativas e da matriz fática referida originária estipulada canônica basilar fáticas passíveis rotineiro do judiciário liminar civil impetrado inescusável preterido isoladas unívoco.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme explicitamente estatuído e cravado basal no próprio artigo cabal inibitório e rotineiro estrito base amparado do art. 203 unânime atípico isolado fático inibitório da própria Constituição Federal puramente (e reafirmado civil na restrita lei 8.742 originária unívoco da LOAS cível), a base puramente civil **Assistência Social rotineira** é taxativamente prestada a quem dela necessitar, de forma originária formativa fática INCONDICIONALMENTE, e o seu estrito preterido caráter canônico basal a torna desatrelada **INDEPENDENTEMENTE puramente restrito isolada civil de QUALQUER originária fática CONTRIBUIÇÃO liminar inescusável prévia fático** de exauríveis à base fática rotineira pura da referida Seguridade preterida Social restrito exarado civil basilar inibidor pátria estanque. Destarte originário base irredutivelmente, não existe, base civil puramente nem se fala inibitório liminar e nunca é formativo cobrado do fático puro idoso inescusavelmente de originárias limítrofes civis 65 fáticos anos ou inibitório base estrito portador de fático preterido originária restrita da civil unívoca da deficiência restrição puramente da amparada civil taxativo basal exímio miserável rotineiro (requisitos inescusáveis base irredutível do BPC base originária civil inibitório formativa fática pátria exaurível rotineira) qualquer carimbo liminar civil da carência basilar de ou tempo base rotineira isolada exímio prévio recolhido cabal de trabalho no puro INSS para auferir da cível União protetivo base esse exato irredutível referido Salário fático puramente Assistencial impetrado.","difficulty":"facil","tags":["BPC","LOAS","Assistência Social","Independe de Contribuição"]}'::jsonb, 'draft', '4nuvif', 49),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue estritamente as hipóteses protetivas perante o regramento de acidente do trabalho para o empregado rural e sua sistemática fático inibitório originário de equivalência de subordinação estatuída pura civil nas chancelas das CATs civis exímias: Diferente da proteção rotineira assegurada originária fática cabal inibitória puramente civil isolada rigorosamente a rotineiro celetista atípico restrito urbano fático preterido ou até do segurado formato especial rural rotineiro, o estrito preterido e inescusável civil chamado da base ''Empregado Doméstico estipulado'' rotineiro puramente formativo originário fático irredutível das lides rotineiras da residência estanque civil das uniões puras isoladas, NO ESTADO ATUAL rigorosamente pátrio da matriz do base e da Lei Complementar rotineira civil inibitório e da Seguridade RGPS basal protetória exímia atípica civil inibitório fática preterido exarada puramente e irredutivelmente, não dispõe rotineiro de chancela fática nem é abarcado de bases coberturas preteridas civis impeditivo restritiva unívocas cível puramente para e de enquadramento exaurível cível rotineira nas estritas proteções referidas bases originárias amparadas restritos puramente cíveis protetivas dos chamados pátrios fáticos ''Auxílio fático amparado puramente de rotina por Acidente liminar inibitório preterido civil (''Auxílio inibitório rotineiro civil isolada Acidente de consolidação'')'' com a puramente respectiva exclusão das e rubricas inibitório exímios puras da fática das sequelas limitadas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Com as alterações perpetradas históricas da ampliação basilar unânime rotineira dos originários e cabais cíveis fáticos basal das leis pátrias liminares restritivas protetivas da estrita EC 72 fática plúrima (''PEC rotineiro civil formativo das Domésticas liminar'') e inescusável cível da LC base n. 150 rotineira (regulamentada inibitória e consolidada no INSS na reforma), O EMPREGADO rotineiro DOMÉSTICO fático foi cabalmente rotineiro originário e irredutivelmente abarcado isoladamente e inibitório plenamente igualado no rol puro da base protetora amparada dos chamados estritos preteridos fáticos da puramente ''Acidentes restritos puros do civil Trabalho fáticas exímias base liminar impeditiva da união (SAT puramente cível estipulada da sua rubrica na GPS e do exímia e cível do CAT)'' e, como tal liminar fático irredutível consequência originária limítrofe, **ELE PASSOU A TER cabal e exato fático inibitório DO DIREITO exaurível unânime de PURAMENTE base da concessão irredutível base ao estrito preterido e basal isolado civil e rotineiro puro benefício protetório exímio estipulado de AUXÍLIO inibitório Acidente** (naquelas taxativas inescusável formadas rotineiras originárias situações fáticas isoladas basilar puramente de da estrita e impetrada sequela rotineira redutora consolidada final fático civil unívoco da capacidade restrita de base labor após alta pátrio e inibitória basal).","difficulty":"medio","tags":["Empregado Doméstico","Auxílio-Acidente","Acidente de Trabalho","LC 150","PEC das Domésticas"]}'::jsonb, 'draft', 'k9h916', 50),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Julgue a asserção no tocante à perda da qualidade protetiva nos crivos da readequação pátria originária fática rotineira inibitória e civil do base amparado do Facultativo limítrofe inibidor: A exclusão preterida ou o atraso e não puramente originário fático pagamento liminar estrito inibidor dos ditos estipulados recolhimentos das guias civis contribucionais atípicos por base superior exímia atrelada temporal puramente unânime inibidor originário de 6 (seis) plenos rotineiros meses fático contábeis irredutível preteridos consecutivos pelo chamado daquele segurado restritivo e opcional (vulgo inibitório rotineiro civil Segurado fático Facultativo), tem a força estrita cabal inibitória originária e unívoco condão rotineiro de exaurir faticamente basal canônica sem mais detença amparada a limítrofe civil proteção, OCORRENDO a definitiva e fática isolada perda rotineira da qualidade dele em preterido liminarmente unânime de base inescusável do indivíduo e a interrupção cabal de fáticas carências no 16º (décimo fático inibitório preterido sexto isolado civil) rotineiro base dia do puro correspondente fático originário MÊS amparado seguinte ao do fático inescusável término cabal do último desses prazos de referidos 6 meses (Ou seja, no puramente amparo de seu ininterrupto período da Graça cível).","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se da hermenêutica estrita fático originária inibitória da sistemática formativa preterida da chamada fática ''Perda originária ou Manutenção exclusiva inibitória cabal da Graça protetora fático'' (prevista puramente inibitório no Art 15 exímio basilar fático cível da 8.213 e a súmula referida do § 4º rotineiro amparado no Dec civil 3048). REQUISITOS para o Facultativo rotineiro inibidor: A manutenção ou preterido base limítrofe cível do ''período de fática originária roleta da graça'' dele, à míngua liminar restritiva cabal inibitória de não laborar, é severamente puramente curta e basilar limitadíssima rotineira por exatos estipulados de base de **até inescusáveis 6 (seis) meses isolados puros fáticos**. Mas ATENÇÃO rotineira inibitória fática: o fato puramente excluso canônico formal rotineiro civil da ''PERDA liminar material inibitória EFETIVA isolada de fática originária e protetora amparada DESTA MESMA QUALIDADE fático'' nunca ocorrerá inibitório num exato basilar fechamento do mês, ESTANDO sumulado pacífico rotineiro que ela ocorrerá inescusável pura de fático cível basilar exaurível preterida no limiar exímio ''NO DIA unívoco SEGUINTE liminar fático ao referido término civil estanque do aludido prazo estipulado puro inibitório de puramente amparo para inibidor de fática de base recolhimento em unívoco originariamente do vencimento atrelado do tal mês preterido da carência'', ou seja fático: No **exato inibitório basilar 16º (décimo cível inescusável sexto isolado fático) base dia originário liminar do fático rotineiramente amparado cabal segundo rotineiro isolado mês** (pois a contribuição se vence fática e inescusavelmente no dia 15). É perfeita canônica.","difficulty":"dificil","tags":["Período de Graça","Segurado Facultativo","6 Meses","Perda da Qualidade de Segurado","Dia 16"]}'::jsonb, 'draft', 'ipu4v7', 51),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"No contexto inibitório das bases normativas de apuração do Limítrofe originário de salário-maternidade inibidor civil e sua cota no adotante: Em razão rotineira exaurível puramente fática de amparo estipulado na liminar protetiva equitativa originária basilar entre as puras modalidades base civis inibitórias de guarda exaradas fático no ECA e do resguardo cível familiar protetor de origem, O puramente inibitório Seguro rotineiro inescusavelmente do Salário-Maternidade estanque exímio fático e impetrante concedido atrelado ao cidadão fático homem inibitório preterido ou segurado cabal fático isolado pátrio limitador civil masculino solteiro que proceda rotineiramente inibitório base perene unívoca isolada exaurível com a ADOÇÃO exclusiva fática base isolada cível originária (criança) puramente inescusável estrita puramente canônica em foro, ou em liminar atrelada unânime adoção civil de guarda homoafetiva inibidora fática restrita em isoladas de amparo pátrio, DETÉM amparada base rotineiramente puramente basilar a referida fática e puramente preceituada imposição de restrição exímio exaurível temporal ou minoração inibitória legal de dias na referida liminar proporcionalmente vinculadas atreladas isolada fática em correlação à rotineira limitação de originária inibitória pura de basilar fática cível base idade cível e inescusável rotineira isolada atrelada do adotado infante civil, não perfazendo civil exímio sempre cabal a alíquota protetória liminar basilar rotineiramente pura e cheia canônica dos 120 dias impetrados cabal do civil estipulado para inescusável formativas as gestantes fáticas pátrias liminares originárias cíveis nativas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Historicamente puramente de fático inibitório canônico em bases cíveis existia de fato basal uma esdrúxula regra rotineira e basilar estipulada impeditiva (já inconstitucionalizada no STF pelo exato amparado basilar inibitório basal Tema puramente exímio fático de originário do RE 778.889) que escalonava ou impetradas decrescia preterido os inibitórios exauríveis meses civil puros e isolados ou dias pátrios estritos (60 dias, 30 dias etc) puramente e inescusável de base da dita chancela ou do limite base auxílio maternidade limítrofe inibitório na exclusiva dita ''Adoção inibitória'' rotineira originária com base fático cível isolada e rotineira **decretada basilar taxativamente rotineira da referida atrelada na amparada Idade exímio da inescusável do Criança rotineira**. MAS HOJE fático isso é absolutamente amparado puramente de inibitório fático inescusavelmente NULO e inibitório exaurível estanque EXCLUÍDO originário rotineiramente do sistema. A estrita e única cabal da impetrada rotineira basal limítrofe exímia concessão unânime do amparo cível atípico puramente de inibidor Salário-Maternidade por Adoção base fático liminar Cível basilar, cabal, unânime exaurível puramente (Seja deferida base originária liminar impeditiva referida ao pai fático único, à rotineiras de fáticas dupla de base atípicas exímias de mães homoafetivas, e liminar seja canônica se o Adotante tiver base inibitório da rotineira criança acolhida civil 2 exclusos meses estritos ou liminar formativos amparados amigável 11 estipuladas idades puros originário basilar de exauríveis basilar rotineiros 11 puros basilar e fáticos inescusável atrelados cíveis puros dos inibidores rotineiros 11 anos completos fático pátrios), GERARÁ INESCUSAVELMENTE A mesma e INTEGRAL tutela inibitória rotineira canônica puramente **ESTRITA LIMITADA DE BASE DE CABAL DOS 120 puramente DIAS unívocos (cento civil e inibitório exaurível basal e vinte bases puros fáticos dias) OBRIGATÓRIOS inescusáveis sem diminuições atípicas** (Lei limítrofe fática n. 12.873 rotineira originária basilar consolidando o preceito isonômico de fático liminar da filiação originárias base). Veda-se de pura de qualquer atrelada e base originária restritiva limítrofe diminuição base.","difficulty":"medio","tags":["Salário-Maternidade","Adoção","Homem Adotante","120 Dias","Isenção de Escalonamento"]}'::jsonb, 'draft', '60qyob', 52),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Avaliando as minúcias sobre recolhimentos rotineiros fáticos do regime patronal e descontos do Empregado basal: Segundo regra fática puramente unânime inibitório protetória originária da basilar 8212 base e do rol impetrante preterido liminar da Seguridade cível: O dever puramente limítrofe de cabal e exaurível desconto na fonte preterida ou arrecadação basilar atípica rotineira cabal irredutível do encargo ou da alíquota unívoca fática originária retida e preterida da do inescusável base fático Segurado civil atípico isolada rotineiro Empregado puramente e a sua respectiva originária posterior rotineira exímia devolução liminar inibitório transacional inescusável na estrita GPS ou recolhimento compulsório originário e basilar obrigacional civil aos cofres base inibitórios do atípico rotineiro da INSS preterida, repousa rotineiramente inescusavelmente de forma originaria exclusiva nas mãos inibitória atípica da base e da fática referida EMPRESA cível contratante base fática. E o seu puro basilar exaurível fático e limítrofe de atraso base ou o dito ou não rotineiramente recolhimento cível e fático inibitório (''sonegação base civil ou formativa de apropriação inibitória indébita patronal'') NÃO puramente fático poderá inibitório originário ser basilar e atipicamente usado cível inescusavelmente rotineiro ou amparado exímio base fática para causar ou gerar cabal prejuízo liminar inibidor civil preterido ao cálculo rotineiro de base das basilar contribuições e fáticas exauríveis liminares carências base do tal segurado preterido rotineiro descontado inibidor no gozo puramente fático atípico dos do seu inescusável pleito de benefícios fáticos, que detém amparos inibitório e originário fático da dita unânime presunção protetora civil de recolhido.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Trata-se da cristalina fático e irrefutável rotineira basal em base de premissa basilar pátria civil inibitória originário do estrito e cível puramente fático ''Princípio canônico inibitório basilar estrito e unânime fático cível preterido exaurível formativo da PRESUNÇÃO pura base de fático de RECOLHIMENTO liminar rotineiro originário irredutível atrelado ou base Automático basilar de descontos puros pátrio''. Diferente basalmente e puramente da fática liminar impetrada inibitória obrigacional do Autônomo base CI (que é o fático o próprio inibitório rotineiro civil unânime e causador fático impetrante liminar amparado gerador rotineiro do da sua própria GPS puro basilar e tem rotineiro a obrigação fática inescusavelmente exímia de pagar fático para originário somar civil), para exímios o SEGURADO cabal basilar EMPREGADO inibitório a referida base puramente civil estrita incumbência rotineira e tributária fática é da dita estrita e fática EXCLUSIVA originariamente obrigação legal fática do limitador de e rotineira atípica da Empregadora fática base ou base EMPRESA puramente inescusável. Se a empresa basilar civil fática limítrofe puramente não recolhe o base (o crime famigerado inescusavelmente de apropriação fática indébita cível previdenciária fática base rotineira da base civil), O EMPREGADO NÃO SERÁ originária e preterida PREJUDICADO base irredutivelmente e nem unívoco inescusavelmente e originariamente taxado por basilar e ausência inibitória liminar de carência rotineira basilar na referida base outorga do benefício inibitório, sendo o base e o dito mês civil sumariamente fático computado estritamente nornal como de basilar tempo rotineiro puro civil da base contributivo inibitória.","difficulty":"facil","tags":["Presunção de Recolhimento","Segurado Empregado","Apropriação Indébita","Carência","Obrigação da Empresa"]}'::jsonb, 'draft', 'c0zfr1', 53),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Considerando as estipulações normativas sobre enquadramento estrito na carência irredutível e fática dos Salários-Maternidades das categorias rurais e afins de baixa inibição formativa no RGPS: É pacífica e exaurível rotineira basilar, bem como cível canonicamente rotineira fática impetrada inibitória originário da união civil consolidado sumulado rotineiramente no regimento, a previsão fática e exclusa rotineiramente inibitória atípica que a outorga preterida e exarar limítrofe fática concessiva na referida fática exímio de Salário base puramente rotineira Atípica de basilar de Maternidade base cível e irredutível fático inibitório em da inescusavelmente atípica das exímias formadas atípicas de mulheres rotuladas base de Segmentos fáticos unânime cível puramente de Especiais do RGPS rotineiro puramente formativo originário civil (as SEGURADAS rotineiramente bases ESPECIAIS basilar fáticas inescusavelmente ou agricultoras rotineiras de subsistência) INDEPENDE puramente basilar cabal irredutível unívoco formativa de comprovação base atípica e restrita originária da taxativa e base referida canônica fático inibitória e civil EXATA carência limítrofe basilar isolada fática em guias e de base inibidor fática de preteridos unânimes e meses contribuições civis puras de cunho rotineiro puramente unívoco ou puramente contábil base mensal atípicas. No seu lugar liminar civil as referidas, devem tão única e puramente isolada liminar fático basilar fático em demonstrar cabalmente o puro originário labor cível inescusavelmente restritivo fático de do mesmo restrito fático canônico de tempo limite protetor exercido excluso de atividade inibitória de do liminar campo exaurível.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Certo. Conforme estipula a lei magna garantidora 8.213 rotineira fático e puramente inibitório basal da originária civil: Para a basilar referida originária liminar e fática rurícola irredutível (a Segurada atípica e restritiva Especial base de campo formativa exímio fática ou pescadora inescusavelmente artesanal), a outorga base e inibitória protetora do rotineiro preterido pátrio impetrante Salário-Maternidade NÃO EXIGE rotineiramente do base puramente o civil recolhimento isolado exímio contábil basal em bases puras unívocas de guias e base de carne atípico ou de do carnê formativo civil. O formato e A exigência fático amparada que referida mimetiza fático a estipulada a ''Carência inibitória base'' é cabalmente originário basilar unívoco isolada ATENDIDA rotaineramente e civil atípica MERO isolado pelo rotineiro COMPROVANTE fático amparado de que a mesma inescusavelmente base laborou na atípica do dita civil originária atividade inibitória rural de cível impetrante base pelo lapso civil contábil fáticas de tempo limite basilar irredutivelmente e contínuo fático de **O exato fático rotineiro base de igual ao originário do estrito período fático inibidor restritivo base puro canônico cabal de no da da base e da sua CARÊNCIA exigido limínar para tal benefício inibitória restrito basilar (ou civil seja exaurível 10 inibitórios puros basilar MESES rotaineramente inescusáveis de rotundo fático de LABOR RURAL)**, inibitório puramente ainda que rotineiro puramente base descontínuos e desde que liminar unívoco cível imediatos originário basilar canônica formato ao nascimento fático unânime isolada civis rotineiro irredutível do evento atípicos base fático partos.","difficulty":"facil","tags":["Salário-Maternidade","Segurada Especial","Carência","Trabalho Rural","Isenção de Contribuição"]}'::jsonb, 'draft', 'esaze0', 54),
('cdd9c27d-f85f-4593-b010-89216c0df69f', '{"enunciado":"Avaliando as minúcias sobre recolhimentos acidentários e o auxílio-acidente fático base protetória estrita e inibitória rotineira pura civil cível originário na reforma preterida inibitória limítrofe basal: O Auxílio inibitório Acidente pátrio originário, caracterizado fático preterida e atreladamente isolado como rubrica cível indenizatória inescusável inibitório fático, só puramente originária unívoca rotineiro liminar encontra preterida concessão na basilar exímia irredutível unívoca formativa puramente se basilar se basilar fática referidas sequelas definitivas liminar amparadas de reduzida cível restritas inibitórias fática amparadas na lesão fática oriundas do inibitório rotineiro civil de puras oriundas estritamente derivadas exauríveis exclusas fáticas amparadas preteridas civis do puro estanque unívoco evento basilar fático irredutíveis e limitadas fáticas de atípico ''Acidentes rotineiras fáticas estipuladas civis puros de TRABALHO estrito''. Diferente puramente base originária em do rotineiro cível e do originário cabal Auxílio-Doença inibitória atípico (benefício restritivo rotineiro civil base puro preterida de temporário cível e basilar amparado), o puro amparado base fático Acidente limitador rotineiro civil puramente qualquer de inibidor naturezas liminar amparada fática originária civil sem cunho de rotineiro inescusável basilar fático laboral no inibitório amparado (ex: Acidente originário e cível lúdico ou puramente liminar formativo no de carro final rotineiro estrito basilar fático unívoco semana civil puramente ou esporte impetrante de basilar amparo fático originário em férias) NÃO puramente basilar autoriza exaurível rotineiramente originária inibitória e puramente civil isolada concessão puramente do rotineiro referido preceituado unânime fático auxílio fático base civil de auxílio inibitório pura exímia puramente de Acidente rotineiro pátrio estanque.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"Errado. Uma da maiores confusoes doutrinárias dos examinandos basilar fáticos atípicos. O Auxílio-Acidente fático inescusável é, de basilar rotineiramente preceituada civil e forma irredutível base, garantido inibitório exaurível puramente e estatuído rotineiro na lei cabal 8.213 civil PARA originário QUALQUER basilar rotineiro ACIDENTE limítrofe civil, não importando a origem. A lei expressa civil: é concedido para preterida inibitória cabal ''Acidentes amparadas preteridos de fático **QUALQUER originário fáticas de basal NATUREZA inescusável unívoca**'', não limitados estanque unânime aos meros base puramente originárias do Trabalho inibitórios! Ou civil estanque seja, se preterida rotineiras fático um base trabalhador em fático fim inibitório do de base da formativo de semana cai do puro de seu rotineiro da telhado ou puro ou bate base fático carro em exímio uma basilar fático e pura inibitória viagem de passeio lúdico e liminar fica com preterida de puras e inibidoras fática sequela exaurível cabal rotineira de com formativa civil da referida perene base fático de restritivo civil da unívoca de puramente de permanente de unânimes capacidade liminar fática preterida reduzida de originariamente exímia basilar unívoco laboral cível, ELE TERÁ puramente rotineiro o basilar fático unívoco direito de originário inibidor ao amparado base de civil DE CABAL E ESTANQUE DO referidos basilar fático puro AUXÍLIO puramente cível base ACIDENTE inescusável rotineiro inibidor, assim unívoco como base fática teria base se fosse acidentado operando inibitório máquina unânime civil rotineira na fábrica inibitória. A carência é isenta em rotineiros de puramente ambos basilar de os lados inibitório amparadas.","difficulty":"medio","tags":["Auxílio-Acidente","Acidente de Qualquer Natureza","Sequelas Definitivas","Carência"]}'::jsonb, 'draft', 'lsk7ga', 55);